INSERT INTO `job` VALUES
(255,44,1,2,'Dělník/ce v potravinářské výrobě','Klatovy - 5. května 112','<p>&bull; Z&aacute;kladn&iacute; vzděl&aacute;n&iacute;, popř. SO a dal&scaron;&iacute;, možnost za&scaron;kolen&iacute;<br>&bull; Zodpovědnost, chuť se učit nov&yacute;m věcem<br>&bull; Zdravotn&iacute; stav bez omezen&iacute;<br>&bull; Tř&iacute;směnn&yacute; provoz<br>&bull; N&aacute;stup možn&yacute; ihned</p>','<p>- pr&aacute;ci ve zdrav&eacute; a perspektivn&iacute; společnosti s dlouholetou tradic&iacute;</p>\r\n<p>- možnost pracovn&iacute;ho postupu</p>\r\n<p>- preferujeme dlouhodob&eacute; pracovn&iacute; smlouvy</p>\r\n<p>- db&aacute;me na vysokou bezpečnost pr&aacute;ce &ndash; jsme držiteli certifik&aacute;tu &bdquo;Bezpečn&yacute; podnik&ldquo;</p>\r\n<p>- zaměstnance vybavujeme pracovn&iacute;m oblečen&iacute;m a ochrann&yacute;mi pomůckami</p>\r\n<p>- možnost čerpat &scaron;irokou &scaron;k&aacute;lu benefitů</p>','<p>13. plat, Bonusy/pr&eacute;mie</p>\r\n<p>Dovolen&aacute; 5 t&yacute;dnů</p>\r\n<p>Pracovn&iacute; oblečen&iacute;</p>\r\n<p>Př&iacute;spěvek na dopravu</p>\r\n<p>Př&iacute;spěvek na dovolenou</p>\r\n<p>Př&iacute;spěvek na penzijn&iacute;/životn&iacute; připoji&scaron;těn&iacute;</p>\r\n<p>&nbsp;Př&iacute;spěvek na sport/kulturu/voln&yacute; čas</p>\r\n<p>Z&aacute;vodn&iacute; stravov&aacute;n&iacute;</p>'),
(258,44,1,3,'Pracovník údržby','Klatovy - 5. května 112','<p>Typ &uacute;vazku - Pr&aacute;ce na pln&yacute; &uacute;vazek<br>Typ smluvn&iacute;ho vztahu - pracovn&iacute; smlouva<br>D&eacute;lka pracovn&iacute;ho poměru - Na dobu neurčitou<br>Požadovan&eacute; vzděl&aacute;n&iacute; - Odborn&eacute; vyučen&iacute; bez maturity</p>','<p>&bull; vzděl&aacute;n&iacute; SO popř. &Uacute;SO<br>technick&eacute;ho směru<br>&bull; praxe v&iacute;t&aacute;na, absolventy<br>za&scaron;kol&iacute;me<br>&bull; dobr&yacute; zdravotn&iacute; stav<br>&bull; směnn&yacute; provoz<br>&bull; spolehlivost, zodpovědnost,<br>flexibilita<br>&bull; Seř&iacute;zen&iacute; a &uacute;držba strojů<br>a zař&iacute;zen&iacute;<br>&bull; Zji&scaron;těn&iacute; př&iacute;čin poruch<br>a probl&eacute;mů na strojn&iacute;m<br>zař&iacute;zen&iacute;<br>&bull; Veden&iacute; z&aacute;znamů o preventivn&iacute;<br>&uacute;držbě<br>&bull; Budete poskytovat podporu<br>při přestavbě v&yacute;robn&iacute;ch linek<br>&bull; Spolupr&aacute;ce při optimalizaci<br>procesů ve v&yacute;robě</p>','<p>- náborový příspěvek do výše 20 000 Kč<br>- poukázky na zvýhodněný nákup našich výrobků<br>&nbsp; &nbsp;závodní stravování s výrazným příspěvkem&nbsp; &nbsp; &nbsp; &nbsp;zaměstnavatele<br>- 5 týdnů dovolené<br>- roční odměny<br>- př&iacute;spěvek na ubytov&aacute;n&iacute; pro zaměstnance mimo&nbsp; region<br>- příspěvek na penzijní připojištění<br>- příspěvek na dopravu do zaměstnání a zpět<br>- jednorázový bonus na dovolenou 3 000 Kč<br>věrnostní bonus za odpracované roky<br>příspěvky ze sociálního fondu na kulturní, sportovní<br>a vzdělávací akce ve výši 2 000 Kč a na dovolenou 2 000 Kč</p>'),
(259,44,1,3,'Předák výrobního provozu','Klatovy - 5. května 112','<p>Typ &uacute;vazku - Pr&aacute;ce na pln&yacute; &uacute;vazek<br>Typ smluvn&iacute;ho vztahu - pracovn&iacute; smlouva<br>D&eacute;lka pracovn&iacute;ho poměru - Na dobu neurčitou<br>Požadovan&eacute; vzděl&aacute;n&iacute; - Odborn&eacute; vyučen&iacute; bez maturity</p>','<p>-&nbsp; SO popř. &Uacute;SO potravin&aacute;řsk&eacute; obory v&yacute;hodou</p>\r\n<p>- zku&scaron;enosti s veden&iacute;m pracovn&iacute;ho kolektivu, koordinace v&yacute;roby</p>\r\n<p>- flexibilita, komunikativnost, zodpovědnost</p>\r\n<p>- znalost pr&aacute;ce na PC</p>\r\n<p>- zdravotn&iacute; stav bez omezen&iacute;</p>\r\n<p>- tř&iacute;směnn&yacute; provoz</p>','<p>- n&aacute;borov&yacute; př&iacute;spěvek do v&yacute;&scaron;e 20 000 Kč<br>- pouk&aacute;zky na zv&yacute;hodněn&yacute; n&aacute;kup na&scaron;ich v&yacute;robků<br>- z&aacute;vodn&iacute; stravov&aacute;n&iacute; s v&yacute;razn&yacute;m př&iacute;spěvkem zaměstnavatele<br>- ročn&iacute; odměny<br>- př&iacute;spěvek na penzijn&iacute; připoji&scaron;těn&iacute;<br>- př&iacute;spěvek na dopravu<br>- jednor&aacute;zov&yacute; bonus na dovolenou 3 000 Kč<br>- věrnostn&iacute; bonus za odpracovan&eacute; roky<br>- odměna za doporučen&iacute; nov&eacute;ho zaměstnance je do v&yacute;&scaron;e 10 000kč<br><br></p>'),
(260,44,1,2,'Řidič pro rozvoz hotových výrobků','Klatovy - 5. května 112','<p>Typ &uacute;vazku - Pr&aacute;ce na pln&yacute; &uacute;vazek<br>Typ smluvn&iacute;ho vztahu - pracovn&iacute; smlouva<br>D&eacute;lka pracovn&iacute;ho poměru - Na dobu neurčitou<br>Požadovan&eacute; vzděl&aacute;n&iacute; - Z&aacute;kladn&iacute;</p>','<p>&nbsp;- ř&iacute;zen&iacute; vozidel skupiny C &ndash; na vozidlo IVECO do 6,5t</p>\r\n<p>- profesn&iacute; průkaz</p>\r\n<p>- karta řidiče</p>\r\n<p>- zdravotn&iacute; stav bez omezen&iacute;</p>\r\n<p>- spolehlivost, komunikativnost</p>','<p>- n&aacute;borov&yacute; př&iacute;spěvek do v&yacute;&scaron;e 20 000 Kč<br>- pouk&aacute;zky na zv&yacute;hodněn&yacute; n&aacute;kup na&scaron;ich v&yacute;robků<br>- z&aacute;vodn&iacute; stravov&aacute;n&iacute; s v&yacute;razn&yacute;m př&iacute;spěvkem zaměstnavatele<br>- ročn&iacute; odměny<br>- př&iacute;spěvek na penzijn&iacute; připoji&scaron;těn&iacute;<br>- př&iacute;spěvek na dopravu<br>- jednor&aacute;zov&yacute; bonus na dovolenou 3 000 Kč<br>- věrnostn&iacute; bonus za odpracovan&eacute; roky<br>- odměna za doporučen&iacute; nov&eacute;ho zaměstnance je do v&yacute;&scaron;e 10 000kč<br><br></p>'),
(266,67,1,1,'Lakýrník','Dýšina ','<p>Př&iacute;prava barvy dle specifikace a nan&aacute;&scaron;en&iacute; barvy dle specifikace za mokra.<br><br></p>','<p><strong>M</strong>anu&aacute;ln&iacute; zručnost, ochotu učit se nov&yacute;m věcem,&nbsp;<br>znalost v&yacute;robn&iacute; a v&yacute;kresov&eacute; dokumentace.</p>','<p>Motivuj&iacute;c&iacute; platov&eacute; ohodnocen&iacute;,<br>5 t&yacute;dnů dovolen&eacute;,<br>zvy&scaron;ov&aacute;n&iacute; kvalifikace,<br>z&aacute;zem&iacute; siln&eacute;ho mezin&aacute;rodn&iacute;ho koncernu,<br>př&iacute;spěvek na stravov&aacute;n&iacute; a dopravu,<br>př&iacute;spěvek na ubytov&aacute;n&iacute; dle intern&iacute;, směrnice společnosti,<br>ubytov&aacute;n&iacute; ve firemn&iacute; ubytovně př&iacute;mo v are&aacute;lu firmy,<br>ročn&iacute; odměny, věrnostn&iacute; odměny<br>po ZD př&iacute;spěvek 500,- Kč/měs&iacute;c na penzijn&iacute; nebo životn&iacute; poji&scaron;těn&iacute;,<br>MultiSport karta&nbsp;</p>'),
(269,67,1,1,'Zámečník - svářeč ','Dýšina ','<p>Budete u n&aacute;s sestavovat a svařovat dle v&yacute;kresov&eacute; dokumentace, zhotovovat souč&aacute;sti z plechů a profilů z oceli, kontrolovat proveden&eacute; sv&aacute;ry a dodržovat pravidla kvality a&nbsp;<br>dodržovat nastaven&aacute; pravidla z oblasti BOZP.</p>','<p>Sv&aacute;řečsk&yacute; průkaz,<br>nutn&eacute; zku&scaron;enosti se svařov&aacute;n&iacute;m CO2,&nbsp;&nbsp;<br>orientaci ve v&yacute;kresov&eacute; dokumentaci,<br>samostatnost, zodpovědnost, zručnost a pečlivost.&nbsp;</p>','<p>V prvn&iacute;ch dnech po Va&scaron;em n&aacute;stupu se V&aacute;s ujmou na&scaron;i &scaron;kolitel&eacute;. Budete sezn&aacute;men s firmou a umožn&iacute;me V&aacute;m př&iacute;padn&eacute; roz&scaron;&iacute;řen&iacute; sv&aacute;řečsk&eacute; certifikace.<br>Užijete si 25 dn&iacute; zasloužen&eacute; dovolen&eacute;<br>odměn&iacute;me V&aacute;s za věrnost a loajalitu,<br>přispějeme V&aacute;m na ubytov&aacute;n&iacute;,<br>přispějeme V&aacute;m na penzijn&iacute; připoji&scaron;těn&iacute;<br>tak&eacute; na dopravu a stravov&aacute;n&iacute;.<br>Z&uacute;častn&iacute;te se firemn&iacute;ch akc&iacute; a<br>dle pracovn&iacute;ch v&yacute;sledků můžete obdržet mimoř&aacute;dn&eacute; pr&eacute;mie a nav&yacute;&scaron;en&iacute; mzdy</p>'),
(270,67,1,1,'Programátor/programátorka svařovacího robota','Dýšina ','<p>Programov&aacute;n&iacute; svařovac&iacute;ho robota, vytv&aacute;řen&iacute; programů offline a online dle v&yacute;robn&iacute; dokumentace, &uacute;zce spolupracovat s ostatn&iacute;mi oddělen&iacute;mi, spolupod&iacute;let se na pr&aacute;ci na projektech, ř&iacute;dit se pravidly BOZP a PO.</p>','<p>Praxi jako obsluha robota CLOOS nebo REIS, př&iacute;padně jako technolog,<br>znalost v&yacute;robn&iacute; a v&yacute;kresov&eacute; dokumentace,<br>znalost/praxe ve svařov&aacute;n&iacute;,<br>z&aacute;klady někter&eacute;ho z programovac&iacute;ch jazyků (Cloos, Valk Welding) &nbsp;&ndash; v&yacute;hodou<br>modelov&aacute;n&iacute; 3D v&yacute;hodou,<br>spolehlivost, pečlivost, ochotu učit se nov&yacute;m věcem.</p>','<p>Motivuj&iacute;c&iacute; platov&eacute; ohodnocen&iacute;<br>5 t&yacute;dnů dovolen&eacute;,&nbsp;zvy&scaron;ov&aacute;n&iacute; kvalifikace,<br>z&aacute;zem&iacute; siln&eacute;ho mezin&aacute;rodn&iacute;ho koncernu,<br>př&iacute;spěvek na stravov&aacute;n&iacute; a dopravu<br>př&iacute;spěvek na ubytov&aacute;n&iacute; dle intern&iacute; směrnice společnosti,<br>ubytov&aacute;n&iacute; ve firemn&iacute; ubytovně př&iacute;mo v are&aacute;lu firmy,<br>ročn&iacute; odměny, věrnostn&iacute; odměny<br>po ZD př&iacute;spěvek 500,- Kč/měs&iacute;c na penzijn&iacute; nebo životn&iacute; poji&scaron;těn&iacute;,<br>MultiSport karta.&nbsp;</p>'),
(272,71,1,5,'IT PROJEKTOVÝ MANAŽER','Bor u Tachova','<ul>\r\n<li>Pod&iacute;len&iacute; se na veden&iacute; projektů za IT oddělen&iacute;</li>\r\n<li>Spolupr&aacute;ce při tvorbě projektov&eacute; dokumentace</li>\r\n<li>V&yacute;voj a implementace konkr&eacute;tn&iacute;ch n&aacute;vrhů ře&scaron;en&iacute;</li>\r\n<li>Podpora cel&eacute;ho procesu specifikace požadavků</li>\r\n<li>Prov&aacute;děn&iacute; testov&aacute;n&iacute; a opatřen&iacute; k zaji&scaron;těn&iacute; kvality projektu</li>\r\n<li>Tvorba anal&yacute;z a pl&aacute;nov&aacute;n&iacute; &uacute;prav</li>\r\n</ul>','<ul>\r\n<li>Min. S&Scaron; vzděl&aacute;n&iacute;</li>\r\n<li>V&iacute;celetou zku&scaron;enost v IT oboru, nejl&eacute;pe v logistick&eacute; společnosti</li>\r\n<li>Pokročilou zku&scaron;enost s veden&iacute;m projektů nebo alespoň s participac&iacute; na nich</li>\r\n<li>Plynulou znalost NJ</li>\r\n<li>Proz&aacute;kaznicky orientovan&yacute; př&iacute;stup</li>\r\n<li>Analytick&eacute; a koncepčn&iacute; schopnosti</li>\r\n</ul>','<ul>\r\n<li>Zaj&iacute;mavou a zodpovědnou činnost v ekonomicky zdrav&eacute;, modern&iacute; rodinn&eacute; společnosti s plochou hierarchickou strukturou</li>\r\n<li>Př&iacute;jemn&eacute; pracovn&iacute; prostřed&iacute; a dobr&yacute; kolektiv</li>\r\n<li>Stabiln&iacute; a dlouhodobou spolupr&aacute;ci</li>\r\n<li>Motivuj&iacute;c&iacute; finančn&iacute; ohodnocen&iacute;</li>\r\n<li>Ročn&iacute; bonus až do v&yacute;&scaron;e 100% měs&iacute;čn&iacute; mzdy</li>\r\n<li>Př&iacute;spěvek na stravov&aacute;n&iacute;</li>\r\n<li>5 t&yacute;dnů dovolen&eacute;</li>\r\n<li>2x t&yacute;dně home office</li>\r\n<li>Flexibiln&iacute; pracovn&iacute; dobu</li>\r\n<li>Firemn&iacute; kant&yacute;nu</li>\r\n<li>&Scaron;kolen&iacute; a vzděl&aacute;v&aacute;n&iacute; včetně jazykov&yacute;ch kurzů v r&aacute;mci pracovn&iacute; doby</li>\r\n<li>Zv&yacute;hodněn&eacute; mobiln&iacute; tarify</li>\r\n<li>Odměnu za doporučen&iacute; nov&eacute;ho zaměstnance</li>\r\n<li>N&aacute;stup ihned nebo dle domluvy</li>\r\n</ul>'),
(275,46,1,5,'VEDOUCÍ PROJEKTU (m/ž)','Plzeň','<p><strong>Pro pos&iacute;len&iacute; na&scaron;eho t&yacute;mu v pozemn&iacute;, silničn&iacute;, mostn&iacute; a železničn&iacute; divizi hled&aacute;me kolegu/yni na pozici vedouc&iacute;ho projektu (m/ž).</strong></p>\r\n<p><strong>N&aacute;plň pr&aacute;ce:</strong></p>\r\n<ul>\r\n<li>ř&iacute;zen&iacute; a odpovědnost za dan&yacute; projekt</li>\r\n<li>veden&iacute; cel&eacute;ho t&yacute;mu pro dan&yacute; projekt</li>\r\n<li>jedn&aacute;n&iacute; s investorem a subdodavateli</li>\r\n<li>spolupr&aacute;ce s technick&yacute;m dozorem investora</li>\r\n<li>dodržen&iacute; harmonogramu realizace stavby</li>\r\n<li>odpovědnost za kvalitu prov&aacute;děn&yacute;ch prac&iacute;</li>\r\n<li>kontrola proveden&eacute; pr&aacute;ce</li>\r\n<li>kontrola dodržov&aacute;n&iacute; BOZP</li>\r\n<li>pr&aacute;ce s technickou dokumentac&iacute;</li>\r\n</ul>','<ul>\r\n<li>S&Scaron;/V&Scaron; vzděl&aacute;n&iacute; stavebn&iacute;ho směru</li>\r\n<li>zku&scaron;enosti podm&iacute;nkou</li>\r\n<li>řidičsk&yacute; průkaz sk. B</li>\r\n<li>spolehlivost</li>\r\n</ul>','<ul>\r\n<li>jistotu u prosperuj&iacute;c&iacute; firmy se zahraničn&iacute;&nbsp; &nbsp; &nbsp; &nbsp; &uacute;čast&iacute;</li>\r\n<li>pracovn&iacute; m&iacute;sto v nov&eacute; administrativn&iacute;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; budově</li>\r\n<li>odpov&iacute;daj&iacute;c&iacute; mzdov&eacute; ohodnocen&iacute;</li>\r\n<li>možnost ročn&iacute;ch pr&eacute;mi&iacute;</li>\r\n<li>stravenkov&yacute; pau&scaron;&aacute;l</li>\r\n<li>možnost př&iacute;spěvku na doplňkov&eacute; penzijn&iacute; spořen&iacute;</li>\r\n<li>25 dnů dovolen&eacute;</li>\r\n<li>notebook, mobiln&iacute; telefon, os. automobil i k soukrom&yacute;m &uacute;čelům</li>\r\n<li>pravideln&eacute; &scaron;kolen&iacute; a vzděl&aacute;v&aacute;n&iacute;</li>\r\n<li>v&yacute;uku NJ na pracovi&scaron;ti</li>\r\n<li>pravideln&eacute; teambuildingy</li>\r\n<li>firemn&iacute; slevy</li>\r\n</ul>'),
(276,46,1,3,'STAVBYVEDOUCÍ (m/ž)','Plzeň, stavby ČR','<p><strong>Pro pos&iacute;len&iacute; na&scaron;eho t&yacute;mu v pozemn&iacute;, silničn&iacute;, mostn&iacute; a železničn&iacute; divizi hled&aacute;me kolegu/yni na pozici stavbyvedouc&iacute;ho (m/ž).</strong></p>\r\n<p><strong>N&aacute;plň pr&aacute;ce:</strong></p>\r\n<ul>\r\n<li>ř&iacute;zen&iacute; stavby v m&iacute;stě realizace</li>\r\n<li>kontrola proveden&eacute; pr&aacute;ce subdodavatele</li>\r\n<li>kontrola dodržov&aacute;n&iacute; BOZP</li>\r\n<li>odpovědnost za kvalitu prov&aacute;děn&yacute;ch prac&iacute;</li>\r\n<li>dodržen&iacute; harmonogramu realizace stavebn&iacute;ch prac&iacute;</li>\r\n<li>pr&aacute;ce s technickou dokumentac&iacute;</li>\r\n<li>spolupr&aacute;ce s technick&yacute;m dozorem investora</li>\r\n</ul>','<ul>\r\n<li>SOU/S&Scaron; vzděl&aacute;n&iacute; stavebn&iacute;ho směru nebo praxe v oboru</li>\r\n<li>řidičsk&yacute; průkaz sk. B</li>\r\n<li>spolehlivost</li>\r\n</ul>','<ul>\r\n<li>jistotu u prosperuj&iacute;c&iacute; firmy se zahraničn&iacute; &uacute;čast&iacute;</li>\r\n<li>odpov&iacute;daj&iacute;c&iacute; mzdov&eacute; ohodnocen&iacute;</li>\r\n<li>možnost ročn&iacute;ch pr&eacute;mi&iacute;</li>\r\n<li>stravenkov&yacute; pau&scaron;&aacute;l</li>\r\n<li>možnost př&iacute;spěvku na doplňkov&eacute; penzijn&iacute; spořen&iacute;</li>\r\n<li>25 dnů dovolen&eacute;</li>\r\n<li>notebook, mobiln&iacute; telefon</li>\r\n<li>v&yacute;uku NJ na pracovi&scaron;ti</li>\r\n<li>pravideln&eacute; &scaron;kolen&iacute; a vzděl&aacute;v&aacute;n&iacute;</li>\r\n<li>možnost ubytov&aacute;n&iacute;</li>\r\n<li>pravideln&eacute; teambuildingy</li>\r\n<li>firemn&iacute; slevy</li>\r\n</ul>'),
(277,46,1,3,'MISTR STAVBY (m/ž)','stavby ČR','<p><strong>Pro pos&iacute;len&iacute; na&scaron;eho t&yacute;mu v pozemn&iacute;, mostn&iacute;, silničn&iacute; a železničn&iacute; divizi hled&aacute;me kolegu/yni na pozici mistra stavby (m/ž).</strong></p>\r\n<p><strong>N&aacute;plň pr&aacute;ce:&nbsp; &nbsp; &nbsp; </strong>&nbsp;</p>\r\n<ul>\r\n<li>ř&iacute;zen&iacute; svěřen&eacute;ho &uacute;seku v m&iacute;stě realizace</li>\r\n<li>kontrola proveden&eacute; pr&aacute;ce subdodavatelů</li>\r\n<li>odpovědnost za kvalitu prov&aacute;děn&yacute;ch prac&iacute;</li>\r\n<li>dodržov&aacute;n&iacute; BOZP</li>\r\n<li>pr&aacute;ce s technickou dokumentac&iacute;</li>\r\n<li>spolupr&aacute;ce s technick&yacute;m dozorem</li>\r\n</ul>','<ul>\r\n<li>SOU/S&Scaron; vzděl&aacute;n&iacute; stavebn&iacute;ho směru nebo praxe v oboru</li>\r\n<li>řidičsk&yacute; průkaz sk. B</li>\r\n<li>z&aacute;kladn&iacute; znalost PC (Outlook, Word, Excel)</li>\r\n<li>vhodn&eacute; i pro absolventy</li>\r\n<li>spolehlivost</li>\r\n</ul>','<ul>\r\n<li>jistotu u prosperuj&iacute;c&iacute; firmy se zahraničn&iacute; &uacute;čast&iacute;</li>\r\n<li>odpov&iacute;daj&iacute;c&iacute; mzdov&eacute; ohodnocen&iacute;</li>\r\n<li>možnost ročn&iacute;ch pr&eacute;mi&iacute;</li>\r\n<li>stravenkov&yacute; pau&scaron;&aacute;l</li>\r\n<li>možnost př&iacute;spěvku na doplňkov&eacute; penzijn&iacute; spořen&iacute;</li>\r\n<li>25 dnů dovolen&eacute;</li>\r\n<li>pravideln&eacute; &scaron;kolen&iacute; a vzděl&aacute;v&aacute;n&iacute;</li>\r\n<li>možnost ubytov&aacute;n&iacute;</li>\r\n<li>firemn&iacute; slevy</li>\r\n</ul>'),
(279,46,1,5,'ASISTENT VEDOUCÍHO PROJEKTU (m/ž)','Plzeň','<p><strong>Pro pos&iacute;len&iacute; na&scaron;eho t&yacute;mu v pozemn&iacute;, silničn&iacute;, mostn&iacute; a železničn&iacute; divizi hled&aacute;me kolegu/yni na pozici asistenta vedouc&iacute;ho projektu (m/ž).</strong></p>\r\n<p><strong>N&aacute;plň pr&aacute;ce:</strong></p>\r\n<ul>\r\n<li>spolupr&aacute;ce na koordinaci stavby a jej&iacute;m materi&aacute;lov&eacute;m zaji&scaron;těn&iacute;</li>\r\n<li>tvorba změnov&yacute;ch listů &ndash; kalkulace v&iacute;ceprac&iacute;/ cenov&eacute; kalkulace, tvorba v&yacute;kazů v&yacute;měr</li>\r\n<li>tvorba časov&yacute;ch a finančn&iacute;ch harmonogramů stavby, zji&scaron;ťovac&iacute;ch protokolů &ndash; fakturace</li>\r\n<li>komunikace s investorem, TDI, projektanty a statiky (např. připom&iacute;nky k projektov&eacute; dokumentaci)</li>\r\n<li>př&iacute;prava podkladů k v&yacute;běru subdodavatelů, kontrola měs&iacute;čn&iacute;ch soupisů proveden&yacute;ch prac&iacute;</li>\r\n</ul>','<ul>\r\n<li>S&Scaron;/V&Scaron; vzděl&aacute;n&iacute; stavebn&iacute;ho směru</li>\r\n<li>vhodn&eacute; i pro absolventy</li>\r\n<li>nutn&aacute; orientace v technick&eacute; dokumentaci</li>\r\n<li>znalost MS Office (Excel, Word)</li>\r\n<li>řidičsk&yacute; průkaz sk. B</li>\r\n<li>spolehlivost</li>\r\n</ul>','<ul>\r\n<li>jistotu u prosperuj&iacute;c&iacute; firmy se zahraničn&iacute; &uacute;čast&iacute;</li>\r\n<li>pr&aacute;ci v nov&eacute; administrativn&iacute; budově</li>\r\n<li>odpov&iacute;daj&iacute;c&iacute; mzdov&eacute; ohodnocen&iacute;</li>\r\n<li>možnost ročn&iacute;ch pr&eacute;mi&iacute;</li>\r\n<li>stravenkov&yacute; pau&scaron;&aacute;l</li>\r\n<li>možnost př&iacute;spěvku na doplňkov&eacute; penzijn&iacute; spořen&iacute;</li>\r\n<li>25 dnů dovolen&eacute;</li>\r\n<li>pravideln&eacute; teambuildingy</li>\r\n<li>v&yacute;uku NJ na pracovi&scaron;ti</li>\r\n<li>pravideln&eacute; &scaron;kolen&iacute; a vzděl&aacute;v&aacute;n&iacute;</li>\r\n<li>obč