(285,71,1,5,'ACCOUNT MANAGER','Bor u Tachova','<ul>\r\n<li>Navazov&aacute;n&iacute; a dal&scaron;&iacute; rozvoj vztahů se z&aacute;kazn&iacute;ky</li>\r\n<li>Komplexn&iacute; podpora st&aacute;vaj&iacute;c&iacute;ch z&aacute;kazn&iacute;ků v lokalitě Bor</li>\r\n<li>Realizace dal&scaron;&iacute;ho obchodn&iacute;ho potenci&aacute;lu na z&aacute;kladě potřeb z&aacute;kazn&iacute;ků</li>\r\n<li>Strategick&eacute; pl&aacute;nov&aacute;n&iacute; rozvoje z&aacute;kazn&iacute;ků</li>\r\n<li>Ř&iacute;zen&iacute; a koordinace strategick&eacute; popt&aacute;vky z&aacute;kazn&iacute;ků</li>\r\n<li>Př&iacute;prava obchodn&iacute;ch reportů</li>\r\n<li>Posilov&aacute;n&iacute; st&aacute;vaj&iacute;c&iacute; obchodn&iacute; strategie</li>\r\n<li>Intern&iacute; kontaktn&iacute; osoba pro t&yacute;m z&aacute;kaznick&eacute;ho servisu</li>\r\n</ul>','<ul>\r\n<li>Praxi na obdobn&eacute; pozici, nejl&eacute;pe v oblasti prodeje nebo logistiky v&yacute;hodou</li>\r\n<li>Velmi dobrou znalost NJ a středně pokročilou znalost AJ</li>\r\n<li>Zku&scaron;enost s programy MS Office (Excel, Word a PowerPoint)</li>\r\n<li>Znalost ř&iacute;zen&iacute; LEAN a kontroly kvality v&yacute;hodou</li>\r\n<li>Vysokou schopnost učit se a ochotu d&aacute;le se rozv&iacute;jet</li>\r\n<li>Strukturovan&yacute; a samostatn&yacute; způsob pr&aacute;ce</li>\r\n<li>Sebevědom&eacute; vystupov&aacute;n&iacute;, vyspěl&eacute; a otevřen&eacute; komunikačn&iacute; schopnosti a t&yacute;mov&yacute; duch<br><br></li>\r\n</ul>','<ul>\r\n<li>Zaj&iacute;mav&eacute; spektrum &uacute;kolů s prostorem pro Va&scaron;e vlastn&iacute; n&aacute;pady</li>\r\n<li>Ekonomicky zdravou a modern&iacute; rodinnou firmu</li>\r\n<li>Pr&aacute;ci v &uacute;spě&scaron;n&eacute; a stabiln&iacute; společnosti a rostouc&iacute;m oboru</li>\r\n<li>Osobn&iacute; rozvoj se zaj&iacute;mav&yacute;mi kari&eacute;rn&iacute;mi možnostmi</li>\r\n<li>Př&aacute;telskou firemn&iacute; kulturu a siln&yacute; t&yacute;mov&yacute; duch</li>\r\n<li>25 dn&iacute; dovolen&eacute;</li>\r\n<li>Home office až 2 dny v t&yacute;dnu</li>\r\n<li>Pružnou pracovn&iacute; dobu</li>\r\n<li>Ročn&iacute; pr&eacute;mie na z&aacute;kladě splněn&iacute; předem stanoven&yacute;ch a dohodnut&yacute;ch c&iacute;lů</li>\r\n<li>Zodpovědnou pr&aacute;ci na perspektivn&iacute;ch projektech s atraktivn&iacute;mi klienty</li>\r\n</ul>'),
(286,64,1,5,'Finanční účetní','Tachov - Plzeň','<p><strong>Kvalita, inovace a partnersk&eacute; sm&yacute;&scaron;len&iacute; patř&iacute; k nejdůležitěj&scaron;&iacute;m faktorům &uacute;spěchu, kter&eacute; n&aacute;s drž&iacute; na předn&iacute;ch př&iacute;čk&aacute;ch v&yacute;robců v oblasti mazac&iacute; a d&iacute;lensk&eacute; techniky v na&scaron;&iacute; již stolet&eacute; působnosti.</strong></p>\r\n<p><strong>Pro svůj z&aacute;vod v Tachově hled&aacute;me vhodn&eacute;ho kandid&aacute;ta/kandid&aacute;tku na pozici finančn&iacute; &uacute;četn&iacute;</strong></p>\r\n<p><strong>Hlavn&iacute; činnosti:</strong></p>\r\n<ul>\r\n<li style=\"font-weight: bold;\"><strong>&uacute;čtov&aacute;n&iacute; faktur přijat&yacute;ch, vydan&yacute;ch, bankovn&iacute;ch v&yacute;pisů a hlavn&iacute; knihy pro vybran&eacute; společnosti ve skupině v podnikov&eacute;m syst&eacute;mu Oracle EBS</strong></li>\r\n<li style=\"font-weight: bold;\"><strong>evidence a &uacute;čtov&aacute;n&iacute; majetku</strong></li>\r\n<li style=\"font-weight: bold;\"><strong>evidence a &uacute;čtov&aacute;n&iacute; cestovn&iacute;ch dokladů</strong></li>\r\n<li style=\"font-weight: bold;\"><strong>spolupr&aacute;ce na př&iacute;pravě měs&iacute;čn&iacute;ch z&aacute;věrek a přehledů pro reporting a ročn&iacute;ch &uacute;četn&iacute;ch z&aacute;věrek vybran&yacute;ch společnost&iacute; ve skupině</strong></li>\r\n<li style=\"font-weight: bold;\"><strong>kompletn&iacute; evidence dovozů ze třet&iacute;ch zem&iacute; (kontrola objedn&aacute;vek, &uacute;hrada a evidence z&aacute;loh, zpracov&aacute;n&iacute; přehledů dovozů pro DPH a pro celn&iacute; evidenci CBAM)</strong></li>\r\n</ul>','<ul>\r\n<li style=\"font-weight: bold;\"><strong>praxe v &uacute;četnictv&iacute;</strong></li>\r\n<li style=\"font-weight: bold;\"><strong>znalost německ&eacute;ho nebo anglick&eacute;ho jazyka slovem i p&iacute;smem (komunikace se z&aacute;kazn&iacute;ky, dodavateli a zahraničn&iacute;mi kolegy)</strong></li>\r\n<li style=\"font-weight: bold;\"><strong>zku&scaron;enost s ERP syst&eacute;mem v&iacute;t&aacute;na (Oracle EBS v&yacute;hodou)</strong></li>\r\n<li style=\"font-weight: bold;\"><strong>znalost MS Office (Word, Excel)</strong></li>\r\n<li style=\"font-weight: bold;\"><strong>spolehlivost, pečlivost, odpovědnost a samostatnost</strong></li>\r\n<li style=\"font-weight: bold;\"><strong>pozitivn&iacute; př&iacute;stup k pr&aacute;ci, proaktivn&iacute; př&iacute;stup, komunikativnost a ochota pracovat v t&yacute;mu</strong></li>\r\n<li style=\"font-weight: bold;\"><strong>řidičsk&yacute; průkaz sk. B (aktivn&iacute; řidič)</strong></li>\r\n</ul>','<ul>\r\n<li><strong>z&aacute;zem&iacute; mezin&aacute;rodn&iacute; společnosti</strong></li>\r\n<li><strong>hlavn&iacute; pracovn&iacute; poměr na dobu neurčitou</strong></li>\r\n<li><strong>m&iacute;sto v&yacute;konu pr&aacute;ce Tachov, služebn&iacute; cesty na pobočku v Plzni</strong></li>\r\n<li><strong>možnost flexibiln&iacute; pracovn&iacute; doby</strong></li>\r\n<li><strong>t&yacute;den dovolen&eacute; nav&iacute;c, z&aacute;vodn&iacute; stravov&aacute;n&iacute;, př&iacute;spěvek na penzijn&iacute; připoji&scaron;těn&iacute;</strong></li>\r\n<li><strong>jazykov&aacute; v&yacute;uka, možnost dal&scaron;&iacute;ho vzděl&aacute;v&aacute;n&iacute; a pravideln&yacute;ch &scaron;kolen&iacute;</strong></li>\r\n<li><strong>n&aacute;stup možn&yacute; ihned</strong></li>\r\n</ul>\r\n<p><strong>Sv&eacute; životopisy v česk&eacute;m a německ&eacute;m jazyce a motivačn&iacute; dopisy zas&iacute;lejte na e-mailovouv adresu: martin.kadanik@pressol.com</strong></p>'),
(289,44,1,3,'Prodavačka/Pokladní ( jídelna Slávie)','Pražská 155, Klatovy','<p>Typ &uacute;vazku - Pr&aacute;ce na pln&yacute; &uacute;vazek<br>Typ smluvn&iacute;ho vztahu - pracovn&iacute; smlouva<br>D&eacute;lka pracovn&iacute;ho poměru - Na dobu neurčitou</p>','<p>&nbsp;praxe v&yacute;hodou</p>\r\n<p>- samostatnost, zodpovědnost, komunikativnost</p>\r\n<p>- jednosměnn&yacute; provoz</p>\r\n<p>- pracovn&iacute; doba ponděl&iacute; až p&aacute;tek (v&iacute;kendy voln&eacute;)</p>','<p>- n&aacute;borov&yacute; př&iacute;spěvek do v&yacute;&scaron;e 20 000 Kč<br>- pouk&aacute;zky na zv&yacute;hodněn&yacute; n&aacute;kup na&scaron;ich v&yacute;robků<br>- z&aacute;vodn&iacute; stravov&aacute;n&iacute; s v&yacute;razn&yacute;m př&iacute;spěvkem zaměstnavatele<br>- ročn&iacute; odměny<br>- př&iacute;spěvek na penzijn&iacute; připoji&scaron;těn&iacute;<br>- př&iacute;spěvek na dopravu<br>- jednor&aacute;zov&yacute; bonus na dovolenou 3 000 Kč<br>- věrnostn&iacute; bonus za odpracovan&eacute; roky<br>- odměna za doporučen&iacute; nov&eacute;ho zaměstnance je do v&yacute;&scaron;e 10 000kč</p>'),
(290,71,1,4,'REFERENT/KA SPRÁVY DAT','Bor u Tachova','<ul>\r\n<li>Dohled nad vyt&iacute;žen&iacute;m skladov&yacute;ch prostor</li>\r\n<li>Prov&aacute;děn&iacute; korekc&iacute; evidovan&eacute;ho zbož&iacute; a veden&iacute; souvisej&iacute;c&iacute; dokumentace</li>\r\n<li>Prov&aacute;děn&iacute; stahov&aacute;n&iacute; zbož&iacute; ze skladu</li>\r\n<li>Hloubkov&aacute; anal&yacute;za dat, zji&scaron;ťov&aacute;n&iacute; důležit&yacute;ch faktů, z&aacute;vislost&iacute;, trendů</li>\r\n<li>Vizualizace dat a př&iacute;prava dat pro reporting</li>\r\n<li>Pořizov&aacute;n&iacute; z&aacute;kladn&iacute;ch &uacute;dajů o zbož&iacute; na 3D stroji a určov&aacute;n&iacute; jejich vlastnost&iacute;</li>\r\n<li>Podpora operativn&iacute;ch spolupracovn&iacute;ků v provozu</li>\r\n</ul>','<ul>\r\n<li>Ochotu pracovat ve dvousměnn&eacute;m provozu</li>\r\n<li>Strukturovan&yacute; způsob pr&aacute;ce orientovan&yacute; na v&yacute;sledek</li>\r\n<li>Spolehlivost, pečlivost a zručnost</li>\r\n<li>Samostatn&yacute; a systematick&yacute; způsob pr&aacute;ce</li>\r\n<li>Smyl pro pr&aacute;ci v t&yacute;mu</li>\r\n<li>&Scaron;ir&scaron;&iacute; uživatelsk&eacute; znalosti MS Word, MS Excel a Powerpoint</li>\r\n<li>Dobr&eacute; komunikačn&iacute; dovednosti a flexibilitu</li>\r\n<li>Minim&aacute;lně č&aacute;stečn&aacute; znalost německ&eacute;ho jazyka v&iacute;t&aacute;na</li>\r\n</ul>','<ul>\r\n<li>Zaj&iacute;mavou a zodpovědnou činnost v ekonomicky zdrav&eacute;, modern&iacute; rodinn&eacute; společnosti s plochou hierarchickou strukturou</li>\r\n<li>Př&iacute;jemn&eacute; pracovn&iacute; prostřed&iacute; a př&aacute;telsk&yacute; kolektiv</li>\r\n<li>Stabiln&iacute; a dlouhodobou spolupr&aacute;ci</li>\r\n<li>Motivuj&iacute;c&iacute; finančn&iacute; ohodnocen&iacute;</li>\r\n<li>5 t&yacute;dnů dovolen&eacute;</li>\r\n<li>Zv&yacute;hodněn&eacute; bankovn&iacute; produkty a mobiln&iacute; tarify</li>\r\n<li>Př&iacute;spěvek na stravov&aacute;n&iacute;</li>\r\n<li>Odměna za doporučen&iacute; nov&eacute;ho zaměstnance</li>\r\n<li>N&aacute;stup možn&yacute; ihned nebo domluvou</li>\r\n</ul>'),
(291,71,1,1,'SKLADOVÝ OPERÁTOR','Bor u Tachova','<ul>\r\n<li>Naskladňov&aacute;n&iacute;, vyskladňov&aacute;n&iacute; a přeskladňov&aacute;n&iacute; zbož&iacute;</li>\r\n<li>Vstupn&iacute; / v&yacute;stupn&iacute; kontrola zbož&iacute;</li>\r\n<li>Tř&iacute;děn&iacute; zbož&iacute;</li>\r\n<li>Kompletace objedn&aacute;vek</li>\r\n<li>Plněn&iacute; samostatn&yacute;ch &uacute;kolů dle zad&aacute;n&iacute; vedouc&iacute;ho</li>\r\n</ul>','<ul>\r\n<li>Ukončen&eacute; Z&Scaron; vzděl&aacute;n&iacute;</li>\r\n<li>Manu&aacute;ln&iacute; zručnost</li>\r\n<li>Samostatnost</li>\r\n<li>Schopnost t&yacute;mov&eacute; pr&aacute;ce</li>\r\n<li>Ochotu k pr&aacute;ci v nepřetržit&eacute;m provozu</li>\r\n<li>Ochotu se neust&aacute;le učit a vzděl&aacute;vat</li>\r\n<li>Respektov&aacute;n&iacute; a dodržov&aacute;n&iacute; bezpečnosti pr&aacute;ce</li>\r\n<li>Čist&yacute; trestn&iacute; rejstř&iacute;k</li>\r\n</ul>','<ul>\r\n<li>Př&iacute;jemn&eacute; pracovn&iacute; prostřed&iacute; a dobr&yacute; kolektiv</li>\r\n<li>Motivuj&iacute;c&iacute; finančn&iacute; ohodnocen&iacute;</li>\r\n<li>Stravenkov&yacute; pau&scaron;&aacute;l</li>\r\n<li>T&yacute;den dovolen&eacute; nav&iacute;c</li>\r\n<li>Zaji&scaron;těn&eacute; ubytov&aacute;n&iacute;</li>\r\n<li>Firemn&iacute; autobusov&aacute; doprava</li>\r\n<li>Př&iacute;platky za pr&aacute;ci o v&iacute;kendu</li>\r\n<li>Stabiln&iacute; a dlouhodobou pr&aacute;ci</li>\r\n<li>N&aacute;stupn&iacute; bonus 10.000 Kč</li>\r\n<li>Možnost kari&eacute;rn&iacute;ho postupu</li>\r\n</ul>'),
(296,73,1,5,'Stavbyvedoucí','Ejpovice (okr. Rokycany)','<ul>\r\n<li>Samostatn&eacute; ř&iacute;zen&iacute; svěřen&eacute; stavby v souladu se smluvn&iacute;mi, technick&yacute;mi a legislativn&iacute;mi požadavky</li>\r\n<li>Spolupr&aacute;ce s veden&iacute;m, investory, stavebn&iacute;m dozorem, projektantem a dodavateli</li>\r\n<li>Vytv&aacute;řen&iacute; harmonogramu stavby a odpovědnost za jeho plněn&iacute;</li>\r\n<li>Pod&iacute;len&iacute; se na v&yacute;běru dodavatelů a jejich koordinaci</li>\r\n<li>Ř&iacute;zen&iacute; n&aacute;kladů, kontrola kvality a ř&iacute;zen&iacute; BOZP</li>\r\n<li>Zodpovědnost za ekonomick&eacute; v&yacute;sledky stavby, kontrola n&aacute;kladů a v&yacute;nosů</li>\r\n</ul>','<ul>\r\n<li>S&Scaron;/V&Scaron; stavebn&iacute;</li>\r\n<li>Praxe v oboru dopravn&iacute;ch či pozemn&iacute;ch staveb (autorizace je v&yacute;hodou)</li>\r\n<li>Řidičsk&yacute; průkaz sk. B</li>\r\n<li>Uživatelsk&aacute; znalost MS Office</li>\r\n<li>Siln&aacute; osobnost s přirozenou autoritou</li>\r\n<li>Zodpovědnost, aktivn&iacute; a samostatn&yacute; př&iacute;stup</li>\r\n</ul>','<ul>\r\n<li>Z&aacute;zem&iacute; siln&eacute; a stabiln&iacute; společnosti</li>\r\n<li>Odpov&iacute;daj&iacute;c&iacute; mzdov&eacute; ohodnocen&iacute;</li>\r\n<li>T&yacute;den dovolen&eacute; nav&iacute;c</li>\r\n<li>Př&iacute;spěvek na stravov&aacute;n&iacute; (185 Kč za směnu)</li>\r\n<li>Př&iacute;spěvek na volnočasov&eacute; benefity (cafeterie)</li>\r\n<li>V&yacute;hody při n&aacute;kupu u obchodn&iacute;ch partnerů</li>\r\n<li>Možnost dal&scaron;&iacute;ho odborn&eacute;ho rozvoje</li>\r\n<li>Př&aacute;telsk&eacute; pracovn&iacute; prostřed&iacute;</li>\r\n<li>Firemn&iacute; akce</li>\r\n<li>Dal&scaron;&iacute; firemn&iacute; benefity</li>\r\n</ul>'),
(297,73,1,5,'Mistr - pozemní stavby','Ejpovice (okr. Rokycany)','<ul>\r\n<li>Koordinace a kontrola stavebn&iacute;ch činnost&iacute; na stavbě</li>\r\n<li>Kontrola technologick&yacute;ch postupů, platn&yacute;ch norem, BOZP a PO</li>\r\n<li>Veden&iacute; stavebn&iacute;ho den&iacute;ku, prov&aacute;děn&iacute; denn&iacute;ch z&aacute;pisů do SD, kontrola SD subdodavatelů</li>\r\n<li>Zaji&scaron;těn&iacute; dodržov&aacute;n&iacute; harmonogramu stavby</li>\r\n</ul>','<ul>\r\n<li>S&Scaron; vzděl&aacute;n&iacute; stavebn&iacute;ho směru</li>\r\n<li>Praxe v oboru pozemn&iacute;ch staveb v&yacute;hodou</li>\r\n<li>Řidičsk&yacute; průkaz skupiny B</li>\r\n<li>Uživatelsk&aacute; znalost MS Office</li>\r\n<li>Zodpovědnost, aktivn&iacute; a samostatn&yacute; př&iacute;stup</li>\r\n</ul>','<ul>\r\n<li>Z&aacute;zem&iacute; siln&eacute; a stabiln&iacute; společnosti</li>\r\n<li>Odpov&iacute;daj&iacute;c&iacute; mzdov&eacute; ohodnocen&iacute;</li>\r\n<li>T&yacute;den dovolen&eacute; nav&iacute;c</li>\r\n<li>Př&iacute;spěvek na stravov&aacute;n&iacute; (185 Kč za směnu)</li>\r\n<li>Př&iacute;spěvek na volnočasov&eacute; benefity (cafeterie)</li>\r\n<li>V&yacute;hody při n&aacute;kupu u obchodn&iacute;ch partnerů</li>\r\n<li>Možnost dal&scaron;&iacute;ho odborn&eacute;ho rozvoje</li>\r\n<li>Př&aacute;telsk&eacute; pracovn&iacute; prostřed&iacute;</li>\r\n<li>Firemn&iacute; akce</li>\r\n<li>Dal&scaron;&iacute; firemn&iacute; benefity</li>\r\n</ul>'),
(298,73,1,1,'Řidič sk. C','Ejpovice (okr. Rokycany)','<ul>\r\n<li>Převoz a svoz materi&aacute;lu v r&aacute;mci stavby</li>\r\n<li>Kontrola chodu a v&yacute;konu stroje</li>\r\n<li>Př&iacute;ležitostn&aacute; manu&aacute;ln&iacute; pr&aacute;ce na stavbě</li>\r\n</ul>','<ul>\r\n<li>Profesn&iacute; průkaz</li>\r\n<li>ŘP sk. C, v&yacute;hodou je sk. E</li>\r\n<li>Zodpovědnost a časovou flexibilitu</li>\r\n</ul>','<ul>\r\n<li>Z&aacute;zem&iacute; siln&eacute; a stabiln&iacute; společnosti</li>\r\n<li>Odpov&iacute;daj&iacute;c&iacute; mzdov&eacute; ohodnocen&iacute;</li>\r\n<li>T&yacute;den dovolen&eacute; nav&iacute;c</li>\r\n<li>Př&iacute;spěvek na stravov&aacute;n&iacute; (185 Kč za směnu)</li>\r\n<li>V&yacute;hody při n&aacute;kupu u obchodn&iacute;ch partnerů</li>\r\n<li>Možnost dal&scaron;&iacute;ho odborn&eacute;ho rozvoje</li>\r\n<li>Př&aacute;telsk&eacute; pracovn&iacute; prostřed&iacute;</li>\r\n<li>Firemn&iacute; akce</li>\r\n<li>Dal&scaron;&iacute; firemn&iacute; benefity</li>\r\n</ul>'),
(299,73,1,1,'Strojník kolového rypadla','Ejpovice (okr. Rokycany)','<ul>\r\n<li>Obsluha a ř&iacute;zen&iacute; kolov&eacute;ho rypadla</li>\r\n<li>Prov&aacute;děn&iacute; zemn&iacute;ch prac&iacute;, v&yacute;kopů, ter&eacute;nn&iacute;ch &uacute;prav a nakl&aacute;d&aacute;n&iacute; materi&aacute;lů dle pokynů stavbyvedouc&iacute;ho</li>\r\n<li>Kontrola technick&eacute;ho stavu stroje</li>\r\n<li>Dodržov&aacute;n&iacute; bezpečnostn&iacute;ch předpisů (pr&aacute;ce v souladu s BOZP, ochrana okoln&iacute;ho prostřed&iacute; a minimalizace rizik na staveni&scaron;ti)</li>\r\n<li>Komunikace se stavbyvedouc&iacute;m, techniky a ostatn&iacute;mi pracovn&iacute;ky na stavbě k zaji&scaron;těn&iacute; plynul&eacute;ho průběhu prac&iacute;</li>\r\n</ul>','<ul>\r\n<li>Průkaz strojn&iacute;ka kolov&yacute;ch rypadel</li>\r\n<li>Zku&scaron;enosti s obsluhou kolov&eacute;ho rypadla (př&iacute;padně jin&eacute; těžk&eacute; techniky).</li>\r\n<li>Zodpovědnost a preciznost</li>\r\n</ul>','<ul>\r\n<li>Z&aacute;zem&iacute; siln&eacute; a stabiln&iacute; společnosti</li>\r\n<li>Odpov&iacute;daj&iacute;c&iacute; mzdov&eacute; ohodnocen&iacute;</li>\r\n<li>T&yacute;den dovolen&eacute; nav&iacute;c</li>\r\n<li>Př&iacute;spěvek na stravov&aacute;n&iacute; (185 Kč za směnu)</li>\r\n<li>V&yacute;hody při n&aacute;kupu u obchodn&iacute;ch partnerů</li>\r\n<li>Možnost dal&scaron;&iacute;ho odborn&eacute;ho rozvoje</li>\r\n<li>Př&aacute;telsk&eacute; pracovn&iacute; prostřed&iacute;</li>\r\n<li>Firemn&iacute; akce</li>\r\n<li>Dal&scaron;&iacute; firemn&iacute; benefity</li>\r\n</ul>'),
(300,62,1,4,'Disponent/Logistik','Klatovy','<ul>\r\n<li>organizace a koordinace tuzemsk&yacute;ch i zahraničn&iacute;ch z&aacute;silek</li>\r\n<li>př&iacute;prava přepravn&iacute;ch dokumentů (dodac&iacute; listy, faktury, celn&iacute; doklady)</li>\r\n<li>komunikace s dopravci ohledně zak&aacute;zek a term&iacute;nů</li>\r\n<li>kontrola spr&aacute;vnosti a včasn&eacute;ho dod&aacute;n&iacute; z&aacute;silek</li>\r\n<li>sledov&aacute;n&iacute; z&aacute;silek a reporting o jejich stavu</li>\r\n<li>pod&iacute;len&iacute; se na celn&iacute;m odbaven&iacute;m</li>\r\n<li>ře&scaron;en&iacute; reklamac&iacute;&nbsp;</li>\r\n</ul>','<ul>\r\n<li>\r\n<p>předchoz&iacute; zku&scaron;enost na obdobn&eacute; pozici</p>\r\n</li>\r\n<li>\r\n<p>komunikativn&iacute; znalost anglick&eacute;ho jazyka (pro komunikaci se zahranič&iacute;m)</p>\r\n</li>\r\n<li>\r\n<p>zku&scaron;enost s celn&iacute;m a v&yacute;vozn&iacute;m ř&iacute;zen&iacute;m</p>\r\n</li>\r\n<li>\r\n<p>znalost syst&eacute;mu SAP velkou v&yacute;hodou</p>\r\n</li>\r\n</ul>','<ul>\r\n<li>13. mzda&nbsp;</li>\r\n<li>př&iacute;spěvek na dopravu</li>\r\n<li>stravenkov&yacute; pau&scaron;&aacute;l</li>\r\n<li>5 t&yacute;dnů dovolen&eacute;</li>\r\n<li>benefitn&iacute; program Pluxee&nbsp;</li>\r\n<li>př&iacute;spěvek na volnočasov&eacute; aktivity (MultiSport karta)&nbsp;</li>\r\n<li>př&iacute;spěvek na penzijn&iacute; připoji&scaron;těn&iacute;&nbsp;</li>\r\n</ul>'),
(301,62,1,4,'Finanční controller junior','Holýšov','<ul>\r\n<li>Př&iacute;prava a zpracov&aacute;n&iacute; v&scaron;ech reportů pro společnost</li>\r\n<li>Prezentace v&yacute;sledků finančn&iacute;mu veden&iacute;</li>\r\n<li>Anal&yacute;za rozd&iacute;lů mezi skutečn&yacute;mi a pl&aacute;novan&yacute;mi v&yacute;sledky</li>\r\n<li>Monitorov&aacute;n&iacute; n&aacute;kladů</li>\r\n<li>Zaji&scaron;ťov&aacute;n&iacute; controllingov&yacute;ch funkc&iacute; v syst&eacute;mu SAP</li>\r\n<li>Podpora při prov&aacute;děn&iacute; měs&iacute;čn&iacute;ch uz&aacute;věrek</li>\r\n<li>Spolupr&aacute;ce s ostatn&iacute;mi oddělen&iacute;mi společnosti</li>\r\n</ul>','<ul>\r\n<li>Min. S&Scaron; ekonomick&eacute;ho směru</li>\r\n<li>Komunikativn&iacute; angličtina NEBO němčina &ndash; budete občasně komunikovat se zahraničn&iacute; centr&aacute;lou &ndash; &uacute;roveň B1/B2</li>\r\n<li>Z&aacute;jem o oblast &uacute;četnictv&iacute;, controllingu</li>\r\n<li>Znalost SAP v&yacute;hodou</li>\r\n</ul>','<ul>\r\n<li>Možnost kari&eacute;rn&iacute;ho posunu</li>\r\n<li>Př&iacute;ležitost pro juniory a absolventy bez praxe</li>\r\n<li>Stravenkovou kartu hrazenou plně zaměstnavatelem</li>\r\n<li>Rodinn&yacute; kolektiv</li>\r\n<li>Smlouvu na hlavn&iacute; pracovn&iacute; poměr s n&aacute;stupem ihned do kmenu</li>\r\n<li>Pružnou pracovn&iacute; dobu v jednosměnn&eacute;m provozu</li>\r\n<li>Vzděl&aacute;vac&iacute; kurzy, &scaron;kolen&iacute;</li>\r\n<li>Z&aacute;zem&iacute; a jistotu mezin&aacute;rodn&iacute; společnosti&nbsp;</li>\r\n</ul>'),
(302,62,1,5,'Specialista kvality s angličtinou','Dnešice','<ul>\r\n<li>celkov&eacute; zaji&scaron;těn&iacute; procesů v oblastech t&yacute;kaj&iacute;c&iacute;ch se kvality</li>\r\n<li>pod&aacute;v&aacute;n&iacute; zpr&aacute;v o v&yacute;sledc&iacute;ch kvality přidělen&eacute;ho oddělen&iacute;<br>spr&aacute;va vzorků</li>\r\n<li>schvalov&aacute;n&iacute; procesn&iacute; a v&yacute;robkov&eacute; dokumentace, formul&aacute;řů a n&aacute;vodů</li>\r\n<li>vytv&aacute;řen&iacute;, přezkoum&aacute;v&aacute;n&iacute; a schvalov&aacute;n&iacute; pl&aacute;nů kontrol pro v&yacute;stupn&iacute; kontrolu kvality</li>\r\n<li>organizov&aacute;n&iacute; a prov&aacute;děn&iacute; př&iacute;slu&scaron;n&yacute;ch intern&iacute;ch &scaron;kolen&iacute;<br>prov&aacute;děn&iacute; intern&iacute;ch auditů a auditů dodavatelů</li>\r\n</ul>','<ul>\r\n<li>S&Scaron; vzděl&aacute;n&iacute;, technick&eacute; zaměřen&iacute; v&yacute;hodou<br>zku&scaron;enosti v oblastech ř&iacute;zen&iacute; jakosti ve v&yacute;robě, znalost metod, n&aacute;strojů a norem kvality (znalost GMP v&yacute;hodou)<br>znalost AJ &ndash; min. &uacute;roveň B2 (v psan&eacute; i mluven&eacute; formě)</li>\r\n</ul>','<ul>\r\n<li>mzdu dle va&scaron;ich zku&scaron;enost&iacute;</li>\r\n<li>t&yacute;den dovolen&eacute; nav&iacute;c</li>\r\n<li>př&iacute;spěvek na dopravu</li>\r\n<li>jazykov&eacute; kurzy v pracovn&iacute; době</li>\r\n<li>př&iacute;spěvek na stravov&aacute;n&iacute;</li>\r\n<li>př&iacute;spěvek na penzijn&iacute; připoji&scaron;těn&iacute;</li>\r\n<li>flexibiln&iacute; pracovn&iacute; dobu</li>\r\n<li>smlouvu na dobu neurčitou</li>\r\n<li>rodinn&eacute; prostřed&iacute; men&scaron;&iacute; firmy</li>\r\n</ul>'),
(303,62,0,6,'Manažer jakosti','Plzeň','<ul>\r\n<li>mentoring t&yacute;mů &uacute;tvarů jakosti ve v&yacute;robě</li>\r\n<li>spr&aacute;va norem a směrnic a jejich implementace do praxe</li>\r\n<li>spolupr&aacute;ce s veden&iacute;m jednotliv&yacute;ch z&aacute;vodů</li>\r\n<li>zaji&scaron;těn&iacute; certifikace u extern&iacute;ch dodavatelů ISO 9001, 14001 a 50001</li>\r\n<li>objedn&aacute;vky extern&iacute;ch auditů</li>\r\n<li>př&iacute;prava technick&yacute;ch listů</li>\r\n<li>občasn&eacute; služebn&iacute; cesty kvůli př&iacute;padn&yacute;m reklamac&iacute;m &ndash; max. 3 x do roka&nbsp;</li>\r\n<li>&uacute;čast na nov&yacute;ch projektech&nbsp;</li>\r\n</ul>','<ul>\r\n<li>S&Scaron;/V&Scaron; vzděl&aacute;n&iacute; technick&eacute;ho směru &ndash; chemick&eacute;</li>\r\n<li>zku&scaron;enosti v oblasti kvality a jakosti v&yacute;robků</li>\r\n<li>angličtina na komunikativn&iacute; &uacute;rovni</li>\r\n<li>ŘP skupiny B</li>\r\n</ul>','<ul>\r\n<li>13. mzda</li>\r\n<li>kvart&aacute;ln&iacute; př&iacute;spěvky</li>\r\n<li>každoročn&iacute; navy&scaron;ov&aacute;n&iacute; mezd</li>\r\n<li>volnočasov&eacute; benefity v hodnotě 15 900 Kč/ročně</li>\r\n<li>př&iacute;spěvek na stravov&aacute;n&iacute;</li>\r\n<li>př&iacute;spěvek na penzijn&iacute; připoji&scaron;těn&iacute;</li>\r\n<li>př&iacute;spěvek na životn&iacute; poji&scaron;těn&iacute;</li>\r\n<li>modern&iacute; a čist&eacute; prostřed&iacute;</li>\r\n<li>firemn&iacute; akce&nbsp;</li>\r\n<li>flexibiln&iacute; pracovn&iacute; doba</li>\r\n</ul>'),
(304,62,0,5,'HR specialista ','Plzeň','<ul>\r\n<li>veden&iacute; person&aacute;ln&iacute; agendy společnosti</li>\r\n<li>zaji&scaron;ťov&aacute;n&iacute; n&aacute;borov&yacute;ch procesů</li>\r\n<li>ře&scaron;en&iacute; l&eacute;kařsk&yacute;ch prohl&iacute;dek, vstupn&iacute;ch &scaron;kolen&iacute; a n&aacute;stupn&iacute;ch dokumentů</li>\r\n<li>vyřizov&aacute;n&iacute; pracovně pr&aacute;vn&iacute;ch z&aacute;ležitost&iacute; při n&aacute;boru zaměstnanců</li>\r\n<li>spolupr&aacute;ce s person&aacute;ln&iacute;mi agenturami</li>\r\n<li>spolupr&aacute;ce na nastaven&iacute; syst&eacute;mu motivace a odměňov&aacute;n&iacute; zaměstnanců</li>\r\n<li>zaji&scaron;ťov&aacute;n&iacute; rozvoje a vzděl&aacute;v&aacute;n&iacute; zaměstnanců</li>\r\n<li>reporting veden&iacute; spolčnosti</li>\r\n</ul>','<ul>\r\n<li>předchoz&iacute; zku&scaron;enosti v HR oboru min. 5 let</li>\r\n<li>angličtina na komunikativn&iacute; &uacute;rovni B2</li>\r\n<li>ŘP skupiny B</li>\r\n</ul>','<ul>\r\n<li>zaj&iacute;mav&eacute; finančn&iacute; ohodnocen&iacute;</li>\r\n<li>mimoř&aacute;dn&eacute; odměny ke mzdě</li>\r\n<li>flexibilita zač&aacute;tku a konce pracovn&iacute; doby</li>\r\n<li>25 dn&iacute; dovolen&eacute;</li>\r\n<li>z&aacute;zem&iacute; mal&eacute; firmy</li>\r\n<li>jazykov&eacute; kurzy v pracovn&iacute; době</li>\r\n<li>vzděl&aacute;vac&iacute; a rozvojov&eacute; kurzy</li>\r\n<li>vzděl&aacute;vac&iacute; kurzy</li>\r\n<li>př&iacute;spěvek na stravov&aacute;n&iacute;</li>\r\n<li>mobiln&iacute; telefon</li>\r\n<li>notebook</li>\r\n</ul>'),
(305,62,0,6,'Vývojový inženýr nových produktů','Plzeň','<ul>\r\n<li>pod&iacute;len&iacute; se na v&yacute;voji nov&yacute;ch produktů v r&aacute;mci nov&yacute;ch projektů</li>\r\n<li>specifikov&aacute;n&iacute; produktu a v&yacute;voj jednotliv&yacute;ch č&aacute;st&iacute;</li>\r\n<li>koordinov&aacute;n&iacute; n&aacute;běhů nov&yacute;ch modelů do v&yacute;roby</li>\r\n<li>ře&scaron;en&iacute; technick&yacute;ch požadavků v r&aacute;mci projektů</li>\r\n<li>tvorba projektov&eacute; a technick&eacute; dokumentace</li>\r\n<li>intern&iacute; komunikace a extern&iacute; spolupr&aacute;ce se zahraničn&iacute;mi firmami</li>\r\n<li>komunikace se zahraničn&iacute;mi z&aacute;kazn&iacute;ky</li>\r\n</ul>','<ul>\r\n<li>minim&aacute;lně S&Scaron;/V&Scaron; technick&eacute;ho zaměřen&iacute; (strojn&iacute;/elektro)</li>\r\n<li>předchoz&iacute; praxe</li>\r\n<li>znalost 3D programů</li>\r\n<li>m&iacute;rně pokročil&aacute; &uacute;roveň angličtiny (B1-B2)</li>\r\n</ul>','<ul>\r\n<li>mzda dle zku&scaron;enost&iacute; &ndash; až 75 000 Kč</li>\r\n<li>n&aacute;borov&yacute; př&iacute;spěvek</li>\r\n<li>pravideln&eacute; každoročn&iacute; navy&scaron;ov&aacute;n&iacute; mzdy</li>\r\n<li>2x půlročn&iacute; bonus = pln&aacute; 13. mzda</li>\r\n<li>14. mzda</li>\r\n<li>Cafeteria system (6000 Kč /rok)</li>\r\n<li>flexibiln&iacute; pracovn&iacute; doba</li>\r\n<li>možnost občasn&eacute;ho HO</li>\r\n<li>5 t&yacute;dnů dovolen&eacute;</li>\r\n<li>5 sick days</li>\r\n<li>př&iacute;spěvek na penzijn&iacute; nebo životn&iacute; poji&scaron;těn&iacute;&nbsp;</li>\r\n<li>dotovan&eacute; z&aacute;vodn&iacute; stravov&aacute;n&iacute;</li>\r\n<li>pitn&yacute; režim na pracovi&scaron;ti zdarma</li>\r\n<li>jazykov&eacute; kurzy &nbsp;a vzděl&aacute;vac&iacute; kurzy v pracovn&iacute; době</li>\r\n<li>zv&yacute;hodněn&yacute; mobiln&iacute; tarif</li>\r\n</ul>'),
(306,64,1,3,'Seřizovač vstřikovacích lisů','Tachov ','<p><strong>PRESSOL Tschechien s.r.o,</strong></p>\r\n<p><strong>Kvalita, inovace a partnersk&eacute; sm&yacute;&scaron;len&iacute; patř&iacute; k nejdůležitěj&scaron;&iacute;m faktorům &uacute;spěchu, kter&eacute; n&aacute;s drž&iacute; na předn&iacute;ch př&iacute;čk&aacute;ch v&yacute;robců v oblasti mazac&iacute; a d&iacute;lensk&eacute; techniky v na&scaron;&iacute; již stolet&eacute; působnosti.</strong></p>\r\n<p><strong>Pro svůj z&aacute;vod v Tachově hled&aacute;me zaměstnance na pozici Seřizovač vstřikovac&iacute;ch lisů</strong></p>\r\n<p><br><strong>Hlavn&iacute; činnosti:</strong></p>\r\n<ul>\r\n<li><strong>Seřizov&aacute;n&iacute; vstřikovac&iacute;ch lisů nebo vyfukovac&iacute;ch lisů</strong></li>\r\n</ul>','<ul>\r\n<li><strong>Zku&scaron;enosti z oblasti seřizov&aacute;n&iacute; lisů</strong></li>\r\n<li><strong>Obsluha a nastavov&aacute;n&iacute; manipul&aacute;torů (robotů)</strong></li>\r\n<li><strong>Zodpovědnost</strong></li>\r\n<li><strong>Manu&aacute;ln&iacute; zručnost</strong></li>\r\n<li><strong>Pr&aacute;ce v 3 směnn&eacute;m provozu</strong></li>\r\n<li><strong>Samostatnost a snaha učit se st&aacute;le nov&yacute;m věcem</strong></li>\r\n</ul>','<ul>\r\n<li><strong>Pr&aacute;ce v &uacute;spě&scaron;n&eacute; mezin&aacute;rodn&iacute; společnosti</strong></li>\r\n<li><strong>N&aacute;stup možn&yacute; ihned</strong></li>\r\n<li><strong>Skvěl&yacute; t&yacute;m kolegů</strong></li>\r\n<li><strong>Dotovan&eacute; z&aacute;vodn&iacute; stravov&aacute;n&iacute;</strong></li>\r\n<li><strong>Penzijn&iacute; poji&scaron;těn&iacute; a jin&eacute; zaměstnaneck&eacute; v&yacute;hody</strong></li>\r\n<li><strong>Dovolen&aacute; 25 dnů</strong></li>\r\n<li><strong>Př&iacute;jemn&eacute; pracovn&iacute; prostřed&iacute;</strong><br><strong>&nbsp;</strong></li>\r\n</ul>'),
(307,64,1,6,'Vývojový inženýr','Tachov ','<p>PRESSOL Tschechien s.r.o,</p>\r\n<p>Kvalita, inovace a partnersk&eacute; sm&yacute;&scaron;len&iacute; patř&iacute; k nejdůležitěj&scaron;&iacute;m faktorům &uacute;spěchu, kter&eacute; n&aacute;s drž&iacute; na předn&iacute;ch př&iacute;čk&aacute;ch v&yacute;robců v oblasti mazac&iacute; a d&iacute;lensk&eacute; techniky v na&scaron;&iacute; již stolet&eacute; působnosti.</p>\r\n<p>Pro svůj z&aacute;vod v Tachově hled&aacute;me zaměstnance na pozici <strong>v&yacute;vojov&yacute; inžen&yacute;r</strong></p>\r\n<p>Požadujeme:</p>\r\n<ul>\r\n<li><strong>Vysoko&scaron;kolsk&eacute; vzděl&aacute;n&iacute; s technick&yacute;m zaměřen&iacute;m (vhodn&eacute; i pro absolventy)</strong></li>\r\n<li><strong>Zku&scaron;enosti na obdobn&eacute; pozici v&yacute;hodou</strong></li>\r\n<li><strong>Praxe ve v&yacute;robn&iacute;m podniku (v&yacute;hodou) a orientace v technick&eacute; dokumentaci&nbsp;</strong></li>\r\n<li><strong>Velmi dobr&aacute; znalost CAM syst&eacute;mu</strong></li>\r\n<li><strong>Znalost německ&eacute;ho jazyka na &uacute;rovni B1, B2 &ndash; podm&iacute;nkou (nutn&aacute; aktivn&iacute; spolupr&aacute;ce s na&scaron;im z&aacute;vodem v Německu). Angličtina v&yacute;hodou.</strong></li>\r\n<li><strong>Řidičsk&yacute; průkaz skupiny B (nen&iacute; podm&iacute;nkou)</strong></li>\r\n<li><strong>Odpovědnost za svěřen&eacute; &uacute;koly</strong></li>\r\n<li><strong>Organizačn&iacute; schopnosti a uměn&iacute; pl&aacute;novat</strong></li>\r\n<li><strong>Komunikačn&iacute; a prezentačn&iacute; dovednosti</strong></li>\r\n<li><strong>Důslednost, samostatnost a spolehlivost</strong></li>\r\n<li><strong>Vhodn&eacute; i pro z&aacute;jemce s ukončen&iacute;m vysoko&scaron;kolsk&yacute;m vzděl&aacute;n&iacute;m bez praxe</strong></li>\r\n</ul>','<ul>\r\n<li><strong>Komunikace v r&aacute;mci společnost&iacute; PRESSOL, komunikace s extern&iacute;mi partnery</strong></li>\r\n<li><strong>Podpora v komplexn&iacute;m v&yacute;voji projektu&nbsp;</strong></li>\r\n<li><strong>Vytv&aacute;řen&iacute; př&iacute;slu&scaron;n&yacute;ch dokumentů</strong></li>\r\n<li><strong>Zlep&scaron;ov&aacute;n&iacute; se zaměřen&iacute;m na standardizaci procesu v&yacute;roby</strong></li>\r\n<li><strong>V&yacute;voj/spolu&uacute;čast na v&yacute;voji nov&yacute;ch v&yacute;robků</strong></li>\r\n<li><strong>Anal&yacute;za komplexn&iacute;ch chyb , n&aacute;vrh a realizace n&aacute;pravn&yacute;ch opatřen&iacute;.</strong></li>\r\n<li><strong>&Uacute;zk&aacute; spolupr&aacute;ce s R&amp;D oddělen&iacute;mi v zahranič&iacute;.</strong></li>\r\n<li><strong>Technick&aacute; podpora v&yacute;robn&iacute; linky a pokročil&eacute; hled&aacute;n&iacute; chyb na př&iacute;stroj&iacute;ch&nbsp;</strong></li>\r\n<li><strong>Pod&iacute;l na zav&aacute;den&iacute; nov&yacute;ch technologi&iacute; a produktu.</strong></li>\r\n</ul>','<ul>\r\n<li style=\"font-weight: bold;\"><strong>Pr&aacute;ce v &uacute;spě&scaron;n&eacute; mezin&aacute;rodn&iacute; společnosti</strong></li>\r\n<li style=\"font-weight: bold;\"><strong>N&aacute;stup možn&yacute; ihned</strong></li>\r\n<li style=\"font-weight: bold;\"><strong>Skvěl&yacute; t&yacute;m kolegů</strong></li>\r\n<li style=\"font-weight: bold;\"><strong>Z&aacute;vodn&iacute; stravov&aacute;n&iacute; za 10 Kč</strong></li>\r\n<li style=\"font-weight: bold;\"><strong>Penzijn&iacute; poji&scaron;těn&iacute; a jin&eacute; zaměstnaneck&eacute; v&yacute;hody</strong></li>\r\n<li style=\"font-weight: bold;\"><strong>Dovolen&aacute; 25 dnů</strong></li>\r\n<li style=\"font-weight: bold;\"><strong>Penzijn&iacute; připoji&scaron;těn&iacute;, doch&aacute;zkov&yacute; bonus, jazykov&eacute; kurzy a jin&eacute;</strong></li>\r\n<li style=\"font-weight: bold;\"><strong>Př&aacute;telsk&yacute; kolektiv, př&iacute;jemn&eacute; pracovn&iacute; prostřed&iacute;</strong></li>\r\n</ul>\r\n<p>Pokud m&aacute;te z&aacute;jem o tuto pracovn&iacute; pozici, po&scaron;lete V&aacute;&scaron; životopis v česk&eacute;m a německ&eacute;m (popř. anglick&eacute;m) jazyce na adresu: alena.svehlova@pressol.com</p>'),
(308,64,1,2,'Seřizovač/ Slévač','Tachov ','<p>PRESSOL Tschechien s.r.o,</p>\r\n<p>Kvalita, inovace a partnersk&eacute; sm&yacute;&scaron;len&iacute; patř&iacute; k nejdůležitěj&scaron;&iacute;m faktorům &uacute;spěchu, kter&eacute; n&aacute;s drž&iacute; na předn&iacute;ch př&iacute;čk&aacute;ch v&yacute;robců v oblasti mazac&iacute; a d&iacute;lensk&eacute; techniky v na&scaron;&iacute; již stolet&eacute; působnosti.</p>\r\n<p>&nbsp;Pro svůj z&aacute;vod v Tachově hled&aacute;me zaměstnance na pozici <strong>SEŘIZOVAČ / SLEV&Aacute;Č</strong></p>\r\n<p>Hlavn&iacute; činnosti:</p>\r\n<ul>\r\n<li><strong>seřizov&aacute;n&iacute; a obsluha stroje</strong><br>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</li>\r\n</ul>','<ul>\r\n<li style=\"font-weight: bold;\"><strong>Zku&scaron;enosti z vstřikovac&iacute;ch strojů v&yacute;hodou</strong></li>\r\n<li style=\"font-weight: bold;\"><strong>Vhodn&eacute; pro osoby s technick&yacute;m zaměřen&iacute;m, v&scaron;e zauč&iacute;me&nbsp;</strong></li>\r\n<li style=\"font-weight: bold;\"><strong>Seřizov&aacute;n&iacute; a obsluha&nbsp;</strong></li>\r\n<li style=\"font-weight: bold;\"><strong>Zodpovědnost</strong></li>\r\n<li style=\"font-weight: bold;\"><strong>Manu&aacute;ln&iacute; zručnost</strong></li>\r\n<li style=\"font-weight: bold;\"><strong>Pr&aacute;ce v 3 směnn&eacute;m provozu</strong></li>\r\n<li style=\"font-weight: bold;\"><strong>Samostatnost a snaha učit se st&aacute;le nov&yacute;m věcem</strong></li>\r\n</ul>','<ul>\r\n<li><strong>Z&aacute;vodn&iacute; stravov&aacute;n&iacute; - Stravov&aacute;n&iacute; za 10 Kč denně</strong></li>\r\n<li><strong>Zvl&aacute;&scaron;tn&iacute; pr&eacute;mie - V&aacute;nočn&iacute; pr&eacute;mie</strong></li>\r\n<li><strong>Firemn&iacute; akce - V&aacute;nočn&iacute;, velikonočn&iacute; a letn&iacute; akce, vitam&iacute;nov&eacute; bal&iacute;čky a spousty dal&scaron;&iacute;ho</strong></li>\r\n<li><strong>Jazykov&eacute; kurzy - V&yacute;uka němčiny zdarma, hrazen&aacute; zaměstnanci jako odpracovan&aacute; doba</strong></li>\r\n<li><strong>Pitn&yacute; režim</strong></li>\r\n<li><strong>Př&iacute;spěvek na soukrom&eacute; životn&iacute; poji&scaron;těn&iacute;</strong></li>\r\n<li><strong>Dovolen&aacute; 5 t&yacute;dnů - 25 dnů dovolen&eacute;</strong></li>\r\n</ul>'),
(309,64,1,2,'SVÁŘEČ','Tachov','<p>PRESSOL Tschechien s.r.o,</p>\r\n<p>Kvalita, inovace a partnersk&eacute; sm&yacute;&scaron;len&iacute; patř&iacute; k nejdůležitěj&scaron;&iacute;m faktorům &uacute;spěchu, kter&eacute; n&aacute;s drž&iacute; na předn&iacute;ch př&iacute;čk&aacute;ch v&yacute;robců v oblasti mazac&iacute; a d&iacute;lensk&eacute; techniky v na&scaron;&iacute; již stolet&eacute; působnosti.</p>\r\n<p>Pro svůj z&aacute;vod v Tachově hled&aacute;me zaměstnance na pozici Sv&aacute;řeč<br>&nbsp;</p>\r\n<p>Hlavn&iacute; činnosti:</p>\r\n<ul>\r\n<li><strong>Svařov&aacute;n&iacute;</strong></li>\r\n</ul>','<ul>\r\n<li><strong>Zku&scaron;enosti z oblasti svařov&aacute;n&iacute;, sv&aacute;řečsk&yacute; průkaz</strong></li>\r\n<li><strong>Zodpovědnost</strong></li>\r\n<li><strong>Manu&aacute;ln&iacute; zručnost</strong></li>\r\n<li><strong>Pr&aacute;ce v 1 směnn&eacute;m provozu</strong></li>\r\n<li><strong>Samostatnost a snaha učit se st&aacute;le nov&yacute;m věcem</strong></li>\r\n</ul>','<ul>\r\n<li><strong>Pr&aacute;ce v &uacute;spě&scaron;n&eacute; mezin&aacute;rodn&iacute; společnosti</strong></li>\r\n<li><strong>N&aacute;stup možn&yacute; ihned</strong></li>\r\n<li><strong>Skvěl&yacute; t&yacute;m kolegů</strong></li>\r\n<li><strong>Dotovan&eacute; z&aacute;vodn&iacute; stravov&aacute;n&iacute;</strong></li>\r\n<li><strong>Penzijn&iacute; poji&scaron;těn&iacute; a jin&eacute; zaměstnaneck&eacute; v&yacute;hody</strong></li>\r\n<li><strong>Dovolen&aacute; 25 dnů</strong></li>\r\n<li><strong>Př&iacute;jemn&eacute; pracovn&iacute; prostřed&iacute;</strong></li>\r\n</ul>'),
(310,62,1,4,'Teamleader logistiky','Klatovy','<ul>\r\n<li>veden&iacute; 6 celn&iacute;ch deklarantů</li>\r\n<li>organizace a koordinace tuzemsk&yacute;ch i zahraničn&iacute;ch z&aacute;silek</li>\r\n<li>př&iacute;prava přepravn&iacute;ch dokumentů (dodac&iacute; listy, faktury, celn&iacute; doklady)</li>\r\n<li>komunikace s dopravci ohledně zak&aacute;zek a term&iacute;nů</li>\r\n<li>kontrola spr&aacute;vnosti a včasn&eacute;ho dod&aacute;n&iacute; z&aacute;silek</li>\r\n<li>sledov&aacute;n&iacute; z&aacute;silek a reporting o jejich stavu</li>\r\n<li>pod&iacute;len&iacute; se na celn&iacute;m odbaven&iacute;m</li>\r\n<li>ře&scaron;en&iacute; reklamac&iacute;</li>\r\n</ul>','<ul>\r\n<li>předchoz&iacute; zku&scaron;enost na obdobn&eacute; pozici</li>\r\n<li>zku&scaron;enost s veden&iacute;m či koordinac&iacute; alespoň men&scaron;&iacute;ho t&yacute;mu</li>\r\n<li>komunikativn&iacute; znalost anglick&eacute;ho jazyka (pro komunikaci se zahranič&iacute;m)</li>\r\n<li>zku&scaron;enost logistick&yacute;ch procesů &ndash; celn&iacute; a v&yacute;vozn&iacute; ř&iacute;zen&iacute;</li>\r\n<li>znalost syst&eacute;mu SAP velkou v&yacute;hodou</li>\r\n<li>němčina v&yacute;hodou<br><br></li>\r\n</ul>\r\n<p>&nbsp;</p>','<ul>\r\n<li>13. mzda</li>\r\n<li>př&iacute;spěvek na dopravu</li>\r\n<li>stravenkov&yacute; pau&scaron;&aacute;l</li>\r\n<li>5 t&yacute;dnů dovolen&eacute;</li>\r\n<li>benefitn&iacute; program Pluxee</li>\r\n<li>možnost spolufinancov&aacute;n&iacute; MultiSport karty</li>\r\n</ul>'),
(311,62,1,4,'Specialista řízení výroby','Klatovy','<ul>\r\n<li>pl&aacute;novat a optimalizovat v&yacute;robn&iacute; harmonogramy a pracovn&iacute; postupy</li>\r\n<li>analyzovat dostupnost materi&aacute;lu a předch&aacute;zet jeho nedostatku</li>\r\n<li>navrhovat zlep&scaron;en&iacute; procesů a zefektivnit pracovn&iacute; postupy</li>\r\n<li>vyv&iacute;jet pokročil&eacute; analytick&eacute; postupy a automatizovat pracovn&iacute; postupy pro tvorbu reportů pomoc&iacute; Power BI a Excelu</li>\r\n<li>optimalizovat datab&aacute;zov&aacute; připojen&iacute; a zaji&scaron;ťovat bezprobl&eacute;movou integraci např&iacute;č IT syst&eacute;my</li>\r\n<li>koordinovat spolupr&aacute;ci s multifunkčn&iacute;mi t&yacute;my pro hladk&yacute; průběh operac&iacute;</li>\r\n</ul>','<ul>\r\n<li>znalost jazyka SQL, pokročil&eacute; aplikace Excel (makra, integrace s datab&aacute;z&iacute;) a Power BI pro anal&yacute;zu a vizualizaci dat</li>\r\n<li>zku&scaron;enosti se syst&eacute;my ERP a pl&aacute;nov&aacute;n&iacute;m v&yacute;roby</li>\r\n<li>analytick&eacute; my&scaron;len&iacute; a smysl pro detail</li>\r\n<li>vynikaj&iacute;c&iacute; komunikačn&iacute; a organizačn&iacute; schopnosti</li>\r\n</ul>','<ul>\r\n<li>13. mzda&nbsp;</li>\r\n<li>př&iacute;spěvek na dopravu&nbsp;</li>\r\n<li>stravenkov&yacute; pau&scaron;&aacute;l</li>\r\n<li>5 t&yacute;dnů dovolen&eacute;</li>\r\n<li>benefitn&iacute; program Pluxee&nbsp;</li>\r\n<li>př&iacute;spěvek na volnočasov&eacute; aktivity (MultiSport karta)&nbsp;</li>\r\n<li>př&iacute;spěvek na penzijn&iacute; připoji&scaron;těn&iacute;&nbsp;</li>\r\n</ul>'),
(312,62,1,4,'Dispečer','Rokycany','<ul>\r\n<li>pl&aacute;nov&aacute;n&iacute; tras s ohledem na vyt&iacute;ženost vozidel, kontrola průběhu přepravy</li>\r\n<li>ř&iacute;zen&iacute; přepravy v re&aacute;ln&eacute;m čase (denn&iacute; komunikace s řidiči, ře&scaron;en&iacute; mimoř&aacute;dn&yacute;ch situac&iacute;)</li>\r\n<li>veden&iacute; př&iacute;slu&scaron;n&eacute; dokumentace a evidence</li>\r\n<li>zad&aacute;v&aacute;n&iacute; dat do intern&iacute;ho informačn&iacute;ho syst&eacute;mu</li>\r\n<li>&uacute;zk&aacute; spolupr&aacute;ce s ostatn&iacute;mi oddělen&iacute;mi společnosti</li>\r\n</ul>','<ul>\r\n<li>německ&yacute; NEBO anglick&yacute; jazyk na komunikativn&iacute; &uacute;rovni</li>\r\n<li>ochota pracovat ve dvousměnn&eacute;m provozu</li>\r\n<li>praxe na obdobn&eacute; pozici v logistice (alespoň 1 rok)</li>\r\n</ul>','<ul>\r\n<li>odpov&iacute;daj&iacute;c&iacute; mzdov&eacute; ohodnocen&iacute; dle praxe</li>\r\n<li>př&iacute;spěvek na stravov&aacute;n&iacute; formou stravenkov&eacute;ho pau&scaron;&aacute;lu</li>\r\n<li>jazykov&eacute; kurzy hrazen&eacute; zaměstnavatelem</li>\r\n<li>benefitn&iacute; program UnicreditBank</li>\r\n<li>slevu na pohonn&eacute; hmoty u čerpac&iacute;ch stanic Orlen</li>\r\n<li>zv&yacute;hodněn&yacute; mobiln&iacute; tarif i pro členy rodiny</li>\r\n<li>z&aacute;zem&iacute; stabiln&iacute; mezin&aacute;rodn&iacute; společnosti</li>\r\n<li>pr&aacute;ci v modern&iacute;m centru s fajn kolektivem</li>\r\n</ul>'),
(313,62,1,5,'PLC programátor ','Plzeň','<p>V&yacute;voj ř&iacute;d&iacute;c&iacute;ch syst&eacute;mů pro č&aacute;sti automatizovan&yacute;ch skladů<br>Programov&aacute;n&iacute; v TiaPortal a FT Suite<br>Pr&aacute;ce se speci&aacute;ln&iacute;mi 3D simulacemi<br>Oživov&aacute;n&iacute; navržen&yacute;ch syst&eacute;mů ve f&aacute;zi v&yacute;voje<br>Fin&aacute;ln&iacute; oživov&aacute;n&iacute; př&iacute;mo u z&aacute;kazn&iacute;ka v zahranič&iacute; (cestov&aacute;n&iacute; v r&aacute;mci zahraničn&iacute;ch z&aacute;kazn&iacute;ků &ndash; cca 1/3 času v kr&aacute;tkodob&yacute;ch turnusech)</p>\r\n<p>&nbsp;</p>','<p>Technick&eacute; vzděl&aacute;n&iacute; &ndash; pozice je vhodn&aacute; pro zku&scaron;en&eacute; PLC program&aacute;tory<br>Zku&scaron;enosti s programov&aacute;n&iacute; PLC (Step7/TiaPortal) velkou v&yacute;hodou<br>Angličtina nebo němčina na &uacute;rovni domluven&iacute; se (m&iacute;rně pokročil&aacute;)<br>Ochota cestovat (Evropa i exotick&eacute; destinace) a b&yacute;t flexibiln</p>','<p>Men&scaron;&iacute; t&yacute;m, kter&yacute; v&aacute;s bude plně podporovat&nbsp;<br>Možnost pr&aacute;ce na HO až 2 dny v t&yacute;dnu&nbsp;<br>Možnost procestovat zaj&iacute;mav&eacute; destinace v r&aacute;mci Evropy i světa<br>Pravideln&eacute; navy&scaron;ov&aacute;n&iacute; mzdy&nbsp;<br>13. mzda<br>Jazykov&eacute; kurzy na pracovi&scaron;ti&nbsp;<br>5 t&yacute;dnů dovolen&eacute;&nbsp;<br>Stravenky&nbsp;</p>'),
(314,62,1,5,'Elektro konstruktér','Plzeň','<p>Tvorba elektro konstrukce dle požadavků z&aacute;kazn&iacute;ka<br>Budete u převzet&iacute; č&aacute;sti projektů ze zahranič&iacute; do ČR &ndash; vznik nov&eacute;ho oddělen&iacute; v ČR<br>Budete pracovat v mezin&aacute;rodn&iacute;m t&yacute;mů kolegů (ČR + Německo)</p>','<p>Vzděl&aacute;n&iacute; elektrotechnick&eacute;ho směru<br>Znalost programu SolidWorks, AutoCAD, Catia nebo Eplan<br>Anglick&yacute; nebo německ&yacute; jazyk na komunikativn&iacute; &uacute;rovni&nbsp;</p>','<p>Men&scaron;&iacute; t&yacute;m, kter&yacute; v&aacute;s bude plně podporovat&nbsp;<br>Možnost pr&aacute;ce na HO až 2 dny v t&yacute;dnu&nbsp;<br>Možnost procestovat zaj&iacute;mav&eacute; destinace v r&aacute;mci Evropy i světa<br>Pravideln&eacute; navy&scaron;ov&aacute;n&iacute; mzdy&nbsp;<br>13. mzda<br>Jazykov&eacute; kurzy na pracovi&scaron;ti&nbsp;<br>5 t&yacute;dnů dovolen&eacute;&nbsp;<br>Stravenky&nbsp;<br>Flexibiln&iacute; pracovn&iacute; doba</p>'),
(315,66,1,2,'Vedoucí skladu náhradních dílů','Klatovy','<p>Pro autoservis n&aacute;kladn&iacute;ch vozů přijmeme nov&eacute;ho kolegu, kter&yacute; převezme odpovědnost za provoz skladu n&aacute;hradn&iacute;ch d&iacute;lů. Va&scaron;&iacute; hlavn&iacute; starost&iacute; bude postarat se o fungov&aacute;n&iacute;, pl&aacute;nov&aacute;n&iacute;, kontrolu a optim&aacute;ln&iacute; rozvoj skladu.</p>\r\n<p>K ruce V&aacute;m budou 2 kolegov&eacute;, kteř&iacute; se s V&aacute;mi budou pod&iacute;let na zaji&scaron;těn&iacute; ř&aacute;dn&eacute;ho chodu skladu autod&iacute;lů.</p>\r\n<p><strong>Vedouc&iacute; skladu denně zaji&scaron;ťuje:</strong></p>\r\n<ul>\r\n<li>komunikaci s dodavateli (osobn&iacute;, telefonickou, emailovou)</li>\r\n<li>objedn&aacute;vky a n&aacute;kup potřebn&yacute;ch autod&iacute;lů pro n&aacute;kladn&iacute; vozy včetně jejich dopravy</li>\r\n<li>evidenci ve&scaron;ker&yacute;ch objedn&aacute;vek ve firemn&iacute;m objedn&aacute;vkov&eacute;m syst&eacute;mu</li>\r\n<li>evidenci a přehled o stavu skladov&yacute;ch z&aacute;sob</li>\r\n<li>dohl&iacute;ž&iacute; na dodržov&aacute;n&iacute; skladov&yacute;ch z&aacute;sob skladu</li>\r\n<li>prodej n&aacute;hradn&iacute;ch d&iacute;lů</li>\r\n<li>zpracov&aacute;n&iacute; servisn&iacute;ch zak&aacute;zek jako podklad pro fakturaci</li>\r\n<li>fungov&aacute;n&iacute; a rozvoj t&yacute;mu zaměstnanců skladu</li>\r\n</ul>','<ul>\r\n<li>technick&eacute; my&scaron;len&iacute;</li>\r\n<li>znalost v problematice autod&iacute;lůosobn&iacute;ch či n&aacute;kladn&iacute;ch vozidel</li>\r\n<li>organizačn&iacute; a komunikačn&iacute; dovednosti</li>\r\n<li>schopnost veden&iacute; t&yacute;mu a spolupr&aacute;ce s ostatn&iacute;mi t&yacute;my</li>\r\n<li>řidičsk&eacute; opr&aacute;vněn&iacute; skupiny B a ochotu ř&iacute;dit firemn&iacute; vozidlo</li>\r\n<li>znalost proces expedice a př&iacute;jmu zbož&iacute;</li>\r\n<li>schopnost převz&iacute;t odpovědnost a ochotu se rozv&iacute;jet</li>\r\n</ul>','<ul>\r\n<li>dlouhodob&eacute; a jist&eacute; zaměstn&aacute;n&iacute;</li>\r\n<li>pr&aacute;ci na 2 směny &ndash; rann&iacute;, odpoledn&iacute;</li>\r\n<li>př&iacute;ležitost k dal&scaron;&iacute;mu odborn&eacute;mu i osobn&iacute;mu rozvoji</li>\r\n<li>zaj&iacute;mav&eacute; finančn&iacute; ohodnocen&iacute;</li>\r\n<li>modern&iacute; pracovn&iacute; prostřed&iacute;</li>\r\n</ul>'),
(316,66,1,2,'Skladník/Skladnice','Klatovy','<p>Společnost Lorenc Logistic, s.r.o. se s&iacute;dlem v Klatovech poskytuje komplexn&iacute; služby. Jedn&iacute;m &nbsp;z na&scaron;ich hlavn&iacute;ch projektů je poskytov&aacute;n&iacute; skladov&aacute;n&iacute;.<br><strong>Abychom zajistili kvalitn&iacute; službu, potřebujeme kvalitn&iacute; t&yacute;m.</strong></p>\r\n<p>A pr&aacute;vě d&iacute;ky tomu nyn&iacute; hled&aacute;me nov&eacute;ho kolegu do t&yacute;mu skladn&iacute;ků. Pracovn&iacute; m&iacute;sto je k dispozici př&iacute;mo v are&aacute;lu firmy v Klatovech.</p>\r\n<p><strong>Va&scaron;&iacute; hlavn&iacute; činnost&iacute; bude:</strong></p>\r\n<ul>\r\n<li>manipulace s paletov&yacute;m zbož&iacute;m různ&eacute;ho druhu (při př&iacute;jmu / expedici)</li>\r\n<li>obsluha manipulačn&iacute; techniky - n&iacute;zkozdvižn&eacute;, vysokozdvižn&eacute; voz&iacute;ky, syst&eacute;mov&eacute; zakladač &ndash; předchoz&iacute; zku&scaron;enosti v&yacute;hodou</li>\r\n<li>pr&aacute;ce se čtec&iacute;m zař&iacute;zen&iacute;m - př&iacute;prava a tisk etiket včetně označen&iacute; zbož&iacute;<br>zpracov&aacute;n&iacute; a dokumentace &scaron;kodn&iacute;ch ud&aacute;lost&iacute;, vratek zbož&iacute; a reklamac&iacute;</li>\r\n<li>kontrola vozidel při expedici zbož&iacute; povahy ADR<br>spolupr&aacute;ce s ostatn&iacute;mi členy t&yacute;mu</li>\r\n</ul>','<ul>\r\n<li>prokazateln&eacute; zku&scaron;enosti s obsluhou VZV</li>\r\n<li>znalosti z oblasti skladov&eacute;ho hospod&aacute;řstv&iacute;</li>\r\n<li>schopnost t&yacute;mov&eacute; pr&aacute;ce včetně komunikačn&iacute;ch a organizačn&iacute;ch dovednost&iacute;</li>\r\n<li>ochotu pracovat v režimu ponděl&iacute; až p&aacute;tek 6:00 - 14:30 a 8:30 - 17:00</li>\r\n<li>ochotu vzděl&aacute;vat se a pracovat na vlastn&iacute;m rozvoji</li>\r\n</ul>','<ul>\r\n<li>zaj&iacute;mav&eacute; mzdov&eacute; ohodnocen&iacute; s pravideln&yacute;m navy&scaron;ov&aacute;n&iacute;</li>\r\n<li>jist&eacute; a stabiln&iacute; zaměstn&aacute;n&iacute;<br>pr&aacute;ci od ponděl&iacute; do p&aacute;tku</li>\r\n<li>př&aacute;telsk&yacute; kolektiv</li>\r\n<li>nejmoderněj&scaron;&iacute; techniku a vybaven&iacute;</li>\r\n<li>možnost dotovan&eacute;ho stravov&aacute;n&iacute; v are&aacute;lu firmy</li>\r\n<li>osobn&iacute; a profesn&iacute; růst</li>\r\n</ul>'),
(317,66,1,5,'Obchodní manažer/ka pro přepravní systém FOFR','Zdiby','<p>Z&aacute;silkov&aacute; služba Fofr je celorepublikov&aacute; přepravn&iacute; společnost. Tvoř&iacute; ji 8 česk&yacute;ch dopravn&iacute;ch společnost&iacute;. Na&scaron;e společnost spravuje depa v Klatovech, Plzni, v Lovosic&iacute;ch a ve Zdibech.</p>\r\n<p>Pr&aacute;vě na lovosick&eacute; depo hled&aacute;me kolegu/kolegyni na pozici obchodn&iacute;ho managera z&aacute;silkov&eacute; služby Fofr. Kolegu, komunikativn&iacute;ho a odv&aacute;žn&eacute;ho, kter&eacute;ho nezaskoč&iacute; ž&aacute;dn&aacute; v&yacute;zva.</p>\r\n<p><strong>Va&scaron;&iacute; hlavn&iacute; odpovědnost&iacute; bude:</strong></p>\r\n<ul>\r\n<li>aktivně hledat nov&eacute; z&aacute;kazn&iacute;ky</li>\r\n<li>udržet portfolio svěřen&yacute;ch z&aacute;kazn&iacute;ků - udržovat a rozv&iacute;jet s nimi spolupr&aacute;ci</li>\r\n<li>vyslechnout jejich potřeby a snažit se jim maxim&aacute;lně vyhovět</li>\r\n<li>pravideln&eacute; n&aacute;v&scaron;těvy u klientů</li>\r\n<li>spolupr&aacute;ce s ostatn&iacute;mi členy t&yacute;mu na pobočce v Lovosic&iacute;ch</li>\r\n</ul>','<ul>\r\n<li>v&yacute;born&eacute; komunikačn&iacute;, prezentačn&iacute; a organizačn&iacute; dovednosti</li>\r\n<li>zku&scaron;enosti z prodeje</li>\r\n<li>schopnost seri&oacute;zn&iacute;ho vystupov&aacute;n&iacute;</li>\r\n<li>schopnost pr&aacute;ce na PC (pokročila znalosti MS Office)</li>\r\n<li>platn&eacute; řidičsk&eacute; opr&aacute;vněn&iacute; skupiny B včetně ochoty cestovat</li>\r\n<li>silnou motivaci a orientaci na v&yacute;sledky<br>&nbsp;</li>\r\n</ul>','<ul>\r\n<li>pr&aacute;ci v rodinn&eacute; společnosti s mnohaletou tradic&iacute;</li>\r\n<li>jistotu zaměstn&aacute;n&iacute; v jak&eacute;koliv době</li>\r\n<li>z&aacute;zem&iacute; dynamicky se rozv&iacute;jej&iacute;c&iacute; společnosti</li>\r\n<li>vzděl&aacute;vac&iacute; program &ndash; profesn&iacute; a jazykov&eacute; kurzy, kurzy osobn&iacute;ho rozvoje</li>\r\n<li>m&aacute;te-li chuť, můžete s n&aacute;mi růst - vy&scaron;&scaron;&iacute; pozice obsazujeme přednostně z řad st&aacute;vaj&iacute;c&iacute;ch zaměstnanců</li>\r\n<li>&scaron;irokou &scaron;k&aacute;lu firemn&iacute;ch benefitů (př&iacute;spěvek na penzijn&iacute; a životn&iacute; poji&scaron;těn&iacute;, př&iacute;spěvek na stravov&aacute;n&iacute;, finančn&iacute; odměny při pracovn&iacute;m v&yacute;roč&iacute; a životn&iacute;m jubileu, d&aacute;rek k narozenin&aacute;m, modern&iacute; firemn&iacute; oblečen&iacute;, aj.).<br>kulturn&iacute; a sportovn&iacute; vyžit&iacute; &ndash; teambuildingov&eacute; akce, rodinn&yacute; den, sportovn&iacute; den, sobotn&iacute; hokejov&eacute; odpoledne, v&aacute;nočn&iacute; več&iacute;rek</li>\r\n</ul>'),
(318,60,1,4,'QUALITY ADMINISTRATOR','Plzeň','<p>udržov&aacute;n&iacute; syst&eacute;mu ř&iacute;zen&iacute; kvality<br>ře&scaron;en&iacute; probl&eacute;mů, preventivn&iacute;ch i n&aacute;pravn&aacute; opatřen&iacute;<br>zpracov&aacute;n&iacute;, anal&yacute;za a reporting dat kvality<br>organizace a &uacute;čast na porad&aacute;ch o kvalitě<br>participace na ř&iacute;zen&iacute; nestandardn&iacute;ch procesů - Stopshipment, Rework management<br>prov&aacute;děn&iacute; a veden&iacute; auditů kvality<br>tvorba a vyd&aacute;v&aacute;n&iacute; dokumentů (směrnic, specifikac&iacute; a n&aacute;vodek)<br>participace na zlep&scaron;ov&aacute;n&iacute; efektivity oddělen&iacute; kvality<br>spolupr&aacute;ce s ostatn&iacute;mi oddělen&iacute;mi</p>','<p>technick&eacute; vzděl&aacute;n&iacute;<br>znalost z&aacute;kladn&iacute;ch n&aacute;strojů sledov&aacute;n&iacute; kvality<br>prezentačn&iacute; dovednosti<br>technick&eacute; my&scaron;len&iacute;, orientace v technick&eacute; dokumentaci<br>komunikativnost<br>schopnost pracovat v t&yacute;mu i samostatně<br>schopnost v&eacute;st t&yacute;m<br>schopnost efektivně ře&scaron;it probl&eacute;my<br>anglick&yacute; jazyk B1/B2<br>řidičsk&yacute; průkaz sk. B<br>dobr&aacute; uživatelsk&aacute; znalost programů MS OFFICE, zejm&eacute;na MS Excel<br>kvalifikačn&iacute; předpoklad k splněn&iacute; nař&iacute;zen&iacute; vl&aacute;dy 194/2022 v&yacute;hodou<br>znalost chlad&iacute;rensk&yacute;ch/topn&yacute;ch technologi&iacute; v&yacute;hodou<br>intern&iacute; auditor v&yacute;hodou</p>','<p>půlročn&iacute; bonusy<br>měs&iacute;čn&iacute; v&yacute;konnostn&iacute; bonus<br>pracovn&iacute; doba 7:30 - 16:00 hodin<br>z&aacute;zem&iacute; velk&eacute; mezin&aacute;rodn&iacute; společnosti<br>odborn&eacute; za&scaron;kolen&iacute;<br>dotovan&eacute; z&aacute;vodn&iacute; stravov&aacute;n&iacute;<br>př&iacute;spěvek na penzijn&iacute; či životn&iacute; poji&scaron;těn&iacute; až 700 Kč/měs&iacute;čně<br>program Cafeteria až 14 tis&iacute;c ročně (dle vlastn&iacute;ho v&yacute;běru na sport, kulturu, zdrav&iacute; či vzděl&aacute;van&iacute;)<br>5 t&yacute;dnů dovolen&eacute;<br>možnost parkovan&iacute; př&iacute;mo v are&aacute;lu společnosti<br>v&yacute;born&aacute; dostupnost MHD</p>'),
(319,60,1,3,'Frézař - Obsluha CNC','Plzeň','<p>obsluha 5-ti os&eacute;ho CNC stroje (Mazak Variaxis - ř&iacute;d&iacute;c&iacute; syst&eacute;m Mazatrol)<br>čten&iacute; technick&eacute; dokumentace a zad&aacute;v&aacute;n&iacute; dat do ř&iacute;d&iacute;c&iacute;ho syst&eacute;mu<br>v&yacute;běr n&aacute;strojů, nastavov&aacute;n&iacute; a seřizov&aacute;n&iacute; CNC stroje<br>koordinace procesu v&yacute;roby<br>kontroln&iacute; měřen&iacute; vyroben&yacute;ch d&iacute;lů<br>spolupr&aacute;ce s technologi&iacute; a konstrukc&iacute;</p>','<p>technick&eacute; vzděl&aacute;n&iacute;<br>zku&scaron;enosti a praxe na CNC fr&eacute;zce<br>5ti-os&eacute; programov&aacute;n&iacute; v SolidCAM (v&yacute;hodou)<br>orientace v technick&eacute; dokumentaci a měřidlech<br>logick&eacute; a technick&eacute; my&scaron;len&iacute;<br>manu&aacute;ln&iacute; zručnost<br>př&aacute;telsk&yacute; t&yacute;mov&yacute; hr&aacute;č</p>','<p>měs&iacute;čn&iacute; v&yacute;konnostn&iacute; bonus<br>půlročn&iacute; bonusy<br>dotovan&eacute; z&aacute;vodn&iacute; stravov&aacute;n&iacute;<br>bonusov&yacute; program Cafeteria Pluxee<br>př&iacute;spěvek na penzijn&iacute; poji&scaron;těn&iacute; až 700 Kč/měs&iacute;c<br>5 t&yacute;dnů dovolen&eacute;<br>firemn&iacute; akce<br>dal&scaron;&iacute; zaměstnaneck&eacute; v&yacute;hody</p>'),
(320,60,1,3,'UDRŽBÁŘ LISOVACÍCH FOREM','Plzeň','<p>&uacute;držba lisovac&iacute;ch forem<br>kontrola komponentů, demont&aacute;ž a mont&aacute;ž lisovac&iacute; formy<br>pl&aacute;nov&aacute;n&iacute; oprav a &uacute;prav dle požadavků v&yacute;roby<br>spolupr&aacute;ce na př&iacute;pravě denn&iacute; a periodick&eacute; &uacute;držby n&aacute;strojů<br>podpora při zaji&scaron;ťov&aacute;n&iacute; oprav a modifikac&iacute; n&aacute;strojů u dodavatelů<br>podpora R&amp;D při v&yacute;voji n&aacute;strojů<br>obsluha strojn&iacute;ho vybaven&iacute; - svařov&aacute;n&iacute;, soustružen&iacute;, brou&scaron;en&iacute; atd.</p>','<p>technick&eacute; vzděl&aacute;n&iacute; nebo vyučen&iacute; v oboru<br>zku&scaron;enost s &uacute;držbou a mont&aacute;ž&iacute; lisovac&iacute;ch forem<br>znalost čten&iacute; v&yacute;kresov&eacute; dokumentace<br>znalost pr&aacute;ce s PC<br>ochota k př&iacute;ležitostn&yacute;m služebn&iacute;m cest&aacute;m<br>sv&aacute;řec&iacute; průkaz v&yacute;hodou<br>AJ v&yacute;hodou</p>','<p>půlročn&iacute; bonusy<br>měs&iacute;čn&iacute; v&yacute;konnostn&iacute; bonus<br>n&aacute;borov&yacute; bonus 25 000 Kč<br>z&aacute;zem&iacute; velk&eacute; mezin&aacute;rodn&iacute; společnosti<br>odborn&eacute; za&scaron;kolen&iacute;<br>dotovan&eacute; z&aacute;vodn&iacute; stravov&aacute;n&iacute;<br>př&iacute;spěvek na penzijn&iacute; poji&scaron;těn&iacute; až 700 Kč/měs&iacute;čně<br>program Cafeteria (dle vlastn&iacute;ho v&yacute;běru na sport, kulturu, zdrav&iacute; či vzděl&aacute;van&iacute;)<br>5 t&yacute;dnů dovolen&eacute;<br>firemn&iacute; akce<br>možnost parkovan&iacute; př&iacute;mo v are&aacute;lu společnosti<br>v&yacute;born&aacute; dostupnost MHD</p>'),
(321,79,1,5,'Logistický Specialista','Plzeň','<p>Pokračujeme ve sv&eacute;m &uacute;spě&scaron;n&eacute;m růstu po cel&eacute;m světě, a to se t&yacute;k&aacute; i na&scaron;eho plzeňsk&eacute;ho t&yacute;mu. Hled&aacute;te uplatněn&iacute; s mezin&aacute;rodn&iacute;m přesahem? Pak možn&aacute; hled&aacute;me pr&aacute;vě V&aacute;s.</p>\r\n<p><strong>Co bude Va&scaron;&iacute;m posl&aacute;n&iacute;m:</strong></p>\r\n<p>Jako člen na&scaron;eho t&yacute;mu (každ&yacute; z n&aacute;s je &ldquo;4flower&rdquo;), budete efektivně ř&iacute;dit pohyb zbož&iacute; koordinac&iacute; s&iacute;tě logistick&yacute;ch služeb na&scaron;ich z&aacute;kazn&iacute;ků a aktivně využ&iacute;vat angličtinu.</p>\r\n<p><strong>Va&scaron;e hlavn&iacute; &uacute;koly zahrnuj&iacute; mimo jin&eacute;:</strong></p>\r\n<ul>\r\n<li>Zaji&scaron;těn&iacute; hladk&eacute;ho průběhu v&scaron;ech oblast&iacute; transportn&iacute; s&iacute;tě na denn&iacute; b&aacute;zi, pomoc&iacute; na&scaron;eho intern&iacute;ho syst&eacute;mu (TMS)</li>\r\n<li>Poskytov&aacute;n&iacute; služeb z&aacute;kaznick&eacute;ho servisu, jako např. spr&aacute;va přepravn&iacute; objedn&aacute;vky, komunikace se z&aacute;kazn&iacute;ky /partnery, zpracov&aacute;n&iacute; faktur</li>\r\n<li>Zpracov&aacute;n&iacute; nestandardn&iacute;ch př&iacute;padů v přepravě a zaji&scaron;těn&iacute; spr&aacute;vn&eacute; a včasn&eacute; informovanosti v&scaron;ech z&uacute;častněn&yacute;ch stran</li>\r\n<li>Odpovědnost za vyře&scaron;en&iacute; př&iacute;padů zpožděn&yacute;ch transportů (vyhled&aacute;n&iacute; a zabezpečen&iacute; realizace, včetně komunikace)</li>\r\n<li>Podpora neust&aacute;l&eacute; optimalizace logistick&eacute; s&iacute;tě z&aacute;kazn&iacute;ků</li>\r\n</ul>\r\n<p>&nbsp;</p>','<ul>\r\n<li>Ide&aacute;lně ukončen&eacute; V&Scaron; vzděl&aacute;n&iacute; logistick&eacute;ho směru nebo ukončen&eacute; S&Scaron; s relevantn&iacute; prax&iacute; (min. 2 roky)</li>\r\n<li>Praktick&eacute; zku&scaron;enosti v dopravn&iacute;m či transportn&iacute;m průmyslu, v prostřed&iacute; s vysokou orientac&iacute; na z&aacute;kazn&iacute;ka</li>\r\n<li>Zvl&aacute;dnut&iacute; komunikace v anglick&eacute;m jazyce (min. B2 &uacute;roveň) &ndash; nutn&aacute; efektivn&iacute; forma, a to p&iacute;semn&aacute; i &uacute;stn&iacute;, každ&yacute; dal&scaron;&iacute; ciz&iacute; jazyk je v&yacute;hodou ide&aacute;lně němčina, francouz&scaron;tina, &scaron;paněl&scaron;tina)<br>Aktivn&iacute; uživatelskou znalost MS Office</li>\r\n<li>Z&aacute;jem o obor logistiky spolu se schopnost&iacute; pracovat v dynamick&eacute;m prostřed&iacute;</li>\r\n<li>Schopnost spr&aacute;vně si nastavit priority a pr&aacute;ce pod tlakem (nutn&aacute; asertivn&iacute; a př&aacute;telsk&aacute; komunikace)</li>\r\n</ul>\r\n<p>Jako glob&aacute;ln&iacute; společnost &uacute;zce spolupracujeme s na&scaron;imi pobočkami v dal&scaron;&iacute;ch zem&iacute;ch a je tedy možn&eacute;, že i Va&scaron;e v&yacute;běrov&eacute; ř&iacute;zen&iacute; bude vedeno HR kolegy ze zahranič&iacute; (např. z Německa nebo Maďarska). Životopis tedy pros&iacute;m zas&iacute;lejte <strong>pouze v anglick&eacute;m jazyce.</strong></p>','<p>Stanete se souč&aacute;st&iacute; &uacute;spě&scaron;n&eacute; mezin&aacute;rodn&iacute; společnosti, kter&aacute; nab&iacute;z&iacute; unik&aacute;tn&iacute; př&iacute;stupy a znalosti a s t&iacute;m ruku v ruce i &scaron;irokou moznost rozvoje a vzděl&aacute;v&aacute;n&iacute;. T&yacute;mově zaměřen&aacute; firemn&iacute; kultura se u n&aacute;s skutečně žije.</p>\r\n<p><strong>Někter&eacute; z benefitů, kter&eacute; využ&iacute;v&aacute;me:</strong></p>\r\n<ul>\r\n<li>Modern&iacute; pracovi&scaron;tě v centru Plzně, s možnost&iacute; využit&iacute; &ldquo;Home Office&rdquo;</li>\r\n<li>Kvalitn&iacute; a vyzkou&scaron;en&yacute; syst&eacute;m zaučen&iacute; a vzděl&aacute;v&aacute;n&iacute;</li>\r\n<li>Jazykov&aacute; v&yacute;uka němčiny a francouz&scaron;tiny</li>\r\n<li>Odměnov&yacute; program za doporučen&iacute; kolegů</li>\r\n<li>Podpora individu&aacute;ln&iacute;ho vzděl&aacute;v&aacute;n&iacute; a osobn&iacute;ho rozvoje</li>\r\n<li>E-card s volnočasov&yacute;mi benefity a stravenkami</li>\r\n<li>Dostupnost odborn&eacute;ho poradenstv&iacute; pro zaměstnance 24/7</li>\r\n<li>N&aacute;poje a ovoce na pracovi&scaron;ti, několikr&aacute;t t&yacute;dně zaji&scaron;těn&eacute; snacky při pr&aacute;ci v kancel&aacute;ři</li>\r\n</ul>'),
(322,79,1,5,'Specialista zákaznic. servisu v logistice','Plzeň','<p>Jako člen na&scaron;eho t&yacute;mu (každ&yacute; z n&aacute;s je &ldquo;4flower&rdquo;), budete prvn&iacute; kontaktn&iacute; osobou pro na&scaron;e z&aacute;kazn&iacute;ky, kteř&iacute; opravdu spol&eacute;haj&iacute; na va&scaron;i podporu ve v&scaron;ech ohledech a situac&iacute;ch.</p>\r\n<p><strong>Va&scaron;e hlavn&iacute; &uacute;koly zahrnuj&iacute; mimo jin&eacute;:</strong></p>\r\n<ul>\r\n<li>Poskytov&aacute;n&iacute; profesion&aacute;ln&iacute; z&aacute;kaznick&eacute; podpory a to jak telefonicky, tak v e-mailov&eacute; komunikaci - prim&aacute;rně v anglick&eacute;m jazyce; znalost dal&scaron;&iacute;ch ciz&iacute;ch jazyků je velkou v&yacute;hodou</li>\r\n<li>Hled&aacute;n&iacute; a realizace smyslupln&yacute;ch a efektivn&iacute;ch ře&scaron;en&iacute; ve stresov&yacute;ch situac&iacute;ch, zaměřen&iacute; na důležit&eacute; detaily</li>\r\n<li>Zji&scaron;ťov&aacute;n&iacute; a včasn&eacute; ře&scaron;en&iacute; z&aacute;kaznick&yacute;ch dotazů</li>\r\n<li>Rychlou reakci a proaktivn&iacute; pr&aacute;ci</li>\r\n<li>Spr&aacute;vn&eacute; nastaven&iacute; priorit v dynamick&eacute;m, rychle se měn&iacute;c&iacute;m prostřed&iacute; logistiky</li>\r\n</ul>','<ul>\r\n<li>Ukončen&eacute; min. S&Scaron; vzděl&aacute;n&iacute;</li>\r\n<li>Zvl&aacute;d&aacute;te komunikaci v anglick&eacute;m jazyce (min. B2 &uacute;roveň) &ndash; nutn&aacute; efektivn&iacute; komunikace, a to p&iacute;semn&aacute; i &uacute;stn&iacute;, každ&yacute; dal&scaron;&iacute; ciz&iacute; jazyk je v&yacute;hodou</li>\r\n<li>Um&iacute;te naslouchat a vc&iacute;tit se do pozice z&aacute;kazn&iacute;ka natolik, abyste dok&aacute;zali navrhnout vhodn&eacute; ře&scaron;en&iacute; pro v&scaron;echny zainteresovan&eacute; strany</li>\r\n<li>Ochotu a schopnost se učit - nevad&iacute;, že nem&aacute;te praxi v logistice, v&scaron;e v&aacute;s nauč&iacute;me</li>\r\n</ul>\r\n<p>Jako glob&aacute;ln&iacute; společnost &uacute;zce spolupracujeme s na&scaron;imi pobočkami v dal&scaron;&iacute;ch zem&iacute;ch a je tedy možn&eacute;, že i Va&scaron;e v&yacute;běrov&eacute; ř&iacute;zen&iacute; bude vedeno HR kolegy ze zahranič&iacute; (např. z Německa nebo Maďarska). Životopis tedy pros&iacute;m zas&iacute;lejte <strong>pouze v anglick&eacute;m jazyce.</strong></p>','<p>Stanete se souč&aacute;st&iacute; &uacute;spě&scaron;n&eacute; mezin&aacute;rodn&iacute; společnosti, kter&aacute; nab&iacute;z&iacute; unik&aacute;tn&iacute; př&iacute;stupy a znalosti a s t&iacute;m ruku v ruce i &scaron;irokou moznost rozvoje a vzděl&aacute;v&aacute;n&iacute;. T&yacute;mově zaměřen&aacute; firemn&iacute; kultura se u n&aacute;s skutečně žije.</p>\r\n<p><strong>Někter&eacute; z benefitů, kter&eacute; využ&iacute;v&aacute;me:</strong></p>\r\n<ul>\r\n<li>Modern&iacute; pracovi&scaron;tě v centru Plzně, s možnost&iacute; využit&iacute; &ldquo;Home Office&rdquo;</li>\r\n<li>Kvalitn&iacute; a vyzkou&scaron;en&yacute; syst&eacute;m zaučen&iacute; a vzděl&aacute;v&aacute;n&iacute;</li>\r\n<li>Jazykov&aacute; v&yacute;uka němčiny a francouz&scaron;tiny</li>\r\n<li>Odměnov&yacute; program za doporučen&iacute; kolegů</li>\r\n<li>Podpora individu&aacute;ln&iacute;ho vzděl&aacute;v&aacute;n&iacute; a osobn&iacute;ho rozvoje</li>\r\n<li>E-card s volnočasov&yacute;mi benefity a stravenkami</li>\r\n<li>Dostupnost odborn&eacute;ho poradenstv&iacute; pro zaměstnance 24/7</li>\r\n<li>N&aacute;poje a ovoce na pracovi&scaron;ti, několikr&aacute;t t&yacute;dně zaji&scaron;těn&eacute; snacky při pr&aacute;ci v kancel&aacute;ři</li>\r\n</ul>'),
(323,69,1,4,'obchodní pozice','Plzeňský kraj','<p>Co u n&aacute;s budete každ&yacute; den dělat?</p>\r\n<ul>\r\n<li>spravovat a roz&scaron;iřovat pojistn&yacute; kmen</li>\r\n<li>pečovat o st&aacute;vaj&iacute;c&iacute; klienty</li>\r\n<li>prod&aacute;vat pojistn&eacute;h produkty, kter&eacute; lze roz&scaron;&iacute;řit i o prodej/tipov&aacute;n&iacute; bankovn&iacute;ch produktů</li>\r\n<li>informovat klienty o aktu&aacute;ln&iacute;m stavu jejich poji&scaron;těn&iacute; a navrhovat optim&aacute;ln&iacute; ře&scaron;en&iacute; na z&aacute;kladě jejich potřeb a požadavků</li>\r\n<li>pom&aacute;hat při ře&scaron;en&iacute; pojistn&yacute;ch ud&aacute;lost&iacute;</li>\r\n</ul>','<ul>\r\n<li>obchodn&iacute;ho ducha, samostatnost a orientaci na v&yacute;sledek</li>\r\n<li>chuť vzděl&aacute;vat se, růst a něco dok&aacute;zat</li>\r\n<li>dobr&eacute; komunikačn&iacute; dovednosti</li>\r\n<li>př&iacute;jemn&eacute; a profesion&aacute;ln&iacute; vystupov&aacute;n&iacute;</li>\r\n<li>maturitn&iacute; vysvědčen&iacute;</li>\r\n<li>řidičsk&yacute; průkaz skupiny B</li>\r\n<li>čist&yacute; trestn&iacute; a insolvenčn&iacute; rejstř&iacute;k je samozřejmost&iacute;, mus&iacute;me trvat i na absenci exekuc&iacute;</li>\r\n</ul>','<ul>\r\n<li>nadprůměrn&eacute; a motivačn&iacute; finančn&iacute; ohodnocen&iacute;</li>\r\n<li>zaj&iacute;mav&eacute; slevy u na&scaron;ich obchodn&iacute;ch partnerů</li>\r\n<li>z&aacute;zem&iacute; stabiln&iacute; poji&scaron;ťovny a mezin&aacute;rodn&iacute; skupiny Vienna Insurance Group</li>\r\n<li>pr&aacute;ce v t&yacute;mu zku&scaron;en&yacute;ch parť&aacute;ků, kteř&iacute; v&aacute;s bez zav&aacute;h&aacute;n&iacute; podpoř&iacute;, když o to budete st&aacute;t</li>\r\n</ul>'),
(324,77,1,3,'Provozní elektrikář','Stříbrská 369, Stod','<p style=\"text-align: center;\">Hled&aacute;me kolegu, kter&yacute; zajist&iacute; plynul&yacute; chod na&scaron;ich v&yacute;robn&iacute;ch linek a elektrozař&iacute;zen&iacute;. Pokud se vyzn&aacute;&scaron; v elektro&uacute;držbě a chce&scaron; b&yacute;t kl&iacute;čov&yacute;m hr&aacute;čem při zaji&scaron;ťov&aacute;n&iacute; provozu, pak hled&aacute;me pr&aacute;vě tebe!</p>\r\n<p><strong>Co tě u n&aacute;s ček&aacute;?</strong></p>\r\n<ul>\r\n<li>preventivn&iacute; &uacute;držba a opravy zař&iacute;zen&iacute; v&yacute;robn&iacute;ch linek a elektrozař&iacute;zen&iacute; budov (PLC, frekvenčn&iacute; měniče, motory, senzory)</li>\r\n<li>anal&yacute;za a rychl&eacute; ře&scaron;en&iacute; technick&yacute;ch probl&eacute;mů</li>\r\n<li>pr&aacute;ce ve směnn&eacute;m režimu (3 dny 5:00 &ndash; 17:00, 3 dny volno, 3 dny 17:00 &ndash; 5:00, 3 dny volno)</li>\r\n</ul>','<ul>\r\n<li>vzděl&aacute;n&iacute; v oboru elektro<br>odbornou způsobilost dle &sect; 6 nař&iacute;zen&iacute; vl&aacute;dy č. 194/2022 Sb. &ndash; elektrotechnik</li>\r\n<li>znalost elektro dokumentace</li>\r\n<li>flexibilitu, spolehlivost a pečlivost</li>\r\n<li>praxe na obdobn&eacute; pozici - v&yacute;hodou</li>\r\n<li>znalost PLC syst&eacute;mů - v&yacute;hodou<br>řidičsk&yacute; průkaz skupiny B, C - v&yacute;hodou</li>\r\n</ul>','<ul>\r\n<li>n&aacute;stup ihned</li>\r\n<li>n&aacute;borov&yacute; př&iacute;spěvek 70 000 Kč</li>\r\n<li>5 t&yacute;dnů dovolen&eacute;</li>\r\n<li>stravenkov&yacute; pau&scaron;&aacute;l a n&aacute;poje na pracovi&scaron;ti</li>\r\n<li>př&iacute;spěvek na penzijn&iacute; poji&scaron;těn&iacute; 1.500 Kč měs&iacute;čně</li>\r\n<li>v př&iacute;padě splněn&iacute; hospod&aacute;řsk&eacute;ho v&yacute;sledku cel&eacute; firmy 13. mzda</li>\r\n<li>podle dojezdov&eacute; vzd&aacute;lenosti př&iacute;spěvek na doj&iacute;žděn&iacute; (80 Kč za 1 km, max. 4.000 Kč)</li>\r\n<li>program kafeterie od Pluxee (b&yacute;val&eacute; Sodexo) - pravideln&eacute; ročn&iacute; př&iacute;spěvky + možnost z&iacute;sk&aacute;n&iacute; individu&aacute;ln&iacute;ch př&iacute;spěvků např. za inovace</li>\r\n<li>Multisport karta 430 Kč měs&iacute;čně</li>\r\n<li>zaměstnaneck&eacute; slevy na produkty - vyr&aacute;b&iacute;me stře&scaron;n&iacute; ta&scaron;ky Tondach, cihly Porotherm, betonov&eacute; prvky Semmelrock, potrub&iacute; Pipelife</li>\r\n<li>odměna za odpracovan&eacute; roky</li>\r\n<li>odměna za životn&iacute; jubilea</li>\r\n<li>pr&aacute;vn&iacute; poradenstv&iacute; zdarma aj.</li>\r\n</ul>'),
(326,77,1,2,'Dělník keramické výroby','Stříbrská 369, Stod','<p style=\"text-align: center;\">Neboj&iacute;&scaron; se poř&aacute;dn&eacute; pr&aacute;ce? Chce&scaron;, aby pod tv&yacute;ma rukama vznikala kvalitn&iacute; stře&scaron;n&iacute; krytina?</p>\r\n<p style=\"text-align: center;\">Tak se přidej!</p>\r\n<p><strong>Co tě u n&aacute;s ček&aacute;?</strong></p>\r\n<ul>\r\n<li>obsluha plně a polo automatizovan&yacute;ch strojů na v&yacute;robu stře&scaron;n&iacute;ch ta&scaron;ek Tondach</li>\r\n<li>pr&aacute;ce v nepřetržit&eacute;m režimu (6:00 &ndash; 18:00, 3 dny pr&aacute;ce - 3 dny volno) nebo ve dvousměnn&eacute;m režimu (3 dny 6:00 &ndash; 14:45, 3 dny 17:00 &ndash; 1:45, 3 dny volno)</li>\r\n</ul>','<ul>\r\n<li>spolehlivost, zodpovědnost a chuť učit se nov&eacute; věci</li>\r\n<li>ochotu pracovat ve směnn&eacute;m režimu</li>\r\n</ul>','<ul>\r\n<li>n&aacute;stup ihned</li>\r\n<li>n&aacute;borov&yacute; př&iacute;spěvek 70 000 Kč</li>\r\n<li>5 t&yacute;dnů dovolen&eacute;</li>\r\n<li>z&aacute;vodn&iacute; stravov&aacute;n&iacute; a n&aacute;poje na pracovi&scaron;ti</li>\r\n<li>př&iacute;spěvek na penzijn&iacute; poji&scaron;těn&iacute; 1.500 Kč měs&iacute;čně</li>\r\n<li>v př&iacute;padě splněn&iacute; hospod&aacute;řsk&eacute;ho v&yacute;sledku cel&eacute; firmy 13. mzda</li>\r\n<li>podle dojezdov&eacute; vzd&aacute;lenosti př&iacute;spěvek na doj&iacute;žděn&iacute; (80 Kč za 1 km, max. 4.000 Kč)</li>\r\n<li>program kafeterie od Pluxee (b&yacute;val&eacute; Sodexo) - pravideln&eacute; ročn&iacute; př&iacute;spěvky + možnost z&iacute;sk&aacute;n&iacute; individu&aacute;ln&iacute;ch př&iacute;spěvků např. za inovace</li>\r\n<li>Multisport karta 430 Kč měs&iacute;čně</li>\r\n<li>zaměstnaneck&eacute; slevy na produkty - vyr&aacute;b&iacute;me stře&scaron;n&iacute; ta&scaron;ky Tondach, cihly Porotherm, betonov&eacute; prvky Semmelrock, potrub&iacute; Pipelife</li>\r\n<li>odměna za odpracovan&eacute; roky</li>\r\n<li>odměna za životn&iacute; jubilea</li>\r\n<li>pr&aacute;vn&iacute; poradenstv&iacute; zdarma aj.</li>\r\n</ul>'),
(327,71,1,5,'IT ADMINISTRÁTOR JUNIOR','Bor u Tachova','<ul>\r\n<li>Poskytov&aacute;n&iacute; IT podpory koncov&yacute;m uživatelům (1st level support &ndash; SW/HW/WMS)</li>\r\n<li>Instalace/konfigurace IT vybaven&iacute; a profilů uživatelů</li>\r\n<li>&Uacute;držba a spr&aacute;va zař&iacute;zen&iacute; (PC, tisk&aacute;rny, scenery apod.)</li>\r\n<li>Spr&aacute;va dokumentac&iacute; a uživatelsk&yacute;ch n&aacute;vodů</li>\r\n<li>Pr&aacute;ce v tiketovac&iacute;m syst&eacute;mu Jira, pr&aacute;ce s Confluence a SOTI</li>\r\n<li>Komunikace s mezin&aacute;rodn&iacute;mi IT t&yacute;my a spolupr&aacute;ce s extern&iacute;mi dodavateli</li>\r\n</ul>','<ul>\r\n<li>Min. S&Scaron; vzděl&aacute;n&iacute; v oboru IT nebo alespoň 1 rok zku&scaron;enost v tomto oboru</li>\r\n<li>Znalost spr&aacute;vy OS Windows a zku&scaron;enost s poč&iacute;tačov&yacute;mi s&iacute;těmi</li>\r\n<li>Komunikativn&iacute; znalost AJ nebo NJ</li>\r\n<li>Řidičsk&eacute; opr&aacute;vněn&iacute; sk. B.</li>\r\n<li>Z&aacute;jem o IT a nov&eacute; technologie</li>\r\n<li>Ochotu pracovat ve dvousměnn&eacute;m provozu</li>\r\n</ul>','<ul>\r\n<li>Zaj&iacute;mavou a zodpovědnou činnost v ekonomicky zdrav&eacute;, modern&iacute; rodinn&eacute; společnosti s plochou hierarchickou strukturou</li>\r\n<li>Př&iacute;jemn&eacute; pracovn&iacute; prostřed&iacute; a př&aacute;telsk&yacute; kolektiv</li>\r\n<li>Stabiln&iacute; a dlouhodobou spolupr&aacute;ci</li>\r\n<li>Motivuj&iacute;c&iacute; finančn&iacute; ohodnocen&iacute;</li>\r\n<li>Ročn&iacute; bonus až do v&yacute;&scaron;e 100% měs&iacute;čn&iacute; mzdy</li>\r\n<li>Př&iacute;spěvek na stravov&aacute;n&iacute;</li>\r\n<li>5 t&yacute;dnů dovolen&eacute;</li>\r\n<li>Teambuildingy / Workshopy</li>\r\n<li>&Scaron;kolen&iacute; a vzděl&aacute;v&aacute;n&iacute; včetně jazykov&yacute;ch kurzů v r&aacute;mci pracovn&iacute; doby</li>\r\n<li>Zv&yacute;hodněn&eacute; mobiln&iacute; tarify</li>\r\n<li>Odměna za doporučen&iacute; nov&eacute;ho zaměstnance</li>\r\n<li>N&aacute;stup možn&yacute; ihned nebo domluvou</li>\r\n</ul>'),
(328,71,1,4,'FINANČNÍ ÚČETNÍ','','<ul>\r\n<li>Anal&yacute;za měs&iacute;čn&iacute;ch ukazatelů (n&aacute;klady, zisky a ztr&aacute;ty, bilance), zji&scaron;ťov&aacute;n&iacute; odchylek</li>\r\n<li>Kontrola spr&aacute;vnosti roz&uacute;čtov&aacute;n&iacute; n&aacute;kladů na jednotliv&eacute; projekty</li>\r\n<li>Kontrola dodavatelsk&yacute;ch faktur</li>\r\n<li>Podpora při měs&iacute;čn&iacute;m vyhodnocen&iacute; v&yacute;sledků s jednotliv&yacute;mi oddělen&iacute;mi operativy</li>\r\n<li>Spolupr&aacute;ce, podpora a zastupov&aacute;n&iacute; oddělen&iacute; n&aacute;kupu</li>\r\n<li>Spolupr&aacute;ce s koncernov&yacute;m BU Controllerem</li>\r\n<li>&Uacute;čast na finančn&iacute;m pl&aacute;nov&aacute;n&iacute;</li>\r\n<li>Pr&aacute;ce v &uacute;četn&iacute;m programu Helios</li>\r\n<li>Sestavov&aacute;n&iacute; podkladů k měs&iacute;čn&iacute;mu reportingu</li>\r\n<li>&Uacute;čast na implementaci nov&eacute;ho ERP SAP S/4 Hana Cloud &ndash; nastavov&aacute;n&iacute;, testov&aacute;n&iacute;, kontrola v&yacute;stupů</li>\r\n<li>Podpora při ročn&iacute;ch inventur&aacute;ch majetku a z&aacute;sob</li>\r\n<li>Kontrola skladov&yacute;ch operac&iacute; a spolupr&aacute;ce s technick&yacute;m oddělen&iacute;m</li>\r\n</ul>','<ul>\r\n<li>S&Scaron; vzděl&aacute;n&iacute; ekonomick&eacute;ho směru</li>\r\n<li>Komplexn&iacute; orientace v &uacute;četn&iacute; a daňov&eacute; problematice, včetně prokazateln&eacute; aktivn&iacute; praxe</li>\r\n<li>Velmi dobr&aacute; uživatelsk&aacute; znalost MS Office (předev&scaron;&iacute;m Excel), Helios a SAP v&yacute;hodou</li>\r\n<li>Pokročil&aacute; znalost německ&eacute;ho nebo anglick&eacute;ho jazyka</li>\r\n<li>V&yacute;born&aacute; znalost česk&eacute;ho jazyka</li>\r\n<li>Samostatn&yacute; a zodpovědn&yacute; př&iacute;stup k pr&aacute;ci</li>\r\n<li>Analytick&eacute; my&scaron;len&iacute;, pečlivost, spolehlivost a smysl pro t&yacute;movou pr&aacute;ci</li>\r\n</ul>','<ul>\r\n<li>Zaj&iacute;mavou a zodpovědnou činnost v ekonomicky zdrav&eacute;, modern&iacute; rodinn&eacute; společnosti s plochou hierarchickou strukturou</li>\r\n<li>Př&iacute;jemn&eacute; pracovn&iacute; prostřed&iacute; a př&aacute;telsk&yacute; kolektiv</li>\r\n<li>Stabiln&iacute; a dlouhodobou spolupr&aacute;ci</li>\r\n<li>&Scaron;kolen&iacute; a vzděl&aacute;v&aacute;n&iacute; včetně jazykov&yacute;ch kurzů v r&aacute;mci pracovn&iacute; doby</li>\r\n<li>Motivuj&iacute;c&iacute; finančn&iacute; ohodnocen&iacute;</li>\r\n<li>Ročn&iacute; bonus až do v&yacute;&scaron;e 100% měs&iacute;čn&iacute; mzdy</li>\r\n<li>Zv&yacute;hodněn&eacute; bankovn&iacute; produkty a mobiln&iacute; tarify</li>\r\n<li>Př&iacute;spěvek na stravov&aacute;n&iacute;</li>\r\n<li>Odměnu za doporučen&iacute; nov&eacute;ho zaměstnance</li>\r\n<li>5 t&yacute;dnů dovolen&eacute;</li>\r\n<li>Home office až dva dny v t&yacute;dnu</li>\r\n<li>Flexibiln&iacute; pracovn&iacute; dobu</li>\r\n</ul>'),
(329,42,1,4,'Finanční poradce ( Junior, Senior)','Plzeň, Tachov, Domažlice, Beroun','<p><strong>Nov&yacute; rok, nov&aacute; pr&aacute;ce v Raiffce? Samozřejmě!</strong></p>\r\n<p>M&iacute;sto pracovi&scaron;tě:&nbsp;</p>\r\n<p>Můžete si vybrat z oblasti: Plzeň, Tachov, Domažlice, Rakovn&iacute;k nebo Beroun</p>\r\n<p>Typ &uacute;vazku: Pr&aacute;ce na pln&yacute; &uacute;vazek, Pr&aacute;ce na zkr&aacute;cen&yacute; &uacute;vazek</p>\r\n<p><br>Typ smluvn&iacute;ho vztahu: Pr&aacute;ce na živnostensk&yacute; list (IČO)</p>\r\n<p>D&eacute;lka pracovn&iacute;ho poměru: Na dobu neurčitou</p>\r\n<p><br>BenefityBonusy/pr&eacute;mie, Firemn&iacute; akce, Individu&aacute;ln&iacute; rozvržen&iacute; pracovn&iacute; doby, Manažersk&yacute; motivačn&iacute; program, Profesn&iacute;/osobn&iacute; kouč, Provize z prodeje, Sleva na firemn&iacute; v&yacute;robky/služby, Vlastn&iacute; organizace n&aacute;plně pr&aacute;ce, Vzděl&aacute;vac&iacute; kurzy, &scaron;kolen&iacute;<br>Požadovan&eacute; vzděl&aacute;n&iacute;Středo&scaron;kolsk&eacute; nebo odborn&eacute; vyučen&iacute; s maturitou</p>\r\n<p><br>Požadovan&eacute; jazykyČe&scaron;tina (v&yacute;born&aacute;)<br>Pozice je vhodn&aacute; i pro absolventy.<br>Pozice je vhodn&aacute; i pro důchodce.<br>Pozice je vhodn&aacute; i pro rodiče na mateřsk&eacute; a rodičovsk&eacute; dovolen&eacute;.</p>\r\n<p>&nbsp;</p>','<p>Na&scaron;e pr&aacute;ce je předev&scaron;&iacute;m o budov&aacute;n&iacute; dlouhodob&yacute;ch vztahů s klienty.</p>\r\n<p>Budete se snažit, abyste byl/a prvn&iacute;, na koho si klient vzpomene, kdykoliv bude potřebovat ře&scaron;it cokoliv t&yacute;kaj&iacute;c&iacute; se jeho financ&iacute;.</p>\r\n<p><br>Naslouch&aacute;me potřeb&aacute;m klientů, kter&yacute;m hled&aacute;me a nach&aacute;z&iacute;me ře&scaron;en&iacute; na m&iacute;ru.</p>\r\n<p><br>RSTS už d&aacute;vno nen&iacute; jen o stavebn&iacute;m spořen&iacute;.</p>\r\n<p>Pracujeme s &scaron;irok&yacute;m portfoliem produktů, kter&eacute; klientům d&aacute;vaj&iacute; smysl a usnadňuj&iacute; jim život v každ&eacute; etapě.</p>\r\n<p>Čist&yacute; trestn&iacute; rejstř&iacute;k a (alespoň) maturitn&iacute; vysvědčen&iacute; je z&aacute;klad, bez kter&eacute;ho se nepohneme d&aacute;l.</p>\r\n<p><br>M&aacute;te otevřenou mysl a chuť do pr&aacute;ce.</p>\r\n<p><br>Pr&aacute;ce s lidmi v&aacute;m děl&aacute; radost, ať už se jedn&aacute; o klienty nebo kolegy.</p>\r\n<p><br>D&aacute;v&aacute; v&aacute;m to smysl? V&yacute;borně! R&aacute;di se s v&aacute;mi o možnostech spolupr&aacute;ce pobav&iacute;me. V&aacute;ž&iacute;me si každ&eacute; reakce a odpov&iacute;d&aacute;me v&scaron;em.</p>','<p>Potk&aacute;vat se s klienty z Plzně a okol&iacute;, pom&aacute;hat jim chytře nakl&aacute;dat s penězi a plnit jejich sny.</p>\r\n<p>Pl&aacute;novat si pracovn&iacute; dobu podle sebe tak, abyste měl/a dostatek času na sebe, rodinu a kon&iacute;čky.</p>\r\n<p>Př&iacute;jem, jehož v&yacute;&scaron;i ovlivňujete jen vy, protože my ž&aacute;dn&eacute; stropy nem&aacute;me.</p>\r\n<p>Zn&iacute; v&aacute;m to dobře? Přidejte se k n&aacute;m a staňte se souč&aacute;st&iacute; skupiny Raiffeisen!</p>\r\n<p>Hned na startu od n&aacute;s dostanete vlastn&iacute; kmen aktivn&iacute;ch klientů, o kter&eacute; budete pečovat. Oslovujeme pouze st&aacute;vaj&iacute;c&iacute; klienty RSTS.Zač&aacute;tky u n&aacute;s budou dosti studijn&iacute;. V&scaron;e potřebn&eacute; v&aacute;m vysvětl&iacute;me a porad&iacute;me, jak na to. &Scaron;kolen&iacute; a zkou&scaron;ky za v&aacute;s zaplat&iacute;me, od v&aacute;s potřebujeme hlavně chuť se (na)učit. Z&iacute;skan&eacute; znalosti nav&iacute;c využijete nejen v pracovn&iacute;m, ale i v běžn&eacute;m životě.</p>\r\n<p>Ž&aacute;dn&yacute; učen&yacute; z nebe nespadl. K ruce proto budete vždy m&iacute;t zku&scaron;en&eacute; kolegy.</p>\r\n<p>V&iacute;me, že zač&aacute;tky nejsou jednoduch&eacute; ani finančně. Podpoř&iacute;me v&aacute;s proto př&iacute;spěvkem 88 000 Kč za prvn&iacute;ch 6 měs&iacute;ců. Svůj v&yacute;dělek ovlivňujete jen vy. U n&aacute;s ž&aacute;dn&eacute; provizn&iacute; stropy nejsou.</p>'),
(330,42,1,5,'Vedoucí kanceláře','Plzeň, Tachov, Domažlice, Beroun','<p>Potk&aacute;vat se s klienty z Plzně a okol&iacute;, pom&aacute;hat jim chytře nakl&aacute;dat s penězi a plnit jejich sny.</p>\r\n<p>Pl&aacute;novat si pracovn&iacute; dobu podle sebe tak, abyste měl/a dostatek času na sebe, rodinu a kon&iacute;čky.</p>\r\n<p>Př&iacute;jem, jehož v&yacute;&scaron;i ovlivňujete jen vy, protože my ž&aacute;dn&eacute; stropy nem&aacute;me. Zn&iacute; v&aacute;m to dobře?</p>\r\n<p>Přidejte se k n&aacute;m a staňte se souč&aacute;st&iacute; skupiny Raiffeisen!</p>\r\n<p>Na&scaron;e pr&aacute;ce je předev&scaron;&iacute;m o budov&aacute;n&iacute; dlouhodob&yacute;ch vztahů s klienty. Budete se snažit, abyste byl/a prvn&iacute;, na koho si klient vzpomene, kdykoliv bude potřebovat ře&scaron;it cokoliv t&yacute;kaj&iacute;c&iacute; se jeho financ&iacute;.</p>\r\n<p><br>Naslouch&aacute;me potřeb&aacute;m klientů, kter&yacute;m hled&aacute;me a nach&aacute;z&iacute;me ře&scaron;en&iacute; na m&iacute;ru.<br>RSTS už d&aacute;vno nen&iacute; jen o stavebn&iacute;m spořen&iacute;. Pracujeme s &scaron;irok&yacute;m portfoliem produktů, kter&eacute; klientům d&aacute;vaj&iacute; smysl a usnadňuj&iacute; jim život v každ&eacute; etapě.</p>','<p>Hned na startu od n&aacute;s dostanete vlastn&iacute; kmen aktivn&iacute;ch klientů, o kter&eacute; budete pečovat. Oslovujeme pouze st&aacute;vaj&iacute;c&iacute; klienty RSTS. Zač&aacute;tky u n&aacute;s budou dosti studijn&iacute;. V&scaron;e potřebn&eacute; v&aacute;m vysvětl&iacute;me a porad&iacute;me, jak na to. &Scaron;kolen&iacute; a zkou&scaron;ky za v&aacute;s zaplat&iacute;me, od v&aacute;s potřebujeme hlavně chuť se (na)učit. Z&iacute;skan&eacute; znalosti nav&iacute;c využijete nejen v pracovn&iacute;m, ale i v běžn&eacute;m životě.</p>\r\n<p>Ž&aacute;dn&yacute; učen&yacute; z nebe nespadl. K ruce proto budete vždy m&iacute;t zku&scaron;en&eacute; kolegy.</p>\r\n<p>V&iacute;me, že zač&aacute;tky nejsou jednoduch&eacute; ani finančně. Podpoř&iacute;me v&aacute;s proto př&iacute;spěvkem 88 000 Kč za prvn&iacute;ch 6 měs&iacute;ců. Svůj v&yacute;dělek ovlivňujete jen vy. U n&aacute;s ž&aacute;dn&eacute; provizn&iacute; stropy nejsou.</p>\r\n<p>&nbsp;</p>','<p>Flexibiln&iacute; pracovn&iacute; doba u n&aacute;s nen&iacute; jen fr&aacute;ze. Jedn&aacute; se o spolupr&aacute;ci na IČ. Jak si zorganizujete svůj čas je jen na v&aacute;s.</p>\r\n<p>Spolupr&aacute;ce se silnou skupinou Raiffeisen sk&yacute;t&aacute; spoustu v&yacute;hod. Slevy na firemn&iacute; služby, zv&yacute;hodněn&yacute; mobiln&iacute; tarif, př&iacute;spěvek na benzin, kancel&aacute;ř atd. patř&iacute; ke klasik&aacute;m. Co ale ř&iacute;k&aacute;te třeba na dovolenou pro na&scaron;e nejlep&scaron;&iacute; obchodn&iacute;ky?</p>\r\n<p>Chcete si časem otevř&iacute;t vlastn&iacute; kancel&aacute;ř, zaučovat nov&eacute; kolegy nebo v&eacute;st t&yacute;m obchodn&iacute;ků? V kari&eacute;rn&iacute;m růstu v&aacute;s moc r&aacute;di podpoř&iacute;me.</p>\r\n<p>Pokud už m&aacute;te zku&scaron;enosti z financ&iacute; nebo prodeje/obchodu, r&aacute;di se s v&aacute;mi pobav&iacute;me o podm&iacute;nk&aacute;ch, kter&eacute; můžeme připravit př&iacute;mo v&aacute;m na m&iacute;ru.</p>'),
(333,65,1,1,'Finanční Controller','Dobřanská 537, 332 09 Štěnovice','<p><strong>Finančn&iacute; Controller je kl&iacute;čovou pozic&iacute; ve finančn&iacute;m oddělen&iacute; společnosti, zodpovědnou za dohled nad ve&scaron;ker&yacute;mi finančn&iacute;mi operacemi a zaji&scaron;těn&iacute; přesnosti &uacute;četn&iacute;ch z&aacute;znamů.</strong></p>\r\n<p><strong>Co v&aacute;s ček&aacute;:</strong></p>\r\n<p>V&yacute;počet a &uacute;čtov&aacute;n&iacute; dohadů, rezerv a alokac&iacute;.<br>Př&iacute;prava podkladů pro pravideln&yacute; reporting, ročn&iacute; rozpočet a statut&aacute;rn&iacute; audit.<br>Anal&yacute;zy z&aacute;sob a rekonciliace &uacute;čtů materi&aacute;lov&eacute; bilance.<br>Spolupr&aacute;ce na procesu inventarizace z&aacute;sob.<br>Kontrola a &uacute;prava nastaven&iacute; syst&eacute;mu.<br>Ře&scaron;en&iacute; Ad Hoc požadavků.<br>Komunikace s centr&aacute;lou společnosti v zahranič&iacute;.<br>Podpora veden&iacute; společnosti ve svěřen&eacute; oblasti.</p>\r\n<p>&nbsp;</p>','<p><strong>Jak&eacute; znalosti a dovednosti byste měli m&iacute;t:</strong></p>\r\n<p>Zku&scaron;enosti oboru financ&iacute;.<br>5 let praxe v &uacute;četnictv&iacute; nebo controllingu.<br>Pokročil&aacute; &uacute;roveň anglick&eacute;ho jazyka.<br>Praktick&eacute; zku&scaron;enosti s prac&iacute; s ERP syst&eacute;my, ide&aacute;lně Oracle, dobr&aacute; znalost Excelu.<br>Schopnost pracovat samostatně i v t&yacute;mu.<br>Schopnost dodržovat term&iacute;ny.<br>Spolehlivost, zodpovědnost, pečlivost, loajalita a ochota učit se nov&yacute;m věcem.</p>','<p><strong>Co v&aacute;m můžeme nab&iacute;dnout:</strong></p>\r\n<p>Možnost pod&iacute;let se na nov&yacute;ch a zaj&iacute;mav&yacute;ch projektech.<br>Poznat dobrou partu lid&iacute;, kter&aacute; t&aacute;hne za jeden provaz.<br>25 dnů dovolen&eacute;.<br>Zkr&aacute;cen&aacute; t&yacute;denn&iacute; pracovn&iacute; doba 37,5 hod. /t&yacute;dně.<br>Př&iacute;spěvek na stravov&aacute;n&iacute; ve v&yacute;&scaron;i 120 Kč na den.<br>Př&iacute;spěvek na penzijn&iacute; připoji&scaron;těn&iacute; ve v&yacute;&scaron;i 1 % ze mzdy, min. 300 Kč měs&iacute;čně.<br>Př&iacute;spěvek 1000 Kč měs&iacute;čně na Pluxee kartu.<br>Př&iacute;spěvek za doporučen&iacute; nov&eacute;ho zaměstnance.<br>Jazykovk&eacute; kurzy.<br>Solidn&iacute; mzda + bonus každ&yacute; měs&iacute;c.<br>13. mzda.</p>'),
(334,75,1,2,'Svářeč','Holýšov','<p>SOU/S&Scaron; v oboru sv&aacute;řeč<br>Praxe 2-3 roky jako sv&aacute;řeč na CO2<br>Platn&yacute; sv&aacute;řečsk&yacute; průkaz<br>(EU zkou&scaron;ky CO2 dle EN 9606 &ndash; 1)<br>Průkaz VZV, vazač a jeř&aacute;bn&iacute;k v&yacute;hodou<br>Samostatn&aacute; pr&aacute;ce dle v&yacute;kresov&eacute; dokumentace<br>Dodržov&aacute;n&iacute; technologick&eacute; k&aacute;zně, požadavků TPM</p>','<p><strong>N&aacute;plň pr&aacute;ce:</strong></p>\r\n<p>Svařov&aacute;n&iacute; dle technologick&eacute;ho postupu na CO2<br>Svařov&aacute;n&iacute; dle platn&yacute;ch norem a předpisů v aktu&aacute;ln&iacute;m zněn&iacute;<br>Zodpovědnost za spr&aacute;vn&eacute; použ&iacute;v&aacute;n&iacute; sv&aacute;řečsk&yacute;ch n&aacute;strojů<br>Kontrola svarů<br>Čten&iacute; technick&eacute; dokumentace<br>Pravideln&aacute; &uacute;držba n&aacute;strojů a udržov&aacute;n&iacute; pracovi&scaron;tě v čistotě<br>Dodržov&aacute;n&iacute; bezpečnostn&iacute;ch předpisů</p>\r\n<p>&nbsp;</p>','<p><strong>Nab&iacute;z&iacute;me</strong>:</p>\r\n<p>7,5h pracovn&iacute; doba<br>5 t&yacute;dnů dovolen&eacute;<br>Pravideln&eacute; ročn&iacute; navy&scaron;ov&aacute;n&iacute; mezd<br>Př&iacute;platky za přesčas, směnnost a pr&aacute;ci o v&iacute;kendech či sv&aacute;tc&iacute;ch<br>Z&aacute;vodn&iacute; stravov&aacute;n&iacute; (oběd za 20Kč)<br>Př&iacute;spěvek na dopravu 3Kč/km<br>&Scaron;kolen&iacute;, jazykov&eacute; kurzy a kari&eacute;rn&iacute; růst<br>Př&iacute;spěvek na penzijn&iacute; poji&scaron;těn&iacute; 900Kč/měs&iacute;c<br>Flexi pasy v hodnotě 2 000Kč/rok<br>Ročn&iacute; pod&iacute;ly na zisku<br>Věrnostn&iacute; jubilejn&iacute; odměny<br>Firemn&iacute; akce pro zaměstnance<br>Finančn&iacute; př&iacute;spěvek</p>'),
(335,75,1,3,'Technik dílny přípravků','Holýšov','<p>- Zji&scaron;ťov&aacute;n&iacute; z&aacute;vad př&iacute;pravků a jejich odstraněn&iacute;<br>- Z&aacute;mečnick&eacute; a n&aacute;strojařsk&eacute; pr&aacute;ce při &uacute;držbě, oprav&aacute;ch, v&yacute;robě, a měřen&iacute; př&iacute;pravků<br>- Svařov&aacute;n&iacute;, brou&scaron;en&iacute; a rovn&aacute;n&iacute; v&yacute;robků a d&iacute;lů z různ&yacute;ch materi&aacute;lů<br>- Obsluha obr&aacute;běc&iacute;ch strojů<br>- Měřen&iacute; pomoc&iacute; 3D měř&iacute;c&iacute;ch př&iacute;strojů, tvorba měř&iacute;c&iacute;ch protokolů v poč&iacute;tači<br>- Manipulace s materi&aacute;lem a s př&iacute;pravky pomoc&iacute; jeř&aacute;bu a VZV<br>- Pr&aacute;ce ve v&yacute;&scaron;k&aacute;ch, na žebř&iacute;ku nebo na plo&scaron;ině<br>- Dodržov&aacute;n&iacute; bezpečnostn&iacute;ch předpisů<br>- Pr&aacute;ce v dvousměnn&eacute;m provozu</p>','<p>&nbsp;</p>\r\n<p>- Vyučen v oboru n&aacute;strojař / oprav&aacute;ř strojů / strojn&iacute; z&aacute;mečn&iacute;k<br>- 2-3 roky praxe v oblasti oprav strojn&iacute;ch zař&iacute;zen&iacute;<br>- Znalost čten&iacute; ve v&yacute;kresov&eacute; dokumentaci<br>- Sv&aacute;řečsk&yacute; průkaz a průkaz VZV v&yacute;hodou<br>- Znalost pr&aacute;ce s měř&iacute;c&iacute;mi CAD př&iacute;stroji a PC v&yacute;hodou<br>- Samostatn&aacute; pr&aacute;ce, zodpovědnost, t&yacute;mov&aacute; spolupr&aacute;ce<br>- Řidičsk&yacute; průkaz skupiny B v&yacute;hodou</p>','<p>7,5h pracovn&iacute; doba<br>5 t&yacute;dnů dovolen&eacute;<br>Pravideln&eacute; ročn&iacute; navy&scaron;ov&aacute;n&iacute; mezd<br>Př&iacute;platky za přesčas, směnnost a pr&aacute;ci o v&iacute;kendech či sv&aacute;tc&iacute;ch<br>Z&aacute;vodn&iacute; stravov&aacute;n&iacute; (oběd za 20Kč)<br>Př&iacute;spěvek na dopravu 3Kč/km<br>&Scaron;kolen&iacute;, jazykov&eacute; kurzy a kari&eacute;rn&iacute; růst<br>Př&iacute;spěvek na penzijn&iacute; poji&scaron;těn&iacute; 900Kč/měs&iacute;c<br>Flexi pasy v hodnotě 2 000Kč/rok<br>Ročn&iacute; pod&iacute;ly na zisku a za splněn&iacute; c&iacute;lů<br>Věrnostn&iacute; jubilejn&iacute; odměny<br>Firemn&iacute; akce pro zaměstnance<br>Finančn&iacute; př&iacute;spěvek při odchodu do důchodu<br>Možnost ubytov&aacute;n&iacute; na ubytovn&aacute;ch</p>'),
(336,75,1,5,'Energetický manažer','Holýšov','<p>&Uacute;čast na konferenc&iacute;ch a jedn&aacute;n&iacute;ch Gr&uuml;ne Energie, Gr&uuml;ne Produktion, Emissionsfreie Produktion, CO2 Ersparungsprogram und Ziele, zodpovědnost za plněn&iacute; stanoven&yacute;ch &uacute;kolů a c&iacute;lů<br>Projektov&yacute; management v oblasti<br>Management PO v oblasti EPS a Centr&aacute;ln&iacute;ho pultu ochrany PO<br>Zaji&scaron;těn&iacute; kontinu&aacute;ln&iacute;ch dod&aacute;vek v&scaron;ech energi&iacute; pro v&yacute;robn&iacute; z&aacute;vod (elektřina, zemn&iacute; plyn, voda, technick&eacute; plyny, LTO) včetně objedn&aacute;vek, kontroly dod&aacute;vek, spolupr&aacute;ce s odd. n&aacute;kupu při v&yacute;běru nov&yacute;ch dodavatelů<br>Pravideln&eacute; revize a kontroly v&scaron;ech zař&iacute;zen&iacute; Energocenter<br>Ř&iacute;zen&iacute; a kontrola v syst&eacute;mu Energis<br>Ř&iacute;zen&iacute; a spolupr&aacute;ce na projektech t&yacute;kaj&iacute;c&iacute;ch se energetick&eacute; oblasti při roz&scaron;iřov&aacute;n&iacute; z&aacute;vodu<br>Veden&iacute; přesn&yacute;ch přehledů spotřeb, evidence reviz&iacute; a pravideln&eacute; &uacute;držby, spolupr&aacute;ce na v&yacute;běrov&yacute;ch ř&iacute;zen&iacute;ch nov&yacute;ch dodavatelů s centr&aacute;ln&iacute;m n&aacute;kupem.<br>Zaji&scaron;ťov&aacute;n&iacute; okamžit&yacute;ch oprav a odstraňov&aacute;n&iacute; poruch a hav&aacute;ri&iacute;</p>','<p>S&Scaron;/V&Scaron; vzděl&aacute;n&iacute; technick&eacute;ho směru, nejl&eacute;pe elektro<br>Komunikativn&iacute; znalost anglick&eacute;ho jazyka nebo německ&eacute;ho jazyka - v&yacute;hodou<br>Zku&scaron;enosti s veden&iacute;m projektů v&yacute;hodou<br>Uživatelsk&aacute; znalost MS Office (Outlook, Teams..)<br>Praxe v oboru v&yacute;hodou<br>Zav&aacute;děn&iacute; ISO norem<br>Řidičsk&yacute; průkaz sk. B<br>Komunikativn&iacute; a organizačn&iacute; schopnosti</p>','<p>7,5h pracovn&iacute; doba<br>Flexibiln&iacute; časov&eacute; konto<br>5 t&yacute;dnů dovolen&eacute;<br>Pravideln&eacute; ročn&iacute; navy&scaron;ov&aacute;n&iacute; mezd<br>Z&aacute;vodn&iacute; stravov&aacute;n&iacute; (oběd za 20Kč)<br>Př&iacute;spěvek na dopravu 3Kč/km<br>Služebn&iacute; telefon i k soukrom&yacute;m &uacute;čelům<br>&Scaron;kolen&iacute;, jazykov&eacute; kurzy a kari&eacute;rn&iacute; růst<br>Př&iacute;spěvek na penzijn&iacute; poji&scaron;těn&iacute; 900Kč/měs&iacute;c<br>Flexi pasy v hodnotě 2 000Kč/rok<br>Ročn&iacute; pod&iacute;ly na zisku a za splněn&iacute; c&iacute;lů<br>Věrnostn&iacute; jubilejn&iacute; odměny<br>Firemn&iacute; akce pro zaměstnance<br>Finančn&iacute; př&iacute;spěvek při odchodu do důchodu</p>'),
(337,75,1,5,'Specialista v oblasti BOZP, PO nebo ochrana ŽP','Holýšov','<p>Plněn&iacute; povinnost&iacute; podle legislativn&iacute;ch předpisů v oblasti BOZP,PO, ŽP<br>Pod&iacute;len&iacute; se na pl&aacute;nov&aacute;n&iacute; a vyjadřov&aacute;n&iacute; se k n&aacute;vrhům pl&aacute;nov&aacute;n&iacute; nov&yacute;ch pracovi&scaron;ť a nov&yacute;ch pracovn&iacute;ch syst&eacute;mů před jejich uveden&iacute;m do provozu.<br>Prov&aacute;děn&iacute;/dokumentov&aacute;n&iacute; bezpečnostn&iacute;ch auditů<br>Vytv&aacute;řen&iacute; anal&yacute;z rizik a konceptů prevence<br>Kontaktn&iacute; osoba pro relevantn&iacute; t&eacute;mata BOZP a PO v Daimler Truck<br>Zodpovědnost za programy Daimler Truck v oblasti BOZP, PO<br>Veden&iacute; projektů<br>Zaji&scaron;těn&iacute; uv&aacute;děn&iacute; zpracovan&yacute;ch opatřen&iacute; a projektů do provozu včetně pl&aacute;nov&aacute;n&iacute; investic<br>Spolupr&aacute;ce s členy t&yacute;mu a ostatn&iacute;mi oddělen&iacute;mi</p>','<p>Minim&aacute;ln&iacute; S&Scaron;<br>Znalost anglick&eacute;ho nebo německ&eacute;ho jazyka<br>3 roky praxe na stejn&eacute; či podobn&eacute; pozici<br>ISO 45001, ISO 14001, ISO 9001<br>Uživatelsk&aacute; znalost MS Office<br>Procesn&iacute; orientace, koncepčn&iacute; my&scaron;len&iacute;, zodpovědnost, samostatnost, flexibilita<br>Řidičsk&yacute; průkaz sk. B</p>','<p>7,5h pracovn&iacute; doba<br>Flexibiln&iacute; časov&eacute; konto<br>5 t&yacute;dnů dovolen&eacute;<br>Pravideln&eacute; ročn&iacute; navy&scaron;ov&aacute;n&iacute; mezd<br>Z&aacute;vodn&iacute; stravov&aacute;n&iacute; (oběd za 20Kč)<br>Př&iacute;spěvek na dopravu 3Kč/km<br>Služebn&iacute; telefon i k soukrom&yacute;m &uacute;čelům<br>&Scaron;kolen&iacute;, jazykov&eacute; kurzy a kari&eacute;rn&iacute; růst<br>Př&iacute;spěvek na penzijn&iacute; poji&scaron;těn&iacute; 900Kč/měs&iacute;c<br>Flexi pasy v hodnotě 2 000Kč/rok<br>Ročn&iacute; pod&iacute;ly na zisku a za splněn&iacute; c&iacute;lů<br>Věrnostn&iacute; jubilejn&iacute; odměny<br>Firemn&iacute; akce pro zaměstnance<br>Finančn&iacute; př&iacute;spěvek při odchodu do důchodu</p>'),
(338,71,1,5,'PERSONALISTA/KA - zástup za mateřskou dovolenou','Bor u Tachova','<ul>\r\n<li>Zpracov&aacute;n&iacute; doch&aacute;zky</li>\r\n<li>Př&iacute;prava pracovně-pr&aacute;vn&iacute;ch dokumentů &ndash; od pracovn&iacute;ch smluv po různ&eacute; dodatky a dohody</li>\r\n<li>Podklady ke zpracov&aacute;n&iacute; mezd &ndash; budete &uacute;zce spolupracovat s mzdovou &uacute;čt&aacute;rnou</li>\r\n<li>Spolupr&aacute;ce s pracovn&iacute;mi agenturami &ndash; včetně spr&aacute;vy př&iacute;slu&scaron;n&eacute; dokumentace</li>\r\n<li>Spr&aacute;va a v&yacute;dej pracovn&iacute;ch oděvů &ndash; star&aacute;te se, aby zaměstnanci měli v&scaron;e potřebn&eacute;</li>\r\n<li>Administrace person&aacute;ln&iacute;ch složek &ndash; od spr&aacute;vy osobn&iacute;ch &uacute;dajů až po archivaci důležit&yacute;ch dokumentů</li>\r\n</ul>','<ul>\r\n<li>Zku&scaron;enost na obdobn&eacute; pozici &ndash; v HR nebo administrativě</li>\r\n<li>Z&aacute;kladn&iacute; orientace v z&aacute;kon&iacute;ku pr&aacute;ce&nbsp;</li>\r\n<li>Znalost ukrajinsk&eacute;ho jazyka &ndash; v&yacute;hodou (ne v&scaron;ak podm&iacute;nkou)</li>\r\n<li>Uživatelsk&aacute; znalost MS Office &ndash; zejm&eacute;na Word, Excel a PowerPoint</li>\r\n<li>Organizačn&iacute; schopnosti &ndash; budete zvl&aacute;dat v&iacute;ce &uacute;kolů najednou</li>\r\n<li>Pečlivost, zodpovědnost a diskr&eacute;tnost &ndash; kvality, kter&eacute; jsou v HR kl&iacute;čov&eacute;</li>\r\n<li>Chuť učit se nov&yacute;m věcem a rozv&iacute;jet se v oblasti personalistiky</li>\r\n</ul>','<ul>\r\n<li>Př&aacute;telsk&yacute; kolektiv a neform&aacute;ln&iacute; pracovn&iacute; prostřed&iacute;</li>\r\n<li>Pracovn&iacute; smlouvu na dobu určitou (z&aacute;stup za mateřskou dovolenou)</li>\r\n<li>Možnost dal&scaron;&iacute; spolupr&aacute;ce</li>\r\n<li>Ročn&iacute; bonus až do v&yacute;&scaron;e 100 % měs&iacute;čn&iacute; mzdy jako odměnu za va&scaron;i pr&aacute;ci</li>\r\n<li>Vzděl&aacute;v&aacute;n&iacute; a &scaron;kolen&iacute; &ndash; včetně jazykov&yacute;ch kurzů př&iacute;mo v pracovn&iacute; době</li>\r\n<li>5 t&yacute;dnů dovolen&eacute; pro dostatečn&yacute; odpočinek</li>\r\n<li>Flexibiln&iacute; pracovn&iacute; dobu a př&iacute;ležitost k pr&aacute;ci z domova</li>\r\n<li>Př&iacute;spěvek na stravov&aacute;n&iacute;, zv&yacute;hodněn&eacute; bankovn&iacute; produkty a mobiln&iacute; tarify</li>\r\n<li>Stabiln&iacute; pracovn&iacute; z&aacute;zem&iacute; s možnost&iacute; dlouhodob&eacute; spolupr&aacute;ce</li>\r\n</ul>'),
(339,88,1,4,'CNC operátor','Plzeň - Borská pole','<p>Oper&aacute;tor CNC stroje obsluhuje poč&iacute;tačem ř&iacute;zen&eacute; obr&aacute;běc&iacute; stroje (fr&eacute;zky, soustruhy, brusky), kter&eacute; zpracov&aacute;vaj&iacute; materi&aacute;l dle programů, prov&aacute;d&iacute; jednoduch&eacute; seř&iacute;zen&iacute;, v&yacute;měnu n&aacute;strojů, kontroluje kvalitu hotov&yacute;ch d&iacute;lů podle technick&yacute;ch v&yacute;kresů, zaji&scaron;ťuje &uacute;držbu a čistotu stroje a zav&aacute;ž&iacute; materi&aacute;l.</p>','<p>SOU/S&Scaron; stroj&iacute;rensk&eacute;ho zaměřen&iacute; (nejl&eacute;pe obr&aacute;běč kovů, n&aacute;strojař), schopnost č&iacute;st technick&eacute; v&yacute;kresy, znalost obr&aacute;běc&iacute;ch n&aacute;strojů a CNC technologi&iacute;, manu&aacute;ln&iacute; zručnost, pečlivost, zodpovědnost a samostatnost, přičemž praxe a znalost specifick&yacute;ch programů (např&iacute;klad EdgeCam, Heidenhain).</p>','<p>Stabiln&iacute; zaměstn&aacute;n&iacute;, odpov&iacute;daj&iacute;c&iacute; finančn&iacute; ohodnocen&iacute;, možnost dal&scaron;&iacute;ho profesn&iacute;ho vzděl&aacute;v&aacute;n&iacute; a kari&eacute;rn&iacute;ho růstu, sick-days, 5 t&yacute;dnů dovolen&eacute;, stravenky a bonusov&eacute; pouk&aacute;zky pro zaměstnance. Pro mimoplzeňsk&eacute; možnost dopravy do zaměstn&aacute;n&iacute;. Zaměatnancům nab&iacute;z&iacute;me tak&eacute; ubytov&aacute;n&iacute;.</p>'),
(340,88,1,4,'montážní dělník/ce','Bor u Tachova','<p>Mont&aacute;žn&iacute; děln&iacute;k prov&aacute;d&iacute; manu&aacute;ln&iacute; mont&aacute;ž a kompletaci v&yacute;robků, d&iacute;lů nebo podsestav podle technick&eacute; dokumentace, často na v&yacute;robn&iacute;ch link&aacute;ch, s použit&iacute;m ručn&iacute;ho n&aacute;řad&iacute; a jednoduch&yacute;ch strojů, a zaji&scaron;ťuje vizu&aacute;ln&iacute; kontrolu fin&aacute;ln&iacute;ho produktu a &uacute;držbu poř&aacute;dku na pracovi&scaron;ti.</p>','<p>Manu&aacute;ln&iacute; zručnost, pečlivost, zodpovědnost a fyzickou zdatnost; nejl&eacute;pe vyučen&yacute; v technick&eacute;m oboru (stroj&iacute;renstv&iacute;, elektrotechnika) ale nen&iacute; podm&iacute;nkou, z&aacute;kladn&iacute; orientace v technick&eacute; dokumentaci (v&yacute;kresy), ochota pracovat ve směnn&eacute;m provozu a dodržovat BOZP; zku&scaron;enosti, sv&aacute;řečsk&yacute; průkaz nebo řidičsk&yacute; průkaz (ŘP B, př&iacute;padně VZV) jsou velkou v&yacute;hodou.</p>','<p>Stabiln&iacute; pr&aacute;ci, rozvoj profesn&iacute; a př&iacute;padně i kari&eacute;rn&iacute; postup, 5 t&yacute;dnů dovolen&eacute;, firemn&iacute; stravov&aacute;n&iacute;, sick-days, bonusy jako permanentky do fitcentra anebo kina a dal&scaron;&iacute; zaměstnaneck&eacute; bonusy.</p>'),
(341,89,1,5,'Copywriter/ka','Praha','<p>Copywriter p&iacute;&scaron;e reklamn&iacute; texty a vytv&aacute;ř&iacute; reklamn&iacute; slogany. Může tak&eacute; vym&yacute;&scaron;let grafick&eacute; n&aacute;vrhy pro zpracov&aacute;n&iacute; grafiky a různ&eacute; inovativn&iacute; n&aacute;pady a kreativn&iacute; postupy pro tvorbu reklamy.</p>','<p>S&Scaron;, v&yacute;born&aacute; znalost če&scaron;tiny, kreativita, ochota učit se nov&eacute; věci, znalost pr&aacute;ce s kancel&aacute;řsk&yacute;m bal&iacute;kem MS Word, Word 365 a v&scaron;eobecn&aacute; znalost pr&aacute;ce na poč&iacute;tači (včetně internetu). Spolehlivost, seri&oacute;znost a samostatnost velkou v&yacute;hodou.</p>','<p>Zaj&iacute;mav&eacute; finančn&iacute; ohodnocen&iacute;, 5 t&yacute;dnů dovolen&eacute;, stravenky, sick-days, společn&eacute; firemn&iacute; akce.</p>'),
(342,89,1,6,'Sekretář/ka','Praha - Staré Město','<p>Sekret&aacute;řka zaji&scaron;ťuje provoz sekretari&aacute;tu, pom&aacute;h&aacute; řediteli/ce firmy dle jeho/jej&iacute;ch pokynů, pracuje v r&aacute;mci administrativy, chodu sekretari&aacute;tu, komunikace s klienty i s ostatn&iacute;mi zaměstnanci.</p>','<p>V&yacute;born&aacute; znalost ČJ, pokročil&aacute; znalost pr&aacute;ce na poč&iacute;tači včetně pr&aacute;ce s internetem, znalost podvojn&eacute;ho &uacute;četnictv&iacute; v&yacute;hodou nikoli podm&iacute;nkou, ŘP B.</p>','<p>Spolehliv&eacute; firemn&iacute; z&aacute;zem&iacute;, dobr&eacute; finančn&iacute; ohodnocen&iacute;, firmn&iacute; stravov&aacute;n&iacute;, 5 t&yacute;dnů dovolen&eacute;, firemn&iacute; akce zdarma a dal&scaron;&iacute; zaměstnaneck&eacute; v&yacute;hody.</p>'),
(343,72,1,1,'Specialista na pronájmy nemovitostí v Plzni','Plzeň','<p>Chcete se st&aacute;t souč&aacute;st&iacute; prestižn&iacute; mezin&aacute;rodn&iacute; realitn&iacute; s&iacute;tě, kter&aacute; ud&aacute;v&aacute; trendy v pr&eacute;miov&eacute;m segmentu?</p>\r\n<p>Engel &amp; V&ouml;lkers Plzeň roz&scaron;iřuje svůj t&yacute;m a hled&aacute; motivovan&eacute;ho kolegu/kolegyni se siln&yacute;m obchodn&iacute;m duchem, kter&yacute; pos&iacute;l&iacute; na&scaron;i divizi pron&aacute;jmů.</p>\r\n<p><strong>Co v&aacute;s u n&aacute;s ček&aacute;:</strong></p>\r\n<ul>\r\n<li>Aktivn&iacute; vyhled&aacute;v&aacute;n&iacute; obchodn&iacute;ch př&iacute;ležitost&iacute; &ndash; cold calling, networking, osobn&iacute; schůzky</li>\r\n<li>Pr&aacute;ce s různ&yacute;mi typy klientů &ndash; od soukrom&yacute;ch osob až po investory a firmy</li>\r\n<li>Veden&iacute; kompletn&iacute;ho obchodn&iacute;ho procesu &ndash; od prvn&iacute;ho kontaktu až po uzavřen&iacute; obchodu</li>\r\n<li>Rozvoj vlastn&iacute;ho regionu &ndash; Plzeň a Plzeň je va&scaron;&iacute;m &uacute;zem&iacute;m</li>\r\n<li>Budov&aacute;n&iacute; dlouhodob&yacute;ch vztahů &ndash; spokojen&iacute; klienti jsou z&aacute;kladem &uacute;spě&scaron;n&eacute;ho obchodu</li>\r\n<li>Spolupr&aacute;ce v r&aacute;mci s&iacute;tě Engel &amp; V&ouml;lkers &ndash; sd&iacute;len&iacute; zku&scaron;enost&iacute;, kontaktů a př&iacute;ležitost&iacute;</li>\r\n</ul>\r\n<p>&nbsp;</p>','<ul>\r\n<li>Obchodn&iacute;ho ducha &ndash; aktivn&iacute; akvizice je pro v&aacute;s přirozenou souč&aacute;st&iacute; pr&aacute;ce</li>\r\n<li>Vynikaj&iacute;c&iacute; komunikačn&iacute; schopnosti &ndash; budete jednat s různ&yacute;mi typy lid&iacute;</li>\r\n<li>Tah na branku a orientaci na v&yacute;sledek &ndash; um&iacute;te si stanovit c&iacute;le a jdete za nimi</li>\r\n<li>Samostatnost a zodpovědnost &ndash; budete ř&iacute;dit sv&eacute; obchody</li>\r\n<li>Vytrvalost &ndash; &uacute;spěch v obchodu přich&aacute;z&iacute; s konzistentn&iacute;m &uacute;sil&iacute;m</li>\r\n<li>Chuť se učit a rozv&iacute;jet &ndash; realitn&iacute; trh m&aacute; sv&aacute; specifika, ale my v&aacute;s nauč&iacute;me v&scaron;e potřebn&eacute;</li>\r\n</ul>\r\n<p>Zku&scaron;enost z obchodu je v&yacute;hodou &ndash; ale pokud m&aacute;te drive a ochotu makat, zbytek v&aacute;s nauč&iacute;me.</p>','<p><strong>Ohodnocen&iacute;:</strong></p>\r\n<ul>\r\n<li>Fixn&iacute; odměna 35 000 Kč/měs. + neomezen&eacute; provize &ndash; va&scaron;e v&yacute;sledky = v&aacute;&scaron; př&iacute;jem</li>\r\n</ul>\r\n<p><strong>Z&aacute;zem&iacute;:</strong></p>\r\n<ul>\r\n<li>Značka Engel &amp; V&ouml;lkers s v&iacute;ce než 40 lety tradice</li>\r\n<li>Marketingov&aacute;, pr&aacute;vn&iacute; a administrativn&iacute; podpora</li>\r\n<li>Modern&iacute; n&aacute;stroje &ndash; CRM, datab&aacute;ze klientů, profesion&aacute;ln&iacute; prezentace</li>\r\n<li>Re&aacute;ln&eacute; obchodn&iacute; př&iacute;ležitosti v Plzni a Plzeňsk&eacute;m kraji</li>\r\n</ul>\r\n<p><br><strong>Rozvoj:</strong></p>\r\n<ul>\r\n<li>Komplexn&iacute; za&scaron;kolen&iacute; a průběžn&eacute; vzděl&aacute;v&aacute;n&iacute;</li>\r\n<li>Sd&iacute;len&iacute; know-how v r&aacute;mci siln&eacute; mezin&aacute;rodn&iacute; s&iacute;tě</li>\r\n<li>Př&iacute;stup ke zku&scaron;en&yacute;m kolegům a mentorům</li>\r\n<li>Možnost růstu a specializace (rezidenčn&iacute;, komerčn&iacute;, investice)</li>\r\n</ul>'),
(344,128,0,5,'Specialista IT - Hardware','Klatovy','<p>Hled&aacute;me spolehliv&eacute;ho IT specialistu, kter&yacute; zvl&aacute;d&aacute; z&aacute;kladn&iacute; instalace, diagnostiku a pr&aacute;ci s koncov&yacute;mi uživateli. Potřebujeme člověka se znalost&iacute; s&iacute;ťov&yacute;ch z&aacute;kladů, komunikativn&iacute; angličtinou a chut&iacute; učit se nov&yacute;m technologi&iacute;m. Možn&aacute; hled&aacute;me pr&aacute;vě V&aacute;s, po&scaron;lete n&aacute;m svůj životopis!<br>&nbsp;</p>','<ul>\r\n<li>znalost z&aacute;kladn&iacute; instalace, diagnostika a oprava PC / notebooků / tabletů</li>\r\n<li>instalace a konfigurace tisk&aacute;ren</li>\r\n<li>z&aacute;klady spr&aacute;vy mobiln&iacute;ch zař&iacute;zen&iacute; (Android, iOS)</li>\r\n<li>instalace a nastaven&iacute; běžn&yacute;ch aplikac&iacute;, instalace a</li>\r\n<li>konfigurace Windows OS</li>\r\n<li>znalost s&iacute;ťov&yacute;ch z&aacute;kladů (TCP/IP, DHCP, DNS, VPN)</li>\r\n<li>komunikativnost a schopnost pracovat s koncov&yacute;mi uživateli</li>\r\n<li>t&yacute;mov&aacute; spolupr&aacute;ce, stresov&aacute; odolnos</li>\r\n<li>ochota učit se nov&yacute;m technologi&iacute;m</li>\r\n<li>angličtina na komunikativn&iacute; &uacute;rovni</li>\r\n</ul>','<ul>\r\n<li>flexibiln&iacute; pracovn&iacute; dobu</li>\r\n<li>za&scaron;kolen&iacute; pro danou pozici</li>\r\n<li>5 t&yacute;dnů dovolen&eacute;</li>\r\n<li>13. mzda při plněn&iacute; celofiremn&iacute;ch krit&eacute;ri&iacute; stanoven&yacute;ch na dan&eacute; obdob&iacute;</li>\r\n<li>velmi dobr&eacute; mzdov&eacute; podm&iacute;nky</li>\r\n<li>benefitn&iacute; program Pluxee</li>\r\n<li>možnost spolufinancov&aacute;n&iacute; MultiSport karty</li>\r\n<li>slevy na firemn&iacute; produkty</li>\r\n<li>stravenkov&yacute; pau&scaron;&aacute;l 120 Kč/1 odpracovan&yacute; den</li>\r\n<li>př&iacute;spěvek na dopravu</li>\r\n<li>př&iacute;spěvek na penzijn&iacute; připoji&scaron;těn&iacute; po 1 odpracovan&eacute;m roce</li>\r\n</ul>'),
(345,72,1,1,'Realitní makléř v oddělení rezidenčních prodejů Plzeň','Plzeň','<p>Hled&aacute;te dynamickou obchodn&iacute; pozici, kter&aacute; každ&yacute; den přin&aacute;&scaron;&iacute; nov&eacute; v&yacute;zvy? Kde pom&aacute;h&aacute;te lidem naj&iacute;t jejich domov a b&yacute;t u těch nejdůležitěj&scaron;&iacute;ch okamžiků v jejich životě? Kde je potřeba empatie, rychlost a schopnost nav&aacute;zat vztah s lidmi?</p>\r\n<p><strong>Co v&aacute;s u n&aacute;s ček&aacute;:</strong></p>\r\n<ul>\r\n<li><strong>Aktivn&iacute; vyhled&aacute;v&aacute;n&iacute; nemovitost&iacute; k prodeji </strong>&ndash; byty, rodinn&eacute; domy, vily v Plzni</li>\r\n<li><strong>Pr&aacute;ce s lidmi v důležit&yacute;ch životn&iacute;ch momentech</strong> &ndash; pom&aacute;h&aacute;te jim prodat nebo koupit domov</li>\r\n<li><strong>Veden&iacute; kompletn&iacute;ho obchodn&iacute;ho procesu</strong> &ndash; od prvn&iacute; schůzky s majitelem až po před&aacute;n&iacute; kl&iacute;čů nov&yacute;m majitelům</li>\r\n<li><strong>Prohl&iacute;dky nemovitost&iacute; a osobn&iacute; prezentace</strong> &ndash; budete tr&aacute;vit čas v ter&eacute;nu na prohl&iacute;dk&aacute;ch se z&aacute;jemci, vyjedn&aacute;vat podm&iacute;nky pro oboustrannou spokojenost</li>\r\n<li><strong>Budov&aacute;n&iacute; důvěry a dlouhodob&yacute;ch vztahů</strong> &ndash; spokojen&iacute; klienti v&aacute;s doporučuj&iacute; d&aacute;l</li>\r\n<li><strong>Spolupr&aacute;ce v r&aacute;mci s&iacute;tě Engel &amp; V&ouml;lkers</strong> &ndash; sd&iacute;len&iacute; kontaktů, zku&scaron;enost&iacute; a př&iacute;ležitost&iacute;</li>\r\n</ul>','<ul>\r\n<li><strong>Lidsk&yacute; př&iacute;stup a empatii </strong>&ndash; prodej domu je emocion&aacute;ln&iacute; z&aacute;ležitost</li>\r\n<li><strong>Komunikačn&iacute; talent a reprezentativn&iacute; vystupov&aacute;n&iacute; </strong>&ndash; budete tv&aacute;ř va&scaron;&iacute;ch klientů i značky</li>\r\n<li><strong>Tah na branku a chuť aktivně prod&aacute;vat </strong>&ndash; ček&aacute;n&iacute; na popt&aacute;vky nen&iacute; cesta k &uacute;spěchu</li>\r\n<li><strong>Samostatnost a zodpovědnost</strong> &ndash; budete ř&iacute;dit sv&eacute; obchody od zač&aacute;tku do konce</li>\r\n<li><strong>Flexibilitu </strong>&ndash; prohl&iacute;dky mohou b&yacute;t kdykoliv v průběhu dne<br>Z&aacute;jem o realitn&iacute; trh a chuť se v něm st&aacute;t profesion&aacute;lem</li>\r\n</ul>','<p><strong>Ohodnocen&iacute;:</strong></p>\r\n<ul>\r\n<li>Fixn&iacute; odměna 35 000 Kč/měs. + neomezen&eacute; provize od prvn&iacute;ho měs&iacute;ce &ndash; č&iacute;m v&iacute;ce prod&aacute;te, t&iacute;m v&iacute;ce vyděl&aacute;te</li>\r\n</ul>\r\n<p><strong>Z&aacute;zem&iacute;:</strong></p>\r\n<ul>\r\n<li>Značka Engel &amp; V&ouml;lkers s v&iacute;ce než 40 lety tradice</li>\r\n<li>Marketingov&aacute;, pr&aacute;vn&iacute; a administrativn&iacute; podpora</li>\r\n<li>Modern&iacute; n&aacute;stroje &ndash; CRM, datab&aacute;ze klientů, profesion&aacute;ln&iacute; fotografie a prezentace</li>\r\n<li>Re&aacute;ln&eacute; obchodn&iacute; př&iacute;ležitosti v Plzni a Plzeňsk&eacute;m kraji</li>\r\n</ul>\r\n<p><br><strong>Rozvoj:</strong></p>\r\n<ul>\r\n<li>Komplexn&iacute; za&scaron;kolen&iacute; a průběžn&eacute; vzděl&aacute;v&aacute;n&iacute;</li>\r\n<li>Sd&iacute;len&iacute; know-how v r&aacute;mci siln&eacute; mezin&aacute;rodn&iacute; s&iacute;tě</li>\r\n<li>Př&iacute;stup ke zku&scaron;en&yacute;m kolegům a mentorům</li>\r\n<li>Možnost růstu a kari&eacute;rn&iacute;ho postupu</li>\r\n</ul>'),
(346,128,0,5,'Procesní vedoucí v oddělení vrstev','Klatovy','<p>Procesn&iacute; vedouc&iacute; m&aacute; na starosti t&yacute;m lid&iacute; v oddělen&iacute; povrstven&iacute; br&yacute;lov&yacute;ch čoček. Budete dohl&iacute;žet na to, aby v&yacute;roba prob&iacute;hala podle pl&aacute;nu. Va&scaron;im &uacute;kolem bude pl&aacute;nov&aacute;n&iacute; n&aacute;kladů, dodržov&aacute;n&iacute; zadan&eacute;ho rozpočtu i pod&iacute;l na zlep&scaron;ov&aacute;n&iacute; v&yacute;robn&iacute;ch procesů.</p>','<ul>\r\n<li>S&Scaron; nebo V&Scaron; technick&eacute;ho zaměřen&iacute;</li>\r\n<li>komunikativn&iacute; znalost němčiny nebo angličtiny</li>\r\n<li>zku&scaron;enosti s veden&iacute;m lid&iacute; a projektů</li>\r\n<li>z&aacute;kladn&iacute; znalost n&aacute;strojů kvality</li>\r\n<li>dobr&aacute; poč&iacute;tačov&aacute; znalost</li>\r\n<li>pečlivost, spolehlivost, samostatnost a proaktivn&iacute; př&iacute;stup</li>\r\n<li>organizačn&iacute;, prezentačn&iacute; a komunikačn&iacute; dovednosti</li>\r\n</ul>','<ul>\r\n<li>5 t&yacute;dnů dovolen&eacute;</li>\r\n<li>13. mzda při plněn&iacute; celofiremn&iacute;ch krit&eacute;ri&iacute; stanoven&yacute;ch na každ&eacute; obdob&iacute;</li>\r\n<li>př&iacute;spěvek na dopravu do zaměstn&aacute;n&iacute;</li>\r\n<li>stravenkov&yacute; pau&scaron;&aacute;l 120 Kč/1 odpracovan&yacute; den</li>\r\n<li>zaměstnaneck&eacute; slevy na n&aacute;kup na&scaron;ich produktů</li>\r\n<li>benefitn&iacute; program Pluxee</li>\r\n<li>možnost spolufinancov&aacute;n&iacute; MultiSport karty</li>\r\n<li>př&iacute;spěvek na penzijn&iacute; připoji&scaron;těn&iacute; po 1 odpracovan&eacute;m roce</li>\r\n</ul>'),
(347,44,1,3,'Mistr/ová výrobního provozu','Klatovy - 5. května 112','','<p>&nbsp;vzděl&aacute;n&iacute; &Uacute;SO popř. V&Scaron; technologie zpracov&aacute;n&iacute; potravin (masa)</p>\r\n<p>- zku&scaron;enosti s veden&iacute;m pracovn&iacute;ho kolektivu, koordinace v&yacute;roby</p>\r\n<p>- flexibilita, komunikativnost, zodpovědnost</p>\r\n<p>- znalost pr&aacute;ce s PC</p>\r\n<p>- zdravotn&iacute; stav bez omezen&iacute;</p>\r\n<p>- tř&iacute;směnn&yacute; provoz</p>','<p>13. plat, Bonusy/pr&eacute;mie</p>\r\n<p>Dovolen&aacute; 5 t&yacute;dnů</p>\r\n<p>Pracovn&iacute; oblečen&iacute;</p>\r\n<p>Př&iacute;spěvek na dopravu</p>\r\n<p>Př&iacute;spěvek na dovolenou</p>\r\n<p>Př&iacute;spěvek na penzijn&iacute;/životn&iacute; připoji&scaron;těn&iacute;</p>\r\n<p>&nbsp;Př&iacute;spěvek na sport/kulturu/voln&yacute; čas</p>\r\n<p>Z&aacute;vodn&iacute; stravov&aacute;n&iacute;</p>'),
(348,44,1,1,'Expedient hotových výrobků (mrazírna)','Klatovy - 5. května 112','<p>Typ &uacute;vazku - Pr&aacute;ce na pln&yacute; &uacute;vazek<br>Typ smluvn&iacute;ho vztahu - pracovn&iacute; smlouva<br>D&eacute;lka pracovn&iacute;ho poměru - Na dobu neurčitou</p>','<p>&nbsp;vzděl&aacute;n&iacute; od z&aacute;kladn&iacute;ho v&yacute;&scaron;e, možnost za&scaron;kolen&iacute;</p>\r\n<p>- znalost pr&aacute;ce na PC</p>\r\n<p>- dobr&yacute; zdravotn&iacute; stav bez omezen&iacute; (pr&aacute;ce v chladu, nočn&iacute; pr&aacute;ce)</p>\r\n<p>- samostatnost, zodpovědnost, flexibilita</p>\r\n<p>- tř&iacute;směnn&yacute; provoz</p>','<p>13. plat, Bonusy/pr&eacute;mie</p>\r\n<p>Dovolen&aacute; 5 t&yacute;dnů</p>\r\n<p>Pracovn&iacute; oblečen&iacute;</p>\r\n<p>Př&iacute;spěvek na dopravu</p>\r\n<p>Př&iacute;spěvek na dovolenou</p>\r\n<p>Př&iacute;spěvek na penzijn&iacute;/životn&iacute; připoji&scaron;těn&iacute;</p>\r\n<p>&nbsp;Př&iacute;spěvek na sport/kulturu/voln&yacute; čas</p>\r\n<p>Z&aacute;vodn&iacute; stravov&aacute;n&iacute;</p>'),
(349,44,1,1,'Dělník strojního odchytu kuřat - PEER sytém','Klatovy - 5. května 112','','<p>- ř&iacute;zen&iacute; vozidel sk. B</p>\r\n<p>- nočn&iacute; pr&aacute;ce</p>\r\n<p>- zdravotn&iacute; stav bez omezen&iacute; (spirometrie)</p>\r\n<p>- spolehlivost, flexibilita</p>','<p>13. plat, Bonusy/pr&eacute;mie</p>\r\n<p>Dovolen&aacute; 5 t&yacute;dnů</p>\r\n<p>Pracovn&iacute; oblečen&iacute;</p>\r\n<p>Př&iacute;spěvek na dopravu</p>\r\n<p>Př&iacute;spěvek na dovolenou</p>\r\n<p>Př&iacute;spěvek na penzijn&iacute;/životn&iacute; připoji&scaron;těn&iacute;</p>\r\n<p>&nbsp;Př&iacute;spěvek na sport/kulturu/voln&yacute; čas</p>\r\n<p>Z&aacute;vodn&iacute; stravov&aacute;n&iacute;</p>'),
(350,44,1,3,'Pracovník autoúdržby','Klatovy - 5. května 112','','<p>&nbsp; vzděl&aacute;n&iacute; SO popř. &Uacute;SO technick&eacute;ho směru<br>&bull; praxe v&iacute;t&aacute;na, absolventy za&scaron;kol&iacute;me<br>&bull; dobr&yacute; zdravotn&iacute; stav<br>&bull; směnn&yacute; provoz<br>&bull; spolehlivost, zodpovědnost, flexibilita<br>&bull; seř&iacute;zen&iacute; a &uacute;držba strojů a zař&iacute;zen&iacute;<br>&bull; zji&scaron;těn&iacute; př&iacute;čin poruch a probl&eacute;mů na strojn&iacute;m zař&iacute;zen&iacute;<br>&bull; veden&iacute; z&aacute;znamů o preventivn&iacute; &uacute;držbě<br>&bull; budete poskytovat podporu při přestavbě v&yacute;robn&iacute;ch linek<br>&bull; spolupr&aacute;ce při optimalizaci procesů ve v&yacute;robě</p>','<p>13. plat, Bonusy/pr&eacute;mie</p>\r\n<p>Dovolen&aacute; 5 t&yacute;dnů</p>\r\n<p>Pracovn&iacute; oblečen&iacute;</p>\r\n<p>Př&iacute;spěvek na dopravu</p>\r\n<p>Př&iacute;spěvek na dovolenou</p>\r\n<p>Př&iacute;spěvek na penzijn&iacute;/životn&iacute; připoji&scaron;těn&iacute;</p>\r\n<p>&nbsp;Př&iacute;spěvek na sport/kulturu/voln&yacute; čas</p>\r\n<p>Z&aacute;vodn&iacute; stravov&aacute;n&iacute;</p>'),
(351,67,0,5,'Technik BOZP a PO  - Poloviční úvazek','Dýšina ','<p>vykon&aacute;v&aacute; činnosti osoby odborně způsobil&eacute; na &uacute;seku bezpečnosti pr&aacute;ce a pož&aacute;rn&iacute; ochrany<br>aktualizuje potřebn&eacute; dokumenty BOZP a PO, minim&aacute;lně v rozsahu stanoven&eacute;m &nbsp;pr&aacute;vn&iacute;mi předpisy (vyhodnocen&iacute; rizik, bezpečnostn&iacute; předpisy, provozn&iacute; ř&aacute;dy, z&aacute;kladn&iacute; směrnice)<br>prov&aacute;d&iacute; kontroln&iacute; činnosti v oblasti BOZP a PO<br>prov&aacute;d&iacute; odborn&aacute; &scaron;kolen&iacute; BOZP a PO<br>&uacute;častn&iacute; se vy&scaron;etřov&aacute;n&iacute; př&iacute;čin pracovn&iacute;ch &uacute;razů (popř. nemoc&iacute; z povol&aacute;n&iacute;)<br>hodnot&iacute; objekty a &nbsp;činnosti v objektech dle pr&aacute;vn&iacute;ch předpisů PO<br>&uacute;častn&iacute; se kontrol prov&aacute;děn&yacute;ch org&aacute;ny st&aacute;tn&iacute; spr&aacute;vy v oblasti BOZP a PO<br>pod&aacute;v&aacute; n&aacute;vrhy na zařazen&iacute; prac&iacute; do kategori&iacute;<br>metodicky ř&iacute;d&iacute; vedouc&iacute; pracovn&iacute;ky v oblasti BOZP a PO<br>je podporou pro v&scaron;echny zaměstnance v oblasti BOZP a PO<br>&uacute;častn&iacute; se intern&iacute;ch a extern&iacute;ch auditů v oblasti BOZP a PO (ISO 45001)</p>','<p>S&Scaron; nebo V&Scaron;<br>osvědčen&iacute; technik OZO BOZP a PO<br>ŘP sk. B</p>','<p>zodpovědnou a perspektivn&iacute; pr&aacute;ci v &uacute;spě&scaron;n&eacute; společnosti na polovičn&iacute; &uacute;vazek<br>finančn&iacute; ohodnocen&iacute; odpov&iacute;daj&iacute;c&iacute; dan&eacute; pozici<br>dal&scaron;&iacute; odměny dle intern&iacute;ch směrnic<br>př&iacute;spěvek na stravov&aacute;n&iacute;<br>př&iacute;spěvek na penzijn&iacute; nebo životn&iacute; připoji&scaron;těn&iacute;<br>možnost př&iacute;spěvku na ubytov&aacute;n&iacute; nebo dopravu<br>n&aacute;stup dle dohody</p>'),
(352,78,1,4,'Servisní technik (m/ž)','Plzeň','<p>Montuj a demontuj průmyslov&eacute; pohony.</p>\r\n<p>Servisuj pohony SEW i jin&eacute; značky &ndash; v d&iacute;lně i př&iacute;mo u z&aacute;kazn&iacute;ků.</p>\r\n<p>Vyj&iacute;žděj na servisn&iacute; z&aacute;sahy a pom&aacute;hej udržovat provozy v chodu.</p>\r\n<p>Připravuj technick&eacute; podklady pro cenov&eacute; nab&iacute;dky.</p>\r\n<p>Pr&aacute;ce pro ty, kteř&iacute; chtěj&iacute; vidět v&yacute;sledky hned a r&aacute;di ře&scaron;&iacute; technick&eacute; v&yacute;zvy.</p>','<ul>\r\n<li>SOU nebo S&Scaron; vzděl&aacute;n&iacute; stroj&iacute;rensk&eacute;</li>\r\n<li>min. 2 roky praxe jako servisn&iacute; technik</li>\r\n<li>orientace v technick&eacute; dokumentaci ( technick&eacute; v&yacute;kresy, specifikace, postupy pr&aacute;ce)</li>\r\n<li>manu&aacute;ln&iacute; zručnost</li>\r\n<li>odolnost senzorick&eacute; z&aacute;těži</li>\r\n<li>důslednost pracovn&iacute;ch činnost&iacute;, spolehlivost, pozitivn&iacute; př&iacute;stup k pr&aacute;ci</li>\r\n<li>řidičsk&yacute; průkaz skupiny B</li>\r\n<li>časov&aacute; flexibilita/ ochota cestovat (ČR, zahranič&iacute;)</li>\r\n</ul>\r\n<p><strong>V&yacute;hodou:</strong></p>\r\n<ul>\r\n<li>pr&aacute;ce v oboru průmyslov&yacute;ch převodovek v&yacute;hodou</li>\r\n<li>znalost technick&eacute; angličtiny v&yacute;hodou</li>\r\n<li>opr&aacute;vněn&iacute; k ř&iacute;zen&iacute; vysokozdvižn&yacute;ch voz&iacute;ků v&yacute;hodou</li>\r\n<li>jeř&aacute;bnick&yacute; a vazačsk&yacute; průkaz v&yacute;hodou</li>\r\n<li>sv&aacute;řečsk&yacute; průkaz + řez&aacute;n&iacute; plamenem v&yacute;hodou</li>\r\n<li>vyhl&aacute;&scaron;ka 50/1998 Sb. v&yacute;hodou</li>\r\n</ul>','<ul>\r\n<li>z&aacute;zem&iacute; siln&eacute; mezin&aacute;rodn&iacute; společnosti</li>\r\n<li>zaj&iacute;mav&eacute; finančn&iacute; ohodnocen&iacute;</li>\r\n<li>profesn&iacute; za&scaron;kolen&iacute; a možnost dal&scaron;&iacute;ho vzděl&aacute;v&aacute;n&iacute;</li>\r\n<li>samostatnou pr&aacute;ci</li>\r\n<li>mobiln&iacute; telefon a notebook</li>\r\n<li>př&iacute;platky nad r&aacute;mec z&aacute;kon&iacute;ku pr&aacute;ce, placen&eacute; přesčasy</li>\r\n<li>dal&scaron;&iacute; vzděl&aacute;v&aacute;n&iacute; formou &scaron;kolen&iacute;</li>\r\n<li>5 t&yacute;dnů dovolen&eacute;</li>\r\n<li>př&iacute;spěvek na stravov&aacute;n&iacute;</li>\r\n<li>př&iacute;jemn&yacute; kolektiv</li>\r\n<li>k&aacute;va, čaj na pracovi&scaron;ti</li>\r\n</ul>'),
(353,67,1,1,'Logistik - manipulant','Dýšina ','<p>manipulace s materi&aacute;lem a zaji&scaron;těn&iacute; v&yacute;roby pomoc&iacute; VZV a jeř&aacute;bu v 1-směnn&eacute;m provozu s možnost&iacute; ubytov&aacute;n&iacute; v nově postaven&eacute; ubytovně v are&aacute;lu společnosti</p>','<p>orientace ve v&yacute;kresov&eacute; dokumentaci a zku&scaron;enost s obsluhou VZV<br>samostatnost, zodpovědnost, zručnost a pečlivost<br>v&yacute;hodou jsou zku&scaron;enosti ze skladu a s VZV</p>','<p>pr&aacute;ci na HPP<br>ubytov&aacute;n&iacute; ve firemn&iacute; ubytovně v are&aacute;lu firmy<br>25 dn&iacute; dovolen&eacute;<br>př&iacute;spěvek na stravov&aacute;n&iacute;<br>ročn&iacute; a věrnostn&iacute; odměny<br>př&iacute;spěvek na ubytov&aacute;n&iacute; nebo dopravu (dle intern&iacute; směrnice)<br>po ZD př&iacute;spěvek na životn&iacute; poji&scaron;těn&iacute;, nebo penzijn&iacute; připoji&scaron;těn&iacute;<br>po ZD možnost využit&iacute; MULTISPORT karty</p>'),
(354,131,1,2,'Operátor/ka výroby','Přehýšov 251, 330 23 Přehýšov','<p>V na&scaron;em v&yacute;robn&iacute;m z&aacute;vodě Wabtec v N&yacute;řanech roz&scaron;iřujeme t&yacute;m oper&aacute;torů.</p>\r\n<p>Nevyžadujeme roky praxe ani v&yacute;učn&iacute; list v oboru - v&scaron;e potřebn&eacute; v&aacute;s nauč&iacute;me př&iacute;mo u n&aacute;s.</p>\r\n<p>Zku&scaron;eněj&scaron;&iacute; kolegov&eacute; v&aacute;m pomohou a dostanete jasn&eacute; &scaron;kolen&iacute; krok za krokem.</p>','<p>Co potřebujeme, aby ve v&aacute;s bylo přirozeně:</p>\r\n<ul>\r\n<li>zručnost - ruce, kter&eacute; se pr&aacute;ce neboj&iacute; - to si vyzkou&scaron;&iacute;me při pohovoru na obyčejn&eacute; skl&aacute;dačce</li>\r\n<li>pečlivost - děl&aacute;te věci poř&aacute;dně - n&aacute;&scaron; z&aacute;kazn&iacute;k potřebuje perfektn&iacute; bezchybn&yacute; v&yacute;robek</li>\r\n<li>spolehlivost - kolegov&eacute; se na v&aacute;s mohou spolehnout - ze zač&aacute;tku pomůžeme my v&aacute;m, pak budete pom&aacute;hat vy ostatn&iacute;m</li>\r\n<li>chuť učit se - nov&eacute; dovednosti v&aacute;s posouvaj&iacute; d&aacute;l - a u n&aacute;s je učen&iacute; nekonč&iacute;c&iacute; proces</li>\r\n</ul>','<ul>\r\n<li>z&aacute;zem&iacute; stabiln&iacute; mezin&aacute;rodn&iacute; firmy</li>\r\n<li>jistotu, že se v&scaron;e nauč&iacute;te krok za krokem</li>\r\n<li>pr&aacute;ci na 7,5 hodiny denně</li>\r\n<li>čist&eacute; prostřed&iacute;</li>\r\n<li>25 dnů dovolen&eacute; a 4 sick days za rok</li>\r\n<li>v&aacute;nočn&iacute; bonus</li>\r\n<li>stravenkov&yacute; pau&scaron;&aacute;l až 2.580,- Kč/měs&iacute;c</li>\r\n<li>př&iacute;spěvek na dopravu 2 Kč/km</li>\r\n<li>flexi pass karta na volnočasov&eacute; aktivity, zdrav&iacute; a vzděl&aacute;v&aacute;n&iacute; 650,- Kč/měs&iacute;c</li>\r\n<li>př&iacute;spěvek na penzijn&iacute; poji&scaron;těn&iacute; 1.000,- Kč/měs&iacute;c</li>\r\n<li>př&iacute;spěvek na jazykov&eacute; kurzy</li>\r\n<li>odměny při pracovn&iacute;ch a životn&iacute