(359,131,1,3,'Svářeč/ka - hliník a nerez - TIG a MAG','Přehýšov 251, 330 23 Přehýšov','<ul>\r\n<li>svařov&aacute;n&iacute; hlin&iacute;kov&yacute;ch a nerezov&yacute;ch d&iacute;lů klimatizačn&iacute;ch jednotek</li>\r\n<li>dodřžov&aacute;n&iacute; požadavků v&yacute;kresov&eacute; dokumentace a postupů svařov&aacute;n&iacute;</li>\r\n<li>prov&aacute;děn&iacute; vizu&aacute;ln&iacute; kontroly každ&eacute;ho svařence</li>\r\n<li>kontrola vstupn&iacute;ho materi&aacute;lu a měřidel</li>\r\n<li>pr&aacute;ce ve v&iacute;cesměnn&eacute;m provozu</li>\r\n</ul>','<ul>\r\n<li>zku&scaron;enost se svařov&aacute;n&iacute;m metodou TIG a MAG</li>\r\n<li>ochota pracovat ve směnn&eacute;m provozu</li>\r\n<li>absolvov&aacute;n&iacute; zkou&scaron;ky dovednosti v na&scaron;&iacute; společnosti</li>\r\n<li>pečlivost, zodpovědnost, svědomitost</li>\r\n</ul>','<ul>\r\n<li>pr&aacute;ci na 7,5 hodiny denně</li>\r\n<li>př&iacute;platek za odpoledn&iacute; směnu 8 %</li>\r\n<li>př&iacute;platek za nočn&iacute; směnu 80 Kč / hod</li>\r\n<li>čist&eacute; prostřed&iacute;</li>\r\n<li>25 dnů dovolen&eacute; a 4 sick days za rok</li>\r\n<li>v&aacute;nočn&iacute; bonus</li>\r\n<li>stravenkov&yacute; pau&scaron;&aacute;l až 2.580,- Kč / měs&iacute;c</li>\r\n<li>př&iacute;spěvek na dopravu 2,- Kč / km</li>\r\n<li>flexi pass karta na volnočasov&eacute; aktivity, zdrav&iacute; a vzděl&aacute;v&aacute;n&iacute; 650,- Kč/měs&iacute;c</li>\r\n<li>př&iacute;spěvek na penzijn&iacute; poji&scaron;těn&iacute; 1.000,- Kč/měs&iacute;c</li>\r\n<li>př&iacute;spěvek na jazykov&eacute; kurzy</li>\r\n<li>odměny při pracovn&iacute;ch a životn&iacute;ch jubile&iacute;ch</li>\r\n<li>odměny za doporučen&iacute; zaměstnanců</li>\r\n<li>odměny pro d&aacute;rce krve</li>\r\n<li>bezplatnou odbornou pomoc - pr&aacute;vn&iacute;, psychologickou, finančn&iacute;</li>\r\n<li>slevy na vozy &Scaron;koda Auto</li>\r\n<li>firemn&iacute; akce</li>\r\n<li>podpora rozvoje a vzděl&aacute;v&aacute;n&iacute;</li>\r\n</ul>'),
(360,129,1,4,'Kuchař/ka','Plzeň','<p>Kuchař připravuje teplou a studenou kuchyni dle platn&yacute;ch ČSN pro tato j&iacute;dla v souladu s hygienick&yacute;mi a nejnověj&scaron;&iacute;mi zdravotně-v&yacute;živov&yacute;mi trendy a nutričn&iacute;mi doporučen&iacute;mi.</p>','<ul>\r\n<li>SOU obor \"Kuchař - č&iacute;&scaron;n&iacute;k\", popř&iacute;padě absolvent Hotelov&eacute; &scaron;koly</li>\r\n<li>fyzickou zdatnost</li>\r\n<li>ochotu učit se nov&yacute;m věcem</li>\r\n<li>praxe je v&yacute;hodou, nikoli podm&iacute;nkou</li>\r\n</ul>','<p>5 t&yacute;dnů dovolen&eacute;, stravenky, sick-days, př&iacute;spěvky na sport či volnočasov&eacute; aktivity dět&iacute;.</p>'),
(361,129,0,2,'Uklízeč/ka','','<p>Ukl&iacute;zečka zaji&scaron;ťuje &uacute;klid kancel&aacute;ř&iacute; a společn&yacute;ch prostor firmy, d&aacute;le vyn&aacute;&scaron;en&iacute; odpadků, doplňov&aacute;n&iacute; drogistick&yacute;ch potřeb ve firmě (m&yacute;dlo, WC pap&iacute;r, pytle na odpadky atd.) a v neposledn&iacute; řadě tak&eacute; oči&scaron;těn&iacute; skleněn&eacute; v&yacute;plně vstupn&iacute;ch dveř&iacute; firmy.</p>','<ul>\r\n<li>pracovitost</li>\r\n<li>časovou flexibilitu</li>\r\n<li>fyzickou zdatnost</li>\r\n<li>praktičnost</li>\r\n<li>čist&yacute; trestn&iacute; rejstř&iacute;k</li>\r\n</ul>','<ul>\r\n<li>5 t&yacute;dnů dovolen&eacute;</li>\r\n<li>stravenky</li>\r\n<li>možnost ubytov&aacute;n&iacute;</li>\r\n<li>Mama friendly př&iacute;stup</li>\r\n</ul>'),
(362,88,1,4,'Servisní technik','Nýřany','<p>Servisn&iacute; technik zaji&scaron;ťuje servis př&iacute;strojů a zař&iacute;zen&iacute;, použ&iacute;van&yacute;ch ve firmě s v&yacute;jimkou strojů typu CNC a strojů obr&aacute;běc&iacute;ch, kde se touto činnost&iacute; zab&yacute;v&aacute; strojn&iacute;k (strojař).</p>','<ul>\r\n<li>spolehlivost</li>\r\n<li>pracovitost</li>\r\n<li>časovou flexibilitu</li>\r\n<li>ochotu učit se nov&yacute;m věcem</li>\r\n<li>SOU nejl&eacute;pe technick&eacute;ho směru</li>\r\n<li>čist&yacute; trestn&iacute; rejstř&iacute;k</li>\r\n<li>ŘP B</li>\r\n</ul>','<ul>\r\n<li>Firemn&iacute; stravenky</li>\r\n<li>5 t&yacute;dnů dovolen&eacute;</li>\r\n<li>permanentky na fotbal či hokej</li>\r\n<li>př&iacute;spěvek na dětsk&eacute; kroužky</li>\r\n<li>možnost ubytov&aacute;n&iacute; nedaleko firmy</li>\r\n</ul>'),
(363,88,1,4,'Řidič VZV vozíku','Nejdek','<p>Řidič VZV voz&iacute;ku m&aacute; jako n&aacute;plň pr&aacute;ce j&iacute;zdu a přemisťov&aacute;n&iacute; břemen prostřednictv&iacute;m vysokozdvižn&eacute;ho voz&iacute;ku (vč. &uacute;držby VZV). Mus&iacute; dodržovat v&scaron;echny předpisy BOZP a nepož&iacute;vat před prac&iacute; ani během n&iacute; alkoholick&eacute; n&aacute;poje a drogy.</p>','<ul>\r\n<li>SOU s maturitou</li>\r\n<li>zkou&scaron;ku na obsluhu VZV a jeho ř&iacute;zen&iacute;</li>\r\n<li>čist&yacute; trestn&iacute; rejstř&iacute;k</li>\r\n<li>fyzickou zdatnost</li>\r\n</ul>','<ul>\r\n<li>5 t&yacute;dnů dovolen&eacute;</li>\r\n<li>firemn&iacute; stravov&aacute;n&iacute;</li>\r\n<li>dopravu do zaměstn&aacute;n&iacute;</li>\r\n<li>sick-days</li>\r\n<li>permanentky do fitka</li>\r\n</ul>'),
(364,89,1,5,'Administrativní pracovník/ce','Kouřim','<p>Administrativn&iacute; pracovn&iacute;k vykon&aacute;v&aacute; administrativn&iacute; pr&aacute;ci dle pokynů nadř&iacute;zen&eacute;ho, přičemž využ&iacute;v&aacute; poč&iacute;tač anebo notebook a rovněž vyřizuje p&iacute;semnou i elektronickou komunikaci dle pokynů nadř&iacute;zen&eacute;ho.</p>','<ul>\r\n<li>S&Scaron; s maturitou</li>\r\n<li>znalost syst&eacute;mů ERP</li>\r\n<li>pokročilou znalost pr&aacute;ce na poč&iacute;tači (MS Word, Excel, atd.)</li>\r\n<li>pracovitost</li>\r\n<li>čist&yacute; trestn&iacute; rejstř&iacute;k</li>\r\n<li>časovou flexibilitu</li>\r\n</ul>','<ul>\r\n<li>firemn&iacute; stravov&aacute;n&iacute;</li>\r\n<li>5 t&yacute;dnů dovolen&eacute;</li>\r\n<li>dopravu do zaměstn&aacute;n&iacute;</li>\r\n<li>permanentky pro děti do plzeňsk&eacute; ZOO</li>\r\n</ul>'),
(365,89,1,2,'Čistič/ka oken','Nová Role','<p>Čistič oken m&aacute; za &uacute;kol zaji&scaron;ťovat čist&aacute; a nepo&scaron;kozen&aacute; okna ve firmě. K pr&aacute;ci použ&iacute;v&aacute; čist&iacute;c&iacute; prostředky na či&scaron;těn&iacute; skel a různ&eacute; vhodn&eacute; utěrky na sklo. Mus&iacute; db&aacute;t tak&eacute; na BOZP a nevykl&aacute;nět se z oken!</p>','<ul>\r\n<li>Z&Scaron;</li>\r\n<li>čist&yacute; trestn&iacute; rejstř&iacute;k</li>\r\n<li>pečlivost a spolehlivost</li>\r\n<li>časovou flexibilitu</li>\r\n<li>pracovitost</li>\r\n</ul>','<ul>\r\n<li>5 t&yacute;dnů dovolen&eacute;</li>\r\n<li>ubytov&aacute;n&iacute; v m&iacute;stě zaměstn&aacute;n&iacute;</li>\r\n<li>stravenky</li>\r\n<li>permanentky do fitka</li>\r\n</ul>'),
(366,80,0,5,'Bankovní poradce ČSOB','','<p>Co tě ček&aacute;?</p>\r\n<p>Pr&aacute;ce s lidmi: Bude&scaron; pom&aacute;hat na&scaron;im klientům naj&iacute;t nejlep&scaron;&iacute; finančn&iacute; ře&scaron;en&iacute;.<br>Nab&iacute;dka produktů ČSOB: Siln&aacute; značka na trhu, kter&aacute; m&aacute; ve světě financ&iacute; pevn&eacute; m&iacute;sto.<br>Nadstandardn&iacute; odměňov&aacute;n&iacute;: K pevn&eacute; mzdě z&iacute;sk&aacute;&scaron; nejen neomezen&yacute; strop proviz&iacute;, ale i mimoř&aacute;dn&eacute; body za uzavřen&eacute; produkty.<br>Př&iacute;choz&iacute; klientela: Bude&scaron; m&iacute;t k dispozici stabiln&iacute; př&iacute;choz&iacute; klientelu, a nav&iacute;c obdrž&iacute;&scaron; vlastn&iacute; portfolio klientů.<br>Osobn&iacute; rozvoj: U n&aacute;s se ti dostane ve&scaron;ker&eacute;ho &scaron;kolen&iacute; a podpory.<br>Svoboda a samostatnost: S&aacute;m si určuje&scaron; svůj harmonogram schůzek.<br>Podpora t&yacute;mu</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>','<p>Chuť se do toho opř&iacute;t<br>Motivaci<br>Minim&aacute;lně středo&scaron;kolsk&eacute; vzděl&aacute;n&iacute; a čist&yacute; trestn&iacute; rejstř&iacute;k</p>','<p>Neomezen&eacute; provize a atraktivn&iacute; bodov&yacute; syst&eacute;m Bodovka!<br>Skvěl&yacute; start kari&eacute;ry<br>Př&aacute;telsk&aacute; atmosf&eacute;ra<br>Stabiln&iacute; zaměstn&aacute;n&iacute;<br>Za&scaron;kolen&iacute; zdarma<br>Stravenkov&yacute; pau&scaron;&aacute;l a MultiSportka<br>T&yacute;den dovolen&eacute; nav&iacute;c a k tomu př&iacute;spěvek na rekreaci<br>V&yacute;konnostn&iacute; bonusy<br>Př&iacute;spěvky na životn&iacute; poji&scaron;těn&iacute;, nebo penzi<br>Zv&yacute;hodněn&eacute; produkty a tarify</p>'),
(367,137,1,3,'SKLADNÍK - ŘIDIČ VZV','Palírenská 641/2, 32600 Plzeň - Božkov, Česká','<p>Hled&aacute;me zručn&eacute;ho kolegu/kolegyni se zku&scaron;enostmi z ř&iacute;zen&iacute;m vysokozdvižn&eacute;ho voz&iacute;ku, kter&yacute;/&aacute; m&aacute; dopln&iacute; n&aacute;&scaron; t&yacute;m ve skladu. Voz&iacute;me palety se sklem, takže pevn&aacute; ruka a opatrnost se v&aacute;m bude hodit, u n&aacute;s se totiž palety maj&iacute; ,,jako v peřince\" proto je praxe a opatrnost při manipulaci s paletami podm&iacute;nka.</p>\r\n<p>Proč STOCK Plzeň Božkov?</p>\r\n<p>Chcete b&yacute;t u procesu, kdy se pr&aacute;zdn&aacute; l&aacute;hev pln&iacute; n&aacute;pojem, zdob&iacute; etiketou a vkl&aacute;d&aacute; do kartonu a n&aacute;sledně putuje do ledničky Va&scaron;&iacute; rodiny i Va&scaron;ich př&aacute;tel?</p>\r\n<p>Chcete v l&eacute;tě na vodě, na oslav&aacute;ch či při jin&yacute;ch př&iacute;ležitostech c&iacute;tit hrdost, že pr&aacute;vě tato lahvinka V&aacute;m pro&scaron;la rukama?<br>Staňte se souč&aacute;st&iacute; tradičn&iacute; kultury a pojďte pracovat do atraktivn&iacute;ho prostřed&iacute; lik&eacute;rky STOCK Plzeň-Božkov, jedničky na česk&eacute;m trhu lihovin.</p>\r\n<p>Pr&aacute;vě teď hled&aacute;me do na&scaron;eho mal&eacute;ho t&yacute;mu fajn lid&iacute; spolehliv&eacute;ho kolegu či kolegyni do oddělen&iacute; logistiky/skladu.</p>','<p>Co V&aacute;s u n&aacute;s ček&aacute;?</p>\r\n<p>ř&iacute;zen&iacute; vysokozdvižn&eacute;ho motorov&eacute;ho voz&iacute;ku<br>pomoc při vykl&aacute;dce, nakl&aacute;dce (uskladněn&iacute; palet)<br>z&aacute;sobov&aacute;n&iacute; linek materi&aacute;lem (lahve, plechovky, obalov&eacute; materi&aacute;ly)<br>manipulace se zbož&iacute;m a paletami v r&aacute;mci skladů<br>pr&aacute;ce v mal&eacute;m kolektivu<br>pozice je vhodn&aacute; i pro ženy<br>pracovat budete na tři směny</p>\r\n<p>Ide&aacute;ln&iacute; kandid&aacute;tem/kandid&aacute;tkou jste, pokud:</p>\r\n<p>m&aacute;te praxi v ř&iacute;zen&iacute; VZV min. 1 rok<br>m&aacute;te platn&yacute; řidičsk&yacute; průkaz VZV typu A, D, W1<br>m&aacute;te řidičsk&yacute; průkaz sk. B<br>m&aacute;te z&aacute;kladn&iacute; znalosti s PC<br>jste ochoten/ochotna učit se nov&yacute;m věcem<br>mluv&iacute;te v&yacute;borně česky<br>jste t&yacute;mov&yacute; hr&aacute;č</p>','<p>Co V&aacute;m na opl&aacute;tku nab&iacute;z&iacute;me?</p>\r\n<p>v&scaron;e V&aacute;s nauč&iacute;me a za&scaron;kol&iacute;me pod podhledem zku&scaron;en&eacute;ho kolegy.<br>zaj&iacute;mavou pracovn&iacute; př&iacute;ležitost a jistotu zaměstn&aacute;n&iacute; ve stabiln&iacute; společnosti<br>mzdov&eacute; ohodnocen&iacute; dle nabyt&yacute;ch zku&scaron;enost&iacute; a pravidelnou valorizaci mezd<br>pohodov&eacute; prostřed&iacute; a př&aacute;telsk&yacute; kolektiv<br>25 dn&iacute; dovolen&eacute;<br>nadstandardn&iacute; př&iacute;platky (př&iacute;platek za pr&aacute;ci v noci 20%, př&iacute;platek za pr&aacute;ci o v&iacute;kendu 50%)<br>př&iacute;spěvek za doch&aacute;zku 500,- Kč měs&iacute;čně<br>stravenky v hodnotě 3 500,- Kč/měs&iacute;čně a možnost stravov&aacute;n&iacute; ve firemn&iacute; kant&yacute;ně<br>př&iacute;spěvek na penzijn&iacute; připoji&scaron;těn&iacute; 12 000 Kč ročně<br>benefitn&iacute; body do Cafeterie 4 800 Kč ročně na sport, zdrav&iacute;, kulturu a voln&yacute; čas<br>př&iacute;spěvek na dopravu 4 800 Kč ročně<br>bal&iacute;ček na&scaron;ich produktů (deput&aacute;t)<br>z&aacute;vodn&iacute; stravov&aacute;n&iacute;<br>cyklist&eacute; u n&aacute;s maj&iacute; u zelenou (zastře&scaron;en&eacute; parkovi&scaron;tě, &scaron;atny)</p>'),
(368,137,1,3,'Operátor výroby v oddělení BLENDING','Palírenská 641/2, 32600 Plzeň - Božkov, Česká','<p>Hled&aacute;me nov&eacute;ho kolegu či kolegyni do t&yacute;mu Blendingu &ndash; důležit&eacute; č&aacute;sti v&yacute;roby, kde vznikaj&iacute; na&scaron;e produkty, na kter&eacute; jsme pr&aacute;vem hrd&iacute;.</p>\r\n<p>Oddělen&iacute; blendingu je kl&iacute;čov&aacute; č&aacute;st na&scaron;eho z&aacute;vodu &ndash; ze z&aacute;kladn&iacute;ch surovin zde vznikaj&iacute; hotov&eacute; tekutiny na&scaron;ich zn&aacute;m&yacute;ch značek jako je Fernet STOCK, Republika, Božkov Tuzemsk&yacute; a dal&scaron;&iacute;, připraven&eacute; ke st&aacute;čen&iacute; do lahv&iacute;.</p>\r\n<p>&nbsp;</p>','<p>Koho hled&aacute;me?</p>\r\n<p>Jste pečliv&yacute;/&aacute;, zodpovědn&yacute;/&aacute; a neboj&iacute;te se fyzick&eacute; pr&aacute;ce.<br>M&aacute;te schopnost pr&aacute;ce s dokumentac&iacute; a dodržov&aacute;n&iacute; technologick&yacute;ch postupů.<br>V&yacute;hodou je zku&scaron;enost z v&yacute;roby potravin, n&aacute;pojů nebo chemie &ndash; nen&iacute; v&scaron;ak podm&iacute;nkou.<br>Česk&yacute; jazyk na komunikativn&iacute; &uacute;rovni, čten&iacute; i psan&iacute; &ndash; budete ps&aacute;t potřebnou dokumentaci, kter&aacute; se v&aacute;že k v&yacute;robě.<br>Spolehlivost, t&yacute;mov&yacute; duch a chuť zapojit se do v&yacute;roby jedinečn&yacute;ch produktů.<br>Ochota pracovat i odpoledn&iacute; směny</p>','<p>Co V&aacute;m na opl&aacute;tku nab&iacute;z&iacute;me?</p>\r\n<p>Zaj&iacute;mav&eacute; finančn&iacute; ohodnocen&iacute; a každ&yacute; rok valorizace mzdy<br>Měs&iacute;čn&iacute; &bdquo;bonus&ldquo; + dal&scaron;&iacute; nadstandardn&iacute; př&iacute;platky<br>Stravenky v hodnotě 170,- Kč za odpracovan&yacute; den (př&iacute;spěvek zaměstnavatele 93,50 Kč).<br>Deput&aacute;t (na&scaron;e vybran&eacute; produkty každ&yacute;ch 6 měs&iacute;ců).<br>Zv&yacute;hodněn&yacute; zaměstnaneck&yacute; prodej.<br>Př&iacute;spěvek na penzijn&iacute; připoji&scaron;těn&iacute; ve v&yacute;&scaron;i 12.000,- Kč ročně.<br>Př&iacute;spěvek na dopravu ve v&yacute;&scaron;i 4.800,- Kč ročně.<br>Př&iacute;spěvek na sport/kulturu/voln&yacute; čas ve v&yacute;&scaron;i 4.800,- Kč ročně.<br>25 dnů dovolen&eacute; a dal&scaron;&iacute; nav&iacute;c dle opracovan&yacute;ch let.</p>'),
(369,137,1,2,'Operátor stáčecí linky/ Operátor zásobních tanků','Palírenská 641/2, 32600 Plzeň - Božkov, Česká','<p>Buďte př&iacute;mo u toho, jak vznikaj&iacute; na&scaron;e legend&aacute;rn&iacute; produkty, a staňte se souč&aacute;st&iacute; dlouholet&eacute; tradice v&yacute;roby kvalitn&iacute;ch lik&eacute;rů a dal&scaron;&iacute;ch v&yacute;robků. Pracujte pro značku, na kterou můžete b&yacute;t hrd&yacute;/&aacute; &ndash; a v obchodech potk&aacute;vat produkty, na jejichž vzniku jste se s&aacute;m/sama pod&iacute;lel/a.</p>\r\n<p>Aktu&aacute;lně hled&aacute;me zaměstnance na tyto pozice:</p>\r\n<p>Oper&aacute;tor st&aacute;čec&iacute; linky a&nbsp;Oper&aacute;tor z&aacute;sobn&iacute;ch tanků</p>\r\n<p>Co V&aacute;s u n&aacute;s ček&aacute;?<br>Obsluha st&aacute;čec&iacute;ch strojů<br>Kontrola produktu, spr&aacute;vn&yacute;ch etiket, obalov&yacute;ch materi&aacute;lů apod.<br>Prov&aacute;děn&iacute; z&aacute;kladn&iacute; &uacute;držby linky, či&scaron;těn&iacute; linky apod.<br>Kontrola kvality (spr&aacute;vně nalepen&aacute; etiketa, neporu&scaron;en&yacute; karton, pevně drž&iacute;c&iacute; kolek apod.)<br>Dodržov&aacute;n&iacute; BOZP a dal&scaron;&iacute;ch intern&iacute;ch předpisů<br>Dodržov&aacute;n&iacute; postupů, spolupr&aacute;ce s kolegy</p>','<p>Co od V&aacute;s oček&aacute;v&aacute;me?<br>Manu&aacute;ln&iacute; zručnost<br>Ovl&aacute;d&aacute;te dobře počty, nelehnete se pr&aacute;ce se z&aacute;sobn&iacute;mi tanky<br>Zku&scaron;enost z automatick&eacute; nebo poloautomatick&eacute; v&yacute;roby velkou v&yacute;hodou<br>Spolehlivost a zodpovědnost<br>Fyzickou zdatnost<br>Ochotu pracovat ve směnn&eacute;m provozu a během sezony i v nepřetržit&eacute;m provozu<br>Odolnost vůči stresu</p>','<p>Co V&aacute;m na opl&aacute;tku nab&iacute;z&iacute;me?<br>Rychle rostouc&iacute; mzdu - po zaučen&iacute; v&aacute;m finance nav&yacute;&scaron;&iacute;me<br>Nadstandardn&iacute; př&iacute;platky za nočn&iacute; či v&iacute;kendov&eacute; směny<br>Stravenky v hodnotě 170,- Kč za odpracovan&yacute; den (př&iacute;spěvek zaměstnavatele 93,50 Kč).<br>Deput&aacute;t (na&scaron;e vybran&eacute; produkty každ&yacute;ch 6 měs&iacute;ců)<br>Vzorky na&scaron;ich produktů<br>Př&iacute;spěvek na penzijn&iacute; připoji&scaron;těn&iacute; ve v&yacute;&scaron;i 12.000,- Kč ročně.<br>Př&iacute;spěvek na dopravu ve v&yacute;&scaron;i 4.800,- ročně.<br>Př&iacute;spěvek na sport/kulturu/voln&yacute; čas ve v&yacute;&scaron;i 4.800,- Kč ročně.<br>25 dnů dovolen&eacute; a dal&scaron;&iacute; nav&iacute;c dle opracovan&yacute;ch let.<br>N&aacute;stup možn&yacute; ihned př&iacute;padně dle dohody.</p>'),
(370,137,1,4,'Laborant/Laborantka','Palírenská 641/2, 32600 Plzeň - Božkov, Česká','<p>Do na&scaron;eho sedmičlenn&eacute;ho t&yacute;mu hled&aacute;me kolegu nebo kolegyni, kter&yacute;/kter&aacute; spolu s n&aacute;mi bude zaji&scaron;ťovat nejvy&scaron;&scaron;&iacute; kvalitu na&scaron;ich v&yacute;robků. Bude v&aacute;s čekat nejen laboratorn&iacute; anal&yacute;za ale tak&eacute; odběr vzorků př&iacute;mo ve v&yacute;robě a kontrola dal&scaron;&iacute;ch kvalitativn&iacute;ch krit&eacute;ri&iacute; na&scaron;ich produktů.</p>\r\n<p>Pr&aacute;ce u n&aacute;s V&aacute;s bude bavit, pokud:<br>M&aacute;te r&aacute;d/a komplexn&iacute; laboratorn&iacute; činnost v akreditovan&eacute; laboratoři<br>Bez laboratorn&iacute;ch anal&yacute;z, (během v&yacute;roby, fin&aacute;ln&iacute; polotovary, fin&aacute;ln&iacute; produkty) se neobejdete stejně jako my.<br>M&aacute;te r&aacute;d/a poř&aacute;dek na pracovi&scaron;ti a v&scaron;e ř&aacute;dně zdokumentov&aacute;no - v&scaron;e zapisujeme a evidujeme.<br>Chcete b&yacute;t ve styku s v&yacute;robou - hodnot&iacute;me kvalitu v&yacute;robků a surovin, dodržov&aacute;n&iacute; standardů na na&scaron;ich v&yacute;robn&iacute;ch link&aacute;ch.<br>R&aacute;di při pr&aacute;ci komunikujete a před&aacute;v&aacute;te informace kolegům např&iacute;č oddělen&iacute;mi - bez komunikace se neobejdeme.<br>Nevad&iacute; V&aacute;m stř&iacute;dat se s kolegyněmi na směn&aacute;ch ve 3 směnn&eacute;m provozu (v sezoně nepřetržit&eacute;m).</p>','<p>Podm&iacute;nky pr&aacute;ce:</p>\r\n<p>S&Scaron; nebo V&Scaron; vzděl&aacute;n&iacute; v chemick&eacute;m oboru, ide&aacute;lně se zaměřen&iacute;m na potravin&aacute;řstv&iacute;, analytickou chemii nebo př&iacute;buzn&eacute; obory<br>Praxe v laboratoři, ide&aacute;lně v oblasti testov&aacute;n&iacute; a rozborů v potravin&aacute;řsk&eacute;m průmyslu<br>Znalost laboratorn&iacute;ch metod a postupů<br>V laboratoři pracujeme na 3 směny - rann&iacute; (6-14h PO-P&Aacute;), odpoledn&iacute; (14-22h PO-P&Aacute;) a nočn&iacute; (22-06h - zač&aacute;tek neděle večer, konec p&aacute;tek r&aacute;no), v&iacute;kendy jsou u n&aacute;s ale voln&eacute;. V sez&oacute;ně před Velikonoci a V&aacute;noci m&aacute;me i nepřetržit&yacute; provoz.</p>','<p>Co od n&aacute;s za dobře vykonanou pr&aacute;ci dostanete?</p>\r\n<p>zaj&iacute;mavou pracovn&iacute; př&iacute;ležitost a jistotu zaměstn&aacute;n&iacute; ve stabiln&iacute; společnosti<br>pohodov&eacute; prostřed&iacute; a př&aacute;telsk&yacute; kolektiv<br>mzdov&eacute; ohodnocen&iacute; dle nabyt&yacute;ch zku&scaron;enost&iacute; a pravidelnou valorizaci mezd<br>25 dn&iacute; dovolen&eacute; + dal&scaron;&iacute; dle odpracovan&yacute;ch let<br>nadstandardn&iacute; př&iacute;platky (př&iacute;platek za pr&aacute;ci v noci 20 %, př&iacute;platek za pr&aacute;ci o v&iacute;kendu 50 %)<br>př&iacute;spěvek za doch&aacute;zku 500 Kč měs&iacute;čně<br>stravenky v hodnotě Kč 170,-/den a možnost stravov&aacute;n&iacute; ve firemn&iacute; kant&yacute;ně<br>př&iacute;spěvek na penzijn&iacute; připoji&scaron;těn&iacute; 12 000 Kč ročně<br>benefitn&iacute; body do Cafeterie 4 800 Kč ročně na sport, zdrav&iacute;, kulturu a voln&yacute; čas<br>př&iacute;spěvek na dopravu 4 800 Kč ročně<br>2x ročně bal&iacute;ček na&scaron;ich produktů (deput&aacute;t), mimoř&aacute;dn&yacute; prodej dle vlastn&iacute;ho v&yacute;běru 2x ročně</p>'),
(371,70,1,3,'Technik údržby','Plzeň','<p><strong>Co bude Va&scaron;&iacute; n&aacute;pln&iacute; pr&aacute;ce?</strong></p>\r\n<p>&Uacute;držba v&scaron;eho, co ve skladu můžete potkat<br>Prov&aacute;děn&iacute; preventivn&iacute;ch prohl&iacute;dek techniky v souladu se schv&aacute;len&yacute;m harmonogramem<br>Denn&iacute; hl&aacute;&scaron;en&iacute; technick&eacute;ho stavu a zji&scaron;těn&yacute;ch nedostatků<br>Dohled nad pracemi extern&iacute;ch společnost&iacute;<br>Hled&aacute;n&iacute; nov&yacute;ch technick&yacute;ch ře&scaron;en&iacute;, snižuj&iacute;c&iacute;ch poruchovost zař&iacute;zen&iacute;</p>','<p><strong>Co od V&aacute;s ček&aacute;me?</strong></p>\r\n<p><br>Praxe na podobn&eacute; pozici v&yacute;hodou<br>Manu&aacute;ln&iacute; zručnost a schopnost si poradit<br>Ochota pracovat ve tř&iacute;směnn&eacute;m provozu<br>Osvědčen&iacute; dle NV č.194/2022 Sb. (b&yacute;val&aacute; vyhl&aacute;&scaron;ka č. 50, &sect; 6) v&yacute;hodou<br>Trestn&iacute; bez&uacute;honnost</p>','<p><strong>Co V&aacute;m nab&iacute;z&iacute;me?</strong></p>\r\n<p><br>Uveden&iacute; do role a důkladn&yacute; z&aacute;cvik od zku&scaron;eněj&scaron;&iacute;ch kolegů<br>Plně hrazen&eacute; 100Kč stravenky = měs&iacute;čně cca 2.000 Kč<br>T&yacute;den dovolen&eacute; nav&iacute;c = 25 dn&iacute;<br>Pravideln&yacute; v&yacute;platn&iacute; term&iacute;n k 10. dni v měs&iacute;ci<br>Pracovat budete v čist&eacute;m, př&aacute;telsk&eacute;m a bezpečn&eacute;m prostřed&iacute;<br>Akce pro zaměstnance: teambuilding, rodinn&yacute; den, sportovn&iacute; odpoledne, grilov&aacute;n&iacute;, ovocn&eacute; dny apod.<br>Nab&iacute;z&iacute;me př&iacute;spěvek na penzijn&iacute; připoji&scaron;těn&iacute; a poji&scaron;těn&iacute; odpovědnosti<br>Možnost v&yacute;hodn&eacute;ho n&aacute;kupu akci&iacute; skupiny DHL Group<br>Levněj&scaron;&iacute; tarify od oper&aacute;torů O2 a T-Mobile, slevy u dal&scaron;&iacute;ch partnerů (např. Alza, Raiffeisenbank, Unicerdit, Samsung, Dr.Max, ZOOT, Grizly a mnoho dal&scaron;&iacute;ch)<br>Možnost MULTISPORT karty a kartu do MAKRA<br>Odměna po odpracovan&eacute;m 1., 2. a 5. roce i za narozeniny a jin&eacute; v&yacute;znamn&eacute; ud&aacute;losti</p>\r\n<p>&bdquo;Pr&aacute;vn&iacute; informace: vlastn&iacute;kem inzer&aacute;tu je společnost DHL Solutions k.s.\"<br><br></p>'),
(372,70,1,5,'Operations Supervisor','Nýřany','<p><strong>Co bude tv&yacute;m &uacute;kolem?</strong></p>\r\n<p><br>Koordinace každodenn&iacute;ho provozu (sklad, přeprava nebo distribučn&iacute; centrum)<br>Veden&iacute;, motivace a rozvoj t&yacute;mu<br>Aktivn&iacute; zapojen&iacute; do procesu zlep&scaron;ov&aacute;n&iacute; k dosažen&iacute; vy&scaron;&scaron;&iacute; efektivity<br>Průběžn&yacute; reporting managementu a z&aacute;kazn&iacute;kovi<br>Odpovědnost za KPIs<br>Dodržov&aacute;n&iacute; BOZP<br>Odpovědnost za finančn&iacute; v&yacute;sledky svěřen&yacute;ch &uacute;seků<br>Pl&aacute;nov&aacute;n&iacute; zdrojů, sledov&aacute;n&iacute; změn a odchylek ve forecastech a aktualizace pl&aacute;nů</p>','<p><strong>Co od tebe oček&aacute;v&aacute;me?</strong></p>\r\n<p><br>Zku&scaron;enosti z logistiky, ide&aacute;lně na obdobn&eacute; pozici popř. z jin&yacute;ch provozů<br>Schopnost v&eacute;st t&yacute;m a rozhodovat se v dynamick&eacute;m prostřed&iacute;<br>Znalost pr&aacute;ce s MS Office, v&yacute;hodou SAP / WMS syst&eacute;my<br>Orientaci na c&iacute;l, analytick&eacute; my&scaron;len&iacute; a dobr&eacute; komunikačn&iacute; dovednosti<br>Zodpovědnost a důraz na dodržov&aacute;n&iacute; procesů<br>Znalost anglick&eacute;ho jazyka umožňuj&iacute;c&iacute; každodenn&iacute; komunikaci B1/B2<br>Řidičsk&yacute; průkaz B<br>Trestn&iacute; bez&uacute;honnost</p>','<p><strong>Co V&aacute;m můžeme nab&iacute;dnout?</strong></p>\r\n<p><br>Kari&eacute;rn&iacute; růst a celou řadu certifikovan&yacute;ch &scaron;kolen&iacute;ch<br>Atraktivn&iacute; mzdov&eacute; podm&iacute;nky a ročn&iacute; bonus<br>Z&aacute;zem&iacute; modern&iacute; logistick&eacute; firmy s mnohaletou tradic&iacute; na česk&eacute;m trhu<br>Flexibiln&iacute; pracovn&iacute; dobu<br>Dovolenou budete tr&aacute;vit 25 dnů v roce<br>Možnost profesn&iacute;ho rozvoje a osobn&iacute;ho růstu podpořen&eacute;ho firemn&iacute;mi vzděl&aacute;vac&iacute;mi programy<br>Plně hrazen&eacute; stravenky 100 Kč/den, 25 dn&iacute; dovolen&eacute;, MultiSport karta, Makro karta, v&yacute;hodn&yacute; mobiln&iacute; tarif, penzijn&iacute; připoji&scaron;těn&iacute;, Cafeterie a dal&scaron;&iacute;&hellip;</p>'),
(373,87,1,5,'Kontaktní pracovník pro styk s podniky','Plzeň','<p>S lehkost&iacute; a radost&iacute; komunikujete s lidmi? Zn&aacute;te podnikov&eacute; prostřed&iacute;? R&aacute;di vyjedn&aacute;v&aacute;te? Vn&iacute;m&aacute;te jedn&aacute;n&iacute; se z&aacute;kazn&iacute;ky jako efektivně str&aacute;ven&yacute; čas?<br>Přidejte se k n&aacute;m!</p>\r\n<p>Nudit se určitě nebudete, do pracovn&iacute; n&aacute;plně patř&iacute;:</p>\r\n<ul>\r\n<li>analyzovat vzděl&aacute;vac&iacute; potřeby v podnic&iacute;ch</li>\r\n<li>připravovat konkr&eacute;tn&iacute; nab&iacute;dky kurzů</li>\r\n<li>vyhled&aacute;vat nov&eacute; z&aacute;kazn&iacute;ky a pečovat o ty st&aacute;vaj&iacute;c&iacute;</li>\r\n<li>b&yacute;t nejen obchodn&iacute;kem, ale tak&eacute; partnerem a konzultantem v podnikov&eacute;m prostřed&iacute;</li>\r\n<li>doporučovat vhodn&eacute; dotačn&iacute; programy</li>\r\n<li>realizovat skvěl&eacute; akce pro odbornou i &scaron;irokou veřejnost</li>\r\n</ul>','<ul>\r\n<li>min. S&Scaron;, V&Scaron; v&iacute;t&aacute;na</li>\r\n<li>schopnost aktivně komunikovat a v&eacute;st jedn&aacute;n&iacute;</li>\r\n<li>odvaha hledat ře&scaron;en&iacute;</li>\r\n<li>radost z v&yacute;sledku</li>\r\n<li>schopnost naslouchat</li>\r\n<li>důslednost</li>\r\n<li>pokročil&aacute; znalost MS Office</li>\r\n<li>komunikativn&iacute; znalost AJ nebo NJ</li>\r\n<li>ŘP sk. B</li>\r\n<li>předchoz&iacute; obchodn&iacute; praxe</li>\r\n</ul>','<ul>\r\n<li>atraktivn&iacute; syst&eacute;mem hodnocen&iacute;, aneb kdo se neboj&iacute;, ten si vyděl&aacute;</li>\r\n<li>podpora a za&scaron;kolen&iacute; do problematiky vzděl&aacute;v&aacute;n&iacute;</li>\r\n<li>opravdu neform&aacute;ln&iacute; pracovn&iacute; prostřed&iacute;</li>\r\n<li>různorod&aacute; prace s prostorem pro vlastn&iacute; kreativitu</li>\r\n<li>stravenky a možnost vlastn&iacute;ho rozvoje</li>\r\n</ul>'),
(374,90,0,1,'Testovkový tester','tady','','',''),
(375,132,1,2,'Operátor výroby','Plzeň','<p>budete se pod&iacute;let na v&yacute;robě klimatizačn&iacute;ch jednotek a tepeln&yacute;ch čerpadel,<br>pr&aacute;ce na v&yacute;robn&iacute; lince,<br>pracovn&iacute; doba 7,5 hod/denně,<br>pr&aacute;ce ve směnn&eacute;m provozu podm&iacute;nkou.</p>','<p>Z&Scaron;/S&Scaron; vzděl&aacute;n&iacute;,<br>praxe ve v&yacute;robn&iacute; společnosti v&yacute;hodou,<br>manu&aacute;ln&iacute; zručnost,<br>spolehlivost, pracovitost, dodržov&aacute;n&iacute; firemn&iacute;ch pravidel,<br>dobrou znalost česk&eacute;ho jazyka.</p>','<p>n&aacute;stupn&iacute; bonus 10.000 Kč,<br>ročn&iacute; doch&aacute;zkov&yacute; bonus 5.000 Kč,<br>půlročn&iacute; bonusy ve v&yacute;&scaron;i 13. mzdy,<br>věrnostn&iacute; bonusy, program Benefit plus - 6000 Kč/rok,<br>25 - 28 dnů dovolen&eacute;,<br>př&iacute;spěvek na penzijko/životko/DIP,<br>celkem 50 minut přest&aacute;vky,<br>program Multisport,<br>v&yacute;razn&eacute; slevy na firemn&iacute; produkty,<br>dotovan&eacute; stravov&aacute;n&iacute; (v&yacute;běr ze 7 j&iacute;del, cena menu 30 Kč),<br>bufet se &scaron;irok&yacute;m sortimentem a n&aacute;pojov&eacute; automaty,<br>dotovanou svozovou dopravu ze směrů Toužim, Kaznějov, Hol&yacute;&scaron;ov,<br>v&yacute;bornou dostupnost - MHD zast&aacute;vka př&iacute;mo před budovou,<br>důkladn&eacute; za&scaron;kolen&iacute; v tr&eacute;ninkov&eacute;m centru,<br>jistota pr&aacute;ce v čist&eacute;m, modern&iacute;m a bezpečn&eacute;m prostřed&iacute;.</p>');
