INSERT INTO `visitor_job_request` VALUES
('Barbie25Girl',339,'DiS.','Anna','Taliánová','','AnnaTalianova@seznam.cz','+420 731 543 654','<ul>\r\n<li>S&Scaron; zakončen&aacute; maturitou</li>\r\n<li>Obchodn&iacute; Akademie s titulem DiS.</li>\r\n<li>kurz \"Komunikace ve firmě a mimo ni\"</li>\r\n<li>kurz \"Řeč těla aneb jak mluv&iacute;te i když mlč&iacute;te\"</li>\r\n<li>kurz \"PC dovednosti - pokročil&aacute; &uacute;roveň\"</li>\r\n</ul>','<ul>\r\n<li>AJ, NJ pokročil&aacute; &uacute;roveň ověřen&eacute; st&aacute;tn&iacute; zkou&scaron;kou</li>\r\n<li>psan&iacute; v&scaron;emi deseti</li>\r\n<li>znalost podvojn&eacute;ho &uacute;četnictv&iacute;</li>\r\n<li>PC dovednosti pokročil&eacute; &uacute;rovně (kancel&aacute;řsk&yacute; bal&iacute;k MS Word, Excel, Impress; kancel&aacute;řsk&yacute; bal&iacute;k 365 od Microsoftu; d&aacute;le kancel&aacute;řsk&yacute; bal&iacute;k Libre Office, grafick&yacute; program Adobe Photoshop, &uacute;četn&iacute; programy Money a Pohoda)</li>\r\n<li>ŘP B</li>\r\n</ul>\r\n<p>Reference od firem:<br>- Wilhelm Meixner s.r.o. (Česk&eacute; Budějovice)<br>- Smart Business (Plzeň)&nbsp;</p>',NULL,NULL,'2026-01-10 17:08:45'),
