('Irena_Kowalska','Mgr.','Irena','Kowalska','','','<ul>\r\n<li>FST ZČU v Plzni</li>\r\n<li>SOUE v Plzni</li>\r\n<li>z&aacute;kladn&iacute; &scaron;kola</li>\r\n</ul>\r\n<p>Kurzy technick&eacute; angličtiny (pokročil&aacute; &uacute;roveň), technick&eacute; němčiny (z&aacute;kladn&iacute; &uacute;roveň), d&aacute;le kurz hackingu a jak se mu br&aacute;nit, kurz bezpečnosti internetov&eacute;ho rozhran&iacute;, kurz Kyberbezpečnostn&iacute; opatřen&iacute; ve firmě.</p>','<ul>\r\n<li>st&aacute;ž ve firmě Daikin v Plzni</li>\r\n<li>praxe ve firmě NovaTech v Boru u Tachova</li>\r\n<li>odborn&eacute; zku&scaron;enosti ve firmě Novaline s.r.o.</li>\r\n<li>poradenstv&iacute; ve společnosti ProgramSoft v Plzni</li>\r\n<li>veden&iacute; t&yacute;mu technick&eacute; podpory ve firmě Software Ingeneers for future v Praze</li>\r\n</ul>\r\n<p>ŘP B.</p>\r\n<p>T&yacute;mov&yacute; hr&aacute;č, časov&aacute; flexibilita, brainstorming, proz&aacute;kaznick&eacute; jedn&aacute;n&iacute;.</p>',NULL,NULL),
